#define BITSCRAMBLER_TX_CTRL_TX_COND_MODE_POS 4   // write this bit to specify the LOOP instruction condition mode of bitscrambler tx core, 0: use the little than operator to get the condition, 1: use not equal operator to get the condition
#define BITSCRAMBLER_TX_CTRL_TX_COND_MODE_MASK 0x10u
