#define BITSCRAMBLER_TX_CTRL_TX_FETCH_MODE_MASK 0x20u
#define BITSCRAMBLER_TX_CTRL_TX_HALT_MODE_POS 6   // write this bit to set the bitscrambler tx core halt mode when tx_halt is set, 0: wait write data back done, , 1: ignore write data back
#define BITSCRAMBLER_TX_CTRL_TX_HALT_MODE_MASK 0x40u
#define BITSCRAMBLER_TX_CTRL_TX_RD_DUMMY_POS 7   // write this bit to set the bitscrambler tx core read data mode when EOF received.0: wait read data, 1: ignore read data
#define BITSCRAMBLER_TX_CTRL_TX_RD_DUMMY_MASK 0x80u
#define BITSCRAMBLER_TX_CTRL_TX_FIFO_RST_POS 8   // write this bit to reset the bitscrambler tx fifo (write-only)
#define BITSCRAMBLER_TX_CTRL_TX_FIFO_RST_MASK 0x100u

