#define ECC_INT_CLR (*(volatile uint32_t *)0x6008b018ul)
#define ECC_INT_CLR_CALC_DONE_INT_CLR_POS 0   // Write 1 to clear the ECC_CALC_DONE_INT interrupt. (write-only)
