// ECC_CONF: ECC configuration register (read-write, reset 0x00000000)
#define ECC_CONF_ADDRESS 0x6008b01cul
#define ECC_CONF (*(volatile uint32_t *)0x6008b01cul)
#define ECC_CONF_START_POS 0   // Configures whether to start calculation of ECC Accelerator. This bit will be self-cleared after the calculation is done. 0: No effect; 1: Start calculation of ECC Accelerator
#define ECC_CONF_START_MASK 0x1u
#define ECC_CONF_RESET_POS 1   // Configures whether to reset ECC Accelerator. 0: No effect; 1: Reset (write-only)
#define ECC_CONF_RESET_MASK 0x2u
#define ECC_CONF_KEY_LENGTH_POS 2   // Configures the key length mode bit of ECC Accelerator. 0: P-192; 1: P-256; 2: P-384
#define ECC_CONF_KEY_LENGTH_MASK 0xcu
#define ECC_CONF_KEY_LENGTH(value) ((((unsigned long)(value)) << 2) & ECC_CONF_KEY_LENGTH_MASK)
#define ECC_CONF_MOD_BASE_POS 4   // Configures the mod base of mod operation, only valid in work_mode 8-11. 0: n(order of curve); 1: p(mod base of curve)
#define ECC_CONF_MOD_BASE_MASK 0x10u
#define ECC_CONF_WORK_MODE_POS 5   // Configures the work mode of ECC Accelerator. 0: Point Multi mode; 1: Reserved; 2: Point Verif mode; 3: Point Verif + Multi mode; 4: Jacobian Point Multi mode; 5: Reserved; 6: Jacobian Point Verif mode; 7: Point Verif + Jacobian Point Multi mode; 8: Mod Add mode; 9. Mod Sub mode; 10: Mod Multi mode; 11: Mod Div mode
#define ECC_CONF_WORK_MODE_MASK 0x1e0u
#define ECC_CONF_WORK_MODE(value) ((((unsigned long)(value)) << 5) & ECC_CONF_WORK_MODE_MASK)
#define ECC_CONF_SECURITY_MODE_POS 9   // Configures the security mode of ECC Accelerator. 0: no secure function enabled. 1: enable constant-time calculation in all point multiplication modes.
#define ECC_CONF_SECURITY_MODE_MASK 0x200u
#define ECC_CONF_VERIFICATION_RESULT_POS 29   // Represents the verification result of ECC Accelerator, valid only when calculation is done. (read-only)
#define ECC_CONF_VERIFICATION_RESULT_MASK 0x20000000ul
#define ECC_CONF_CLK_EN_POS 30   // Configures whether to force on register clock gate. 0: No effect; 1: Force on
#define ECC_CONF_CLK_EN_MASK 0x40000000ul
#define ECC_CONF_MEM_CLOCK_GATE_FORCE_ON_POS 31   // Configures whether to force on ECC memory clock gate. 0: No effect; 1: Force on
#define ECC_CONF_MEM_CLOCK_GATE_FORCE_ON_MASK 0x80000000ul

