// ---- ECDSA: ECDSA (Elliptic Curve Digital Signature Algorithm) Accelerator

// ECDSA_CONF: ECDSA configure register (read-write, reset 0x00000000)
#define ECDSA_CONF_ADDRESS 0x6008e004ul
#define ECDSA_CONF (*(volatile uint32_t *)0x6008e004ul)
#define ECDSA_CONF_WORK_MODE_POS 0   // The work mode bits of ECDSA Accelerator. 0: Signature Verify Mode. 1: Signature Generate Mode. 2: Export Public Key Mode. 3: invalid.
#define ECDSA_CONF_WORK_MODE_MASK 0x3u
#define ECDSA_CONF_WORK_MODE(value) ((((unsigned long)(value)) << 0) & ECDSA_CONF_WORK_MODE_MASK)
#define ECDSA_CONF_ECC_CURVE_POS 2   // The ecc curve select bit of ECDSA Accelerator. 0: P-192. 1: P-256.
#define ECDSA_CONF_ECC_CURVE_MASK 0x4u
#define ECDSA_CONF_SOFTWARE_SET_K_POS 3   // The source of k select bit. 0: k is automatically generated by hardware. 1: k is written by software.
#define ECDSA_CONF_SOFTWARE_SET_K_MASK 0x8u
#define ECDSA_CONF_SOFTWARE_SET_Z_POS 4   // The source of z select bit. 0: z is generated from SHA result. 1: z is written by software.
#define ECDSA_CONF_SOFTWARE_SET_Z_MASK 0x10u
#define ECDSA_CONF_DETERMINISTIC_K_POS 5   // The source of hardware generated k. 0: k is generated by TRNG. 1: k is generated by deterministic derivation algorithm.
#define ECDSA_CONF_DETERMINISTIC_K_MASK 0x20u
#define ECDSA_CONF_DETERMINISTIC_LOOP_POS 6   // The (loop number - 1) value in the deterministic derivation algorithm to derive k.
#define ECDSA_CONF_DETERMINISTIC_LOOP_MASK 0x3fffc0ul
#define ECDSA_CONF_DETERMINISTIC_LOOP(value) ((((unsigned long)(value)) << 6) & ECDSA_CONF_DETERMINISTIC_LOOP_MASK)

// ECDSA_CLK: ECDSA clock gate register (read-write, reset 0x00000000)
#define ECDSA_CLK_ADDRESS 0x6008e008ul
#define ECDSA_CLK (*(volatile uint32_t *)0x6008e008ul)
#define ECDSA_CLK_GATE_FORCE_ON_POS 0   // Write 1 to force on register clock gate.
#define ECDSA_CLK_GATE_FORCE_ON_MASK 0x1u

// ECDSA_INT_RAW: ECDSA interrupt raw register, valid in level. (read-write, reset 0x00000000)
#define ECDSA_INT_RAW_ADDRESS 0x6008e00cul
#define ECDSA_INT_RAW (*(volatile uint32_t *)0x6008e00cul)
#define ECDSA_INT_RAW_PREP_DONE_INT_RAW_POS 0   // The raw interrupt status bit for the ecdsa_prep_done_int interrupt (read-only)
#define ECDSA_INT_RAW_PREP_DONE_INT_RAW_MASK 0x1u
#define ECDSA_INT_RAW_PROC_DONE_INT_RAW_POS 1   // The raw interrupt status bit for the ecdsa_proc_done_int interrupt (read-only)
#define ECDSA_INT_RAW_PROC_DONE_INT_RAW_MASK 0x2u
#define ECDSA_INT_RAW_POST_DONE_INT_RAW_POS 2   // The raw interrupt status bit for the ecdsa_post_done_int interrupt (read-only)
#define ECDSA_INT_RAW_POST_DONE_INT_RAW_MASK 0x4u
#define ECDSA_INT_RAW_SHA_RELEASE_INT_RAW_POS 3   // The raw interrupt status bit for the ecdsa_sha_release_int interrupt (read-only)
#define ECDSA_INT_RAW_SHA_RELEASE_INT_RAW_MASK 0x8u

// ECDSA_INT_ST: ECDSA interrupt status register. (read-write, reset 0x00000000)
#define ECDSA_INT_ST_ADDRESS 0x6008e010ul
#define ECDSA_INT_ST (*(volatile uint32_t *)0x6008e010ul)
#define ECDSA_INT_ST_PREP_DONE_INT_ST_POS 0   // The masked interrupt status bit for the ecdsa_prep_done_int interrupt (read-only)
#define ECDSA_INT_ST_PREP_DONE_INT_ST_MASK 0x1u
#define ECDSA_INT_ST_PROC_DONE_INT_ST_POS 1   // The masked interrupt status bit for the ecdsa_proc_done_int interrupt (read-only)
#define ECDSA_INT_ST_PROC_DONE_INT_ST_MASK 0x2u
#define ECDSA_INT_ST_POST_DONE_INT_ST_POS 2   // The masked interrupt status bit for the ecdsa_post_done_int interrupt (read-only)
#define ECDSA_INT_ST_POST_DONE_INT_ST_MASK 0x4u
#define ECDSA_INT_ST_SHA_RELEASE_INT_ST_POS 3   // The masked interrupt status bit for the ecdsa_sha_release_int interrupt (read-only)
#define ECDSA_INT_ST_SHA_RELEASE_INT_ST_MASK 0x8u

// ECDSA_INT_ENA: ECDSA interrupt enable register. (read-write, reset 0x00000000)
#define ECDSA_INT_ENA_ADDRESS 0x6008e014ul
#define ECDSA_INT_ENA (*(volatile uint32_t *)0x6008e014ul)
#define ECDSA_INT_ENA_PREP_DONE_INT_ENA_POS 0   // The interrupt enable bit for the ecdsa_prep_done_int interrupt
#define ECDSA_INT_ENA_PREP_DONE_INT_ENA_MASK 0x1u
#define ECDSA_INT_ENA_PROC_DONE_INT_ENA_POS 1   // The interrupt enable bit for the ecdsa_proc_done_int interrupt
#define ECDSA_INT_ENA_PROC_DONE_INT_ENA_MASK 0x2u
#define ECDSA_INT_ENA_POST_DONE_INT_ENA_POS 2   // The interrupt enable bit for the ecdsa_post_done_int interrupt
#define ECDSA_INT_ENA_POST_DONE_INT_ENA_MASK 0x4u
#define ECDSA_INT_ENA_SHA_RELEASE_INT_ENA_POS 3   // The interrupt enable bit for the ecdsa_sha_release_int interrupt
#define ECDSA_INT_ENA_SHA_RELEASE_INT_ENA_MASK 0x8u

// ECDSA_INT_CLR: ECDSA interrupt clear register. (read-write, reset 0x00000000)
#define ECDSA_INT_CLR_ADDRESS 0x6008e018ul
#define ECDSA_INT_CLR (*(volatile uint32_t *)0x6008e018ul)
#define ECDSA_INT_CLR_PREP_DONE_INT_CLR_POS 0   // Set this bit to clear the ecdsa_prep_done_int interrupt (write-only)
#define ECDSA_INT_CLR_PREP_DONE_INT_CLR_MASK 0x1u
#define ECDSA_INT_CLR_PROC_DONE_INT_CLR_POS 1   // Set this bit to clear the ecdsa_proc_done_int interrupt (write-only)
#define ECDSA_INT_CLR_PROC_DONE_INT_CLR_MASK 0x2u
#define ECDSA_INT_CLR_POST_DONE_INT_CLR_POS 2   // Set this bit to clear the ecdsa_post_done_int interrupt (write-only)
#define ECDSA_INT_CLR_POST_DONE_INT_CLR_MASK 0x4u
#define ECDSA_INT_CLR_SHA_RELEASE_INT_CLR_POS 3   // Set this bit to clear the ecdsa_sha_release_int interrupt (write-only)
#define ECDSA_INT_CLR_SHA_RELEASE_INT_CLR_MASK 0x8u

// ECDSA_START: ECDSA start register (read-write, reset 0x00000000)
#define ECDSA_START_ADDRESS 0x6008e01cul
#define ECDSA_START (*(volatile uint32_t *)0x6008e01cul)
#define ECDSA_START_START_POS 0   // Write 1 to start caculation of ECDSA Accelerator. This bit will be self-cleared after configuration. (write-only)
#define ECDSA_START_START_MASK 0x1u
#define ECDSA_START_LOAD_DONE_POS 1   // Write 1 to input load done signal of ECDSA Accelerator. This bit will be self-cleared after configuration. (write-only)
#define ECDSA_START_LOAD_DONE_MASK 0x2u
#define ECDSA_START_GET_DONE_POS 2   // Write 1 to input get done signal of ECDSA Accelerator. This bit will be self-cleared after configuration. (write-only)
#define ECDSA_START_GET_DONE_MASK 0x4u

// ECDSA_STATE: ECDSA status register (read-write, reset 0x00000000)
#define ECDSA_STATE_ADDRESS 0x6008e020ul
#define ECDSA_STATE (*(volatile uint32_t *)0x6008e020ul)
#define ECDSA_STATE_BUSY_POS 0   // The status bits of ECDSA Accelerator. ECDSA is at 0: IDLE, 1: LOAD, 2: GET, 3: BUSY state. (read-only)
#define ECDSA_STATE_BUSY_MASK 0x3u
#define ECDSA_STATE_BUSY(value) ((((unsigned long)(value)) << 0) & ECDSA_STATE_BUSY_MASK)

// ECDSA_RESULT: ECDSA result register (read-write, reset 0x00000000)
#define ECDSA_RESULT_ADDRESS 0x6008e024ul
#define ECDSA_RESULT (*(volatile uint32_t *)0x6008e024ul)
#define ECDSA_RESULT_OPERATION_RESULT_POS 0   // The operation result bit of ECDSA Accelerator, only valid when ECDSA calculation is done. (read-only)
#define ECDSA_RESULT_OPERATION_RESULT_MASK 0x1u
#define ECDSA_RESULT_K_VALUE_WARNING_POS 1   // The k value warning bit of ECDSA Accelerator, valid when k value is bigger than the curve order, then actually taken k = k mod n. (read-only)
#define ECDSA_RESULT_K_VALUE_WARNING_MASK 0x2u

// ECDSA_DATE: Version control register (read-write, reset 0x02306130)
#define ECDSA_DATE_ADDRESS 0x6008e0fcul
#define ECDSA_DATE (*(volatile uint32_t *)0x6008e0fcul)
#define ECDSA_DATE_DATE_POS 0   // ECDSA version control register
#define ECDSA_DATE_DATE_MASK 0xffffffful
#define ECDSA_DATE_DATE(value) ((((unsigned long)(value)) << 0) & ECDSA_DATE_DATE_MASK)

// ECDSA_SHA_MODE: ECDSA control SHA register (read-write, reset 0x00000000)
