#define GPIO_EXT_INT_ENA (*(volatile uint32_t *)0x60091fd8ul)
#define GPIO_EXT_INT_ENA_COMP_NEG_0_INT_ENA_POS 0   // analog comparator pos edge interrupt enable
#define GPIO_EXT_INT_ENA_COMP_NEG_0_INT_ENA_MASK 0x1u
#define GPIO_EXT_INT_ENA_COMP_POS_0_INT_ENA_POS 1   // analog comparator neg edge interrupt enable
#define GPIO_EXT_INT_ENA_COMP_POS_0_INT_ENA_MASK 0x2u
#define GPIO_EXT_INT_ENA_COMP_ALL_0_INT_ENA_POS 2   // analog comparator neg or pos edge interrupt enable
#define GPIO_EXT_INT_ENA_COMP_ALL_0_INT_ENA_MASK 0x4u

// GPIO_EXT_INT_CLR: GPIO_EXT interrupt clear register (read-write, reset 0x00000000)
#define GPIO_EXT_INT_CLR_ADDRESS 0x60091fdcul
#define GPIO_EXT_INT_CLR (*(volatile uint32_t *)0x60091fdcul)
#define GPIO_EXT_INT_CLR_COMP_NEG_0_INT_CLR_POS 0   // analog comparator pos edge interrupt clear (write-only)
#define GPIO_EXT_INT_CLR_COMP_NEG_0_INT_CLR_MASK 0x1u
#define GPIO_EXT_INT_CLR_COMP_POS_0_INT_CLR_POS 1   // analog comparator neg edge interrupt clear (write-only)
#define GPIO_EXT_INT_CLR_COMP_POS_0_INT_CLR_MASK 0x2u
#define GPIO_EXT_INT_CLR_COMP_ALL_0_INT_CLR_POS 2   // analog comparator neg or pos edge interrupt clear (write-only)
#define GPIO_EXT_INT_CLR_COMP_ALL_0_INT_CLR_MASK 0x4u

// GPIO_EXT_PIN_CTRL: Clock Output Configuration Register (read-write, reset 0x00000000)
#define GPIO_EXT_PIN_CTRL_ADDRESS 0x60091fe0ul
#define GPIO_EXT_PIN_CTRL (*(volatile uint32_t *)0x60091fe0ul)
#define GPIO_EXT_PIN_CTRL_CLK_OUT1_POS 0   // If you want to output clock for I2S to CLK_OUT_out1, set this register to 0x0. CLK_OUT_out1 can be found in peripheral output signals.
#define GPIO_EXT_PIN_CTRL_CLK_OUT1_MASK 0x1fu
#define GPIO_EXT_PIN_CTRL_CLK_OUT1(value) ((((unsigned long)(value)) << 0) & GPIO_EXT_PIN_CTRL_CLK_OUT1_MASK)
#define GPIO_EXT_PIN_CTRL_CLK_OUT2_POS 5   // If you want to output clock for I2S to CLK_OUT_out2, set this register to 0x0. CLK_OUT_out2 can be found in peripheral output signals.
#define GPIO_EXT_PIN_CTRL_CLK_OUT2_MASK 0x3e0u
#define GPIO_EXT_PIN_CTRL_CLK_OUT2(value) ((((unsigned long)(value)) << 5) & GPIO_EXT_PIN_CTRL_CLK_OUT2_MASK)
#define GPIO_EXT_PIN_CTRL_CLK_OUT3_POS 10   // If you want to output clock for I2S to CLK_OUT_out3, set this register to 0x0. CLK_OUT_out3 can be found in peripheral output signals.
#define GPIO_EXT_PIN_CTRL_CLK_OUT3_MASK 0x7c00u
#define GPIO_EXT_PIN_CTRL_CLK_OUT3(value) ((((unsigned long)(value)) << 10) & GPIO_EXT_PIN_CTRL_CLK_OUT3_MASK)

