// ---- I2C0: I2C (Inter-Integrated Circuit) Controller 0

// I2C0_SCL_LOW_PERIOD: Configures the low level width of the SCL Clock (read-write, reset 0x00000000)
#define I2C0_SCL_LOW_PERIOD_ADDRESS 0x60004000ul
#define I2C0_SCL_LOW_PERIOD (*(volatile uint32_t *)0x60004000ul)
#define I2C0_SCL_LOW_PERIOD_SCL_LOW_PERIOD_POS 0   // Configures the low level width of the SCL Clock in master mode. Measurement unit: i2c_sclk
#define I2C0_SCL_LOW_PERIOD_SCL_LOW_PERIOD_MASK 0x1ffu
#define I2C0_SCL_LOW_PERIOD_SCL_LOW_PERIOD(value) ((((unsigned long)(value)) << 0) & I2C0_SCL_LOW_PERIOD_SCL_LOW_PERIOD_MASK)

// I2C0_CTR: Transmission setting (read-write, reset 0x00000208)
#define I2C0_CTR_ADDRESS 0x60004004ul
#define I2C0_CTR (*(volatile uint32_t *)0x60004004ul)
#define I2C0_CTR_SDA_FORCE_OUT_POS 0   // Configures the SDA output mode. 0: Open drain output; 1: Direct output
#define I2C0_CTR_SDA_FORCE_OUT_MASK 0x1u
#define I2C0_CTR_SCL_FORCE_OUT_POS 1   // Configures the SCL output mode. 0: Open drain output; 1: Direct output
#define I2C0_CTR_SCL_FORCE_OUT_MASK 0x2u
#define I2C0_CTR_SAMPLE_SCL_LEVEL_POS 2   // Configures the sample mode for SDA. 0: Sample SDA data on the SCL high level; 1: Sample SDA data on the SCL low level
#define I2C0_CTR_SAMPLE_SCL_LEVEL_MASK 0x4u
#define I2C0_CTR_RX_FULL_ACK_LEVEL_POS 3   // Configures the ACK value that needs to be sent by master when the rx_fifo_cnt has reached the threshold.
#define I2C0_CTR_RX_FULL_ACK_LEVEL_MASK 0x8u
#define I2C0_CTR_MS_MODE_POS 4   // Configures the module as an I2C Master or Slave. 0: Slave; 1: Master
#define I2C0_CTR_MS_MODE_MASK 0x10u
#define I2C0_CTR_TRANS_START_POS 5   // Configures whether the slave starts sending the data in txfifo. 0: No effect; 1: Start (write-only)
#define I2C0_CTR_TRANS_START_MASK 0x20u
#define I2C0_CTR_TX_LSB_FIRST_POS 6   // Configures to control the sending order for data needing to be sent. 0: send data from the most significant bit; 1: send data from the least significant bit
#define I2C0_CTR_TX_LSB_FIRST_MASK 0x40u
#define I2C0_CTR_RX_LSB_FIRST_POS 7   // Configures to control the storage order for received data. 0: receive data from the most significant bit; 1: receive data from the least significant bit
#define I2C0_CTR_RX_LSB_FIRST_MASK 0x80u
#define I2C0_CTR_CLK_EN_POS 8   // Configures whether to gate clock signal for registers. 0: Support clock only when registers are read or written to by software; 1: Force clock on for registers
#define I2C0_CTR_CLK_EN_MASK 0x100u
#define I2C0_CTR_ARBITRATION_EN_POS 9   // Configures to enable I2C bus arbitration detection. 0: No effect; 1: Enable
#define I2C0_CTR_ARBITRATION_EN_MASK 0x200u
#define I2C0_CTR_FSM_RST_POS 10   // Configures to reset the SCL_FSM. 0: No effect; 1: Reset (write-only)
#define I2C0_CTR_FSM_RST_MASK 0x400u
#define I2C0_CTR_CONF_UPGATE_POS 11   // Configures this bit for synchronization. 0: No effect; 1: Synchronize (write-only)
#define I2C0_CTR_CONF_UPGATE_MASK 0x800u
#define I2C0_CTR_SLV_TX_AUTO_START_EN_POS 12   // Configures to enable slave to send data automatically; 0: Disable; 1: Enable
#define I2C0_CTR_SLV_TX_AUTO_START_EN_MASK 0x1000u
#define I2C0_CTR_ADDR_10BIT_RW_CHECK_EN_POS 13   // Configures to check if the r/w bit of 10bit addressing consists with I2C protocol. 0: Not check; 1: Check
#define I2C0_CTR_ADDR_10BIT_RW_CHECK_EN_MASK 0x2000u
#define I2C0_CTR_ADDR_BROADCASTING_EN_POS 14   // Configures to support the 7 bit general call function. 0: Not support; 1: Support
#define I2C0_CTR_ADDR_BROADCASTING_EN_MASK 0x4000u

// I2C0_SR: Describe I2C work status (read-write, reset 0x0000c000)
#define I2C0_SR_ADDRESS 0x60004008ul
#define I2C0_SR (*(volatile uint32_t *)0x60004008ul)
#define I2C0_SR_RESP_REC_POS 0   // Represents the received ACK value in master mode or slave mode. 0: ACK; 1: NACK. (read-only)
#define I2C0_SR_RESP_REC_MASK 0x1u
#define I2C0_SR_SLAVE_RW_POS 1   // Represents the transfer direction in slave mode. 1: Master reads from slave; 0: Master writes to slave. (read-only)
#define I2C0_SR_SLAVE_RW_MASK 0x2u
#define I2C0_SR_ARB_LOST_POS 3   // Represents whether the I2C controller loses control of SCL line. 0: No arbitration lost; 1: Arbitration lost (read-only)
#define I2C0_SR_ARB_LOST_MASK 0x8u
#define I2C0_SR_BUS_BUSY_POS 4   // Represents the I2C bus state. 1: The I2C bus is busy transferring data; 0: The I2C bus is in idle state. (read-only)
#define I2C0_SR_BUS_BUSY_MASK 0x10u
#define I2C0_SR_SLAVE_ADDRESSED_POS 5   // Represents whether the address sent by the master is equal to the address of the slave. Valid only when the module is configured as an I2C Slave. 0: Not equal; 1: Equal (read-only)
#define I2C0_SR_SLAVE_ADDRESSED_MASK 0x20u
#define I2C0_SR_RXFIFO_CNT_POS 8   // Represents the number of data bytes received in RAM. (read-only)
#define I2C0_SR_RXFIFO_CNT_MASK 0x3f00u
#define I2C0_SR_RXFIFO_CNT(value) ((((unsigned long)(value)) << 8) & I2C0_SR_RXFIFO_CNT_MASK)
#define I2C0_SR_STRETCH_CAUSE_POS 14   // Represents the cause of SCL clocking stretching in slave mode. 0: Stretching SCL low when the master starts to read data. 1: Stretching SCL low when I2C TX FIFO is empty in slave mode. 2: Stretching SCL low when I2C RX FIFO is full in slave mode. (read-only)
#define I2C0_SR_STRETCH_CAUSE_MASK 0xc000u
#define I2C0_SR_STRETCH_CAUSE(value) ((((unsigned long)(value)) << 14) & I2C0_SR_STRETCH_CAUSE_MASK)
#define I2C0_SR_TXFIFO_CNT_POS 18   // Represents the number of data bytes to be sent. (read-only)
#define I2C0_SR_TXFIFO_CNT_MASK 0xfc0000ul
#define I2C0_SR_TXFIFO_CNT(value) ((((unsigned long)(value)) << 18) & I2C0_SR_TXFIFO_CNT_MASK)
#define I2C0_SR_SCL_MAIN_STATE_LAST_POS 24   // Represents the states of the I2C module state machine. 0: Idle; 1: Address shift; 2: ACK address; 3: Rx data; 4: Tx data; 5: Send ACK; 6: Wait ACK (read-only)
#define I2C0_SR_SCL_MAIN_STATE_LAST_MASK 0x7000000ul
#define I2C0_SR_SCL_MAIN_STATE_LAST(value) ((((unsigned long)(value)) << 24) & I2C0_SR_SCL_MAIN_STATE_LAST_MASK)
#define I2C0_SR_SCL_STATE_LAST_POS 28   // Represents the states of the state machine used to produce SCL. 0: Idle; 1: Start; 2: Negative edge; 3: Low; 4: Positive edge; 5: High; 6: Stop (read-only)
#define I2C0_SR_SCL_STATE_LAST_MASK 0x70000000ul
#define I2C0_SR_SCL_STATE_LAST(value) ((((unsigned long)(value)) << 28) & I2C0_SR_SCL_STATE_LAST_MASK)

// I2C0_TO: Setting time out control for receiving data (read-write, reset 0x00000010)
#define I2C0_TO_ADDRESS 0x6000400cul
#define I2C0_TO (*(volatile uint32_t *)0x6000400cul)
#define I2C0_TO_TIME_OUT_VALUE_POS 0   // Configures the timeout threshold period for SCL stucking at high or low level. The actual period is 2\^{}(reg_time_out_value). Measurement unit: i2c_sclk
#define I2C0_TO_TIME_OUT_VALUE_MASK 0x1fu
#define I2C0_TO_TIME_OUT_VALUE(value) ((((unsigned long)(value)) << 0) & I2C0_TO_TIME_OUT_VALUE_MASK)
#define I2C0_TO_TIME_OUT_EN_POS 5   // Configures to enable time out control. 0: No effect; 1: Enable
#define I2C0_TO_TIME_OUT_EN_MASK 0x20u

// I2C0_SLAVE_ADDR: Local slave address setting (read-write, reset 0x00000000)
#define I2C0_SLAVE_ADDR_ADDRESS 0x60004010ul
#define I2C0_SLAVE_ADDR (*(volatile uint32_t *)0x60004010ul)
#define I2C0_SLAVE_ADDR_SLAVE_ADDR_POS 0   // Configure the slave address of I2C Slave.
#define I2C0_SLAVE_ADDR_SLAVE_ADDR_MASK 0x7fffu
#define I2C0_SLAVE_ADDR_SLAVE_ADDR(value) ((((unsigned long)(value)) << 0) & I2C0_SLAVE_ADDR_SLAVE_ADDR_MASK)
#define I2C0_SLAVE_ADDR_ADDR_10BIT_EN_POS 31   // Configures to enable the slave 10-bit addressing mode in master mode. 0: No effect; 1: Enable
#define I2C0_SLAVE_ADDR_ADDR_10BIT_EN_MASK 0x80000000ul

// I2C0_FIFO_ST: FIFO status register (read-write, reset 0x00000000)
#define I2C0_FIFO_ST_ADDRESS 0x60004014ul
#define I2C0_FIFO_ST (*(volatile uint32_t *)0x60004014ul)
#define I2C0_FIFO_ST_RXFIFO_RADDR_POS 0   // Represents the offset address of the APB reading from RXFIFO. (read-only)
#define I2C0_FIFO_ST_RXFIFO_RADDR_MASK 0x1fu
#define I2C0_FIFO_ST_RXFIFO_RADDR(value) ((((unsigned long)(value)) << 0) & I2C0_FIFO_ST_RXFIFO_RADDR_MASK)
#define I2C0_FIFO_ST_RXFIFO_WADDR_POS 5   // Represents the offset address of i2c module receiving data and writing to RXFIFO. (read-only)
#define I2C0_FIFO_ST_RXFIFO_WADDR_MASK 0x3e0u
#define I2C0_FIFO_ST_RXFIFO_WADDR(value) ((((unsigned long)(value)) << 5) & I2C0_FIFO_ST_RXFIFO_WADDR_MASK)
#define I2C0_FIFO_ST_TXFIFO_RADDR_POS 10   // Represents the offset address of i2c module reading from TXFIFO. (read-only)
#define I2C0_FIFO_ST_TXFIFO_RADDR_MASK 0x7c00u
#define I2C0_FIFO_ST_TXFIFO_RADDR(value) ((((unsigned long)(value)) << 10) & I2C0_FIFO_ST_TXFIFO_RADDR_MASK)
#define I2C0_FIFO_ST_TXFIFO_WADDR_POS 15   // Represents the offset address of APB bus writing to TXFIFO. (read-only)
#define I2C0_FIFO_ST_TXFIFO_WADDR_MASK 0xf8000ul
#define I2C0_FIFO_ST_TXFIFO_WADDR(value) ((((unsigned long)(value)) << 15) & I2C0_FIFO_ST_TXFIFO_WADDR_MASK)
#define I2C0_FIFO_ST_SLAVE_RW_POINT_POS 22   // Represents the offset address in the I2C Slave RAM addressed by I2C Master when in I2C slave mode. (read-only)
#define I2C0_FIFO_ST_SLAVE_RW_POINT_MASK 0x3fc00000ul
#define I2C0_FIFO_ST_SLAVE_RW_POINT(value) ((((unsigned long)(value)) << 22) & I2C0_FIFO_ST_SLAVE_RW_POINT_MASK)

// I2C0_FIFO_CONF: FIFO configuration register (read-write, reset 0x0000408b)
#define I2C0_FIFO_CONF_ADDRESS 0x60004018ul
#define I2C0_FIFO_CONF (*(volatile uint32_t *)0x60004018ul)
#define I2C0_FIFO_CONF_RXFIFO_WM_THRHD_POS 0   // Configures the water mark threshold of RXFIFO in nonfifo access mode. When I2C_FIFO_PRT_EN is 1 and RX FIFO counter is bigger than I2C_RXFIFO_WM_THRHD[4:0], I2C_RXFIFO_WM_INT_RAW bit will be valid. \tododone{For CJ, please check this description. I habe doubt about reg_reg_fifo_prt_en.CJ: modified}
#define I2C0_FIFO_CONF_RXFIFO_WM_THRHD_MASK 0x1fu
#define I2C0_FIFO_CONF_RXFIFO_WM_THRHD(value) ((((unsigned long)(value)) << 0) & I2C0_FIFO_CONF_RXFIFO_WM_THRHD_MASK)
#define I2C0_FIFO_CONF_TXFIFO_WM_THRHD_POS 5   // Configures the water mark threshold of TXFIFO in nonfifo access mode. When I2C_FIFO_PRT_EN is 1 and TC FIFO counter is bigger than I2C_TXFIFO_WM_THRHD[4:0], I2C_TXFIFO_WM_INT_RAW bit will be valid.
#define I2C0_FIFO_CONF_TXFIFO_WM_THRHD_MASK 0x3e0u
#define I2C0_FIFO_CONF_TXFIFO_WM_THRHD(value) ((((unsigned long)(value)) << 5) & I2C0_FIFO_CONF_TXFIFO_WM_THRHD_MASK)
#define I2C0_FIFO_CONF_NONFIFO_EN_POS 10   // Configures to enable APB nonfifo access.
#define I2C0_FIFO_CONF_NONFIFO_EN_MASK 0x400u
#define I2C0_FIFO_CONF_FIFO_ADDR_CFG_EN_POS 11   // Configures the slave to enable dual address mode. When this mode is enabled, the byte received after the I2C address byte represents the offset address in the I2C Slave RAM. 0: Disable; 1: Enable
#define I2C0_FIFO_CONF_FIFO_ADDR_CFG_EN_MASK 0x800u
#define I2C0_FIFO_CONF_RX_FIFO_RST_POS 12   // Configures to reset RXFIFO. 0: No effect; 1: Reset
#define I2C0_FIFO_CONF_RX_FIFO_RST_MASK 0x1000u
#define I2C0_FIFO_CONF_TX_FIFO_RST_POS 13   // Configures to reset TXFIFO. 0: No effect; 1: Reset
#define I2C0_FIFO_CONF_TX_FIFO_RST_MASK 0x2000u
#define I2C0_FIFO_CONF_FIFO_PRT_EN_POS 14   // Configures to enable FIFO pointer in non-fifo access mode. This bit controls the valid bits and the TX/RX FIFO overflow, underflow, full and empty interrupts. 0: No effect; 1: Enable
#define I2C0_FIFO_CONF_FIFO_PRT_EN_MASK 0x4000u

// I2C0_DATA: Rx FIFO read data (read-write, reset 0x00000000)
#define I2C0_DATA_ADDRESS 0x6000401cul
#define I2C0_DATA (*(volatile uint32_t *)0x6000401cul)
#define I2C0_DATA_FIFO_RDATA_POS 0   // Represents the value of RXFIFO read data. (read-only)
#define I2C0_DATA_FIFO_RDATA_MASK 0xffu
#define I2C0_DATA_FIFO_RDATA(value) ((((unsigned long)(value)) << 0) & I2C0_DATA_FIFO_RDATA_MASK)

// I2C0_INT_RAW: Raw interrupt status (read-write, reset 0x00000002)
#define I2C0_INT_RAW_ADDRESS 0x60004020ul
#define I2C0_INT_RAW (*(volatile uint32_t *)0x60004020ul)
#define I2C0_INT_RAW_RXFIFO_WM_INT_RAW_POS 0   // The raw interrupt status of I2C_RXFIFO_WM_INT interrupt. (read-only)
#define I2C0_INT_RAW_RXFIFO_WM_INT_RAW_MASK 0x1u
