// I2S0_RX_CONF: I2S RX configure register (read-write, reset 0x00c0b600)
#define I2S0_RX_CONF_ADDRESS 0x6000c020ul
#define I2S0_RX_CONF (*(volatile uint32_t *)0x6000c020ul)
#define I2S0_RX_CONF_RX_RESET_POS 0   // Set this bit to reset receiver (write-only)
#define I2S0_RX_CONF_RX_RESET_MASK 0x1u
#define I2S0_RX_CONF_RX_FIFO_RESET_POS 1   // Set this bit to reset Rx AFIFO (write-only)
#define I2S0_RX_CONF_RX_FIFO_RESET_MASK 0x2u
#define I2S0_RX_CONF_RX_START_POS 2   // Set this bit to start receiving data
#define I2S0_RX_CONF_RX_START_MASK 0x4u
#define I2S0_RX_CONF_RX_SLAVE_MOD_POS 3   // Set this bit to enable slave receiver mode
#define I2S0_RX_CONF_RX_SLAVE_MOD_MASK 0x8u
#define I2S0_RX_CONF_RX_STOP_MODE_POS 4   // 0 : I2S Rx only stop when reg_rx_start is cleared. 1: Stop when reg_rx_start is 0 or in_suc_eof is 1. 2: Stop I2S RX when reg_rx_start is 0 or RX FIFO is full.
#define I2S0_RX_CONF_RX_STOP_MODE_MASK 0x30u
#define I2S0_RX_CONF_RX_STOP_MODE(value) ((((unsigned long)(value)) << 4) & I2S0_RX_CONF_RX_STOP_MODE_MASK)
#define I2S0_RX_CONF_RX_MONO_POS 6   // Set this bit to enable receiver in mono mode
#define I2S0_RX_CONF_RX_MONO_MASK 0x40u
#define I2S0_RX_CONF_RX_BIG_ENDIAN_POS 7   // I2S Rx byte endian, 1: low addr value to high addr. 0: low addr with low addr value.
#define I2S0_RX_CONF_RX_BIG_ENDIAN_MASK 0x80u
#define I2S0_RX_CONF_RX_UPDATE_POS 8   // Set 1 to update I2S RX registers from APB clock domain to I2S RX clock domain. This bit will be cleared by hardware after update register done.
#define I2S0_RX_CONF_RX_UPDATE_MASK 0x100u
#define I2S0_RX_CONF_RX_MONO_FST_VLD_POS 9   // 1: The first channel data value is valid in I2S RX mono mode. 0: The second channel data value is valid in I2S RX mono mode.
#define I2S0_RX_CONF_RX_MONO_FST_VLD_MASK 0x200u
#define I2S0_RX_CONF_RX_PCM_CONF_POS 10   // I2S RX compress/decompress configuration bit. & 0 (atol): A-Law decompress, 1 (ltoa) : A-Law compress, 2 (utol) : u-Law decompress, 3 (ltou) : u-Law compress. &
#define I2S0_RX_CONF_RX_PCM_CONF_MASK 0xc00u
#define I2S0_RX_CONF_RX_PCM_CONF(value) ((((unsigned long)(value)) << 10) & I2S0_RX_CONF_RX_PCM_CONF_MASK)
#define I2S0_RX_CONF_RX_PCM_BYPASS_POS 12   // Set this bit to bypass Compress/Decompress module for received data.
#define I2S0_RX_CONF_RX_PCM_BYPASS_MASK 0x1000u
#define I2S0_RX_CONF_RX_MSB_SHIFT_POS 13   // Set this bit to enable receiver in Phillips standard mode
#define I2S0_RX_CONF_RX_MSB_SHIFT_MASK 0x2000u
#define I2S0_RX_CONF_RX_DONE_MODE_POS 14   // 1: I2S trigger rx_done when in_suc_eof is 1. 0: I2S trigger rx_done when RX FIFO is full.
#define I2S0_RX_CONF_RX_DONE_MODE_MASK 0x4000u
