#define IO_MUX_GPIO0_MCU_OE_POS 0   // Configures whether or not to enable the output of GPIO%s in sleep mode. 0: Disable; 1: Enable
#define IO_MUX_GPIO0_MCU_OE_MASK 0x1u
#define IO_MUX_GPIO0_SLP_SEL_POS 1   // Configures whether or not to enter sleep mode for GPIO%s. 0: Not enter; 1: Enter
#define IO_MUX_GPIO0_SLP_SEL_MASK 0x2u
#define IO_MUX_GPIO0_MCU_WPD_POS 2   // Configure whether or not to enable pull-down resistor of GPIO%s in sleep mode. 0: Disable; 1: Enable
#define IO_MUX_GPIO0_MCU_WPD_MASK 0x4u
#define IO_MUX_GPIO0_MCU_WPU_POS 3   // Configures whether or not to enable pull-up resistor of GPIO%s during sleep mode. 0: Disable; 1: Enable
#define IO_MUX_GPIO0_MCU_WPU_MASK 0x8u
#define IO_MUX_GPIO0_MCU_IE_POS 4   // Configures whether or not to enable the input of GPIO%s during sleep mode. 0: Disable; 1: Enable
#define IO_MUX_GPIO0_MCU_IE_MASK 0x10u
#define IO_MUX_GPIO0_MCU_DRV_POS 5   // Configures the drive strength of GPIO%s during sleep mode. 0: ~5 mA; 1: ~10 mA; 2: ~20 mA; 3: ~40 mA
#define IO_MUX_GPIO0_MCU_DRV_MASK 0x60u
#define IO_MUX_GPIO0_MCU_DRV(value) ((((unsigned long)(value)) << 5) & IO_MUX_GPIO0_MCU_DRV_MASK)
#define IO_MUX_GPIO0_FUN_WPD_POS 7   // Configures whether or not to enable pull-down resistor of GPIO%s. 0: Disable; 1: Enable
#define IO_MUX_GPIO0_FUN_WPD_MASK 0x80u
#define IO_MUX_GPIO0_FUN_WPU_POS 8   // Configures whether or not enable pull-up resistor of GPIO%s. 0: Disable; 1: Enable
#define IO_MUX_GPIO0_FUN_WPU_MASK 0x100u
#define IO_MUX_GPIO0_FUN_IE_POS 9   // Configures whether or not to enable input of GPIO%s. 0: Disable; 1: Enable
#define IO_MUX_GPIO0_FUN_IE_MASK 0x200u
#define IO_MUX_GPIO0_FUN_DRV_POS 10   // Configures the drive strength of GPIO%s. 0: ~5 mA; 1: ~10 mA; 2: ~20 mA; 3: ~40 mA
#define IO_MUX_GPIO0_FUN_DRV_MASK 0xc00u
#define IO_MUX_GPIO0_FUN_DRV(value) ((((unsigned long)(value)) << 10) & IO_MUX_GPIO0_FUN_DRV_MASK)
#define IO_MUX_GPIO0_MCU_SEL_POS 12   // Configures to select IO MUX function for this signal. 0: Select Function 0; 1: Select Function 1; ......
#define IO_MUX_GPIO0_MCU_SEL_MASK 0x7000u
#define IO_MUX_GPIO0_MCU_SEL(value) ((((unsigned long)(value)) << 12) & IO_MUX_GPIO0_MCU_SEL_MASK)
#define IO_MUX_GPIO0_FILTER_EN_POS 15   // Configures whether or not to enable filter for pin input signals. 0: Disable; 1: Enable
#define IO_MUX_GPIO0_FILTER_EN_MASK 0x8000u
#define IO_MUX_GPIO0_HYS_EN_POS 16   // Configures whether or not to enable the hysteresis function of the pin when IO_MUX_GPIO%s_HYS_SEL is set to 1. 0: Disable; 1: Enable
#define IO_MUX_GPIO0_HYS_EN_MASK 0x10000ul
#define IO_MUX_GPIO0_HYS_SEL_POS 17   // Configures to choose the signal for enabling the hysteresis function for GPIO%s. 0: Choose the output enable signal of eFuse; 1: Choose the output enable signal of IO_MUX_GPIO%s_HYS_EN
#define IO_MUX_GPIO0_HYS_SEL_MASK 0x20000ul

