// ---- KEYMNG: KEYMNG Peripheral

// KEYMNG_CLK: Key Manager clock gate control register (read-write, reset 0x00000001)
#define KEYMNG_CLK_ADDRESS 0x60087004ul
#define KEYMNG_CLK (*(volatile uint32_t *)0x60087004ul)
#define KEYMNG_CLK_REG_CG_FORCE_ON_POS 0   // Write 1 to force on register clock gate.
#define KEYMNG_CLK_REG_CG_FORCE_ON_MASK 0x1u
#define KEYMNG_CLK_MEM_CG_FORCE_ON_POS 1   // Write 1 to force on memory clock gate.
#define KEYMNG_CLK_MEM_CG_FORCE_ON_MASK 0x2u

// KEYMNG_INT_RAW: Key Manager interrupt raw register, valid in level. (read-write, reset 0x00000000)
#define KEYMNG_INT_RAW_ADDRESS 0x60087008ul
#define KEYMNG_INT_RAW (*(volatile uint32_t *)0x60087008ul)
#define KEYMNG_INT_RAW_PREP_DONE_INT_RAW_POS 0   // The raw interrupt status bit for the km_prep_done_int interrupt (read-only)
#define KEYMNG_INT_RAW_PREP_DONE_INT_RAW_MASK 0x1u
#define KEYMNG_INT_RAW_PROC_DONE_INT_RAW_POS 1   // The raw interrupt status bit for the km_proc_done_int interrupt (read-only)
#define KEYMNG_INT_RAW_PROC_DONE_INT_RAW_MASK 0x2u
#define KEYMNG_INT_RAW_POST_DONE_INT_RAW_POS 2   // The raw interrupt status bit for the km_post_done_int interrupt (read-only)
#define KEYMNG_INT_RAW_POST_DONE_INT_RAW_MASK 0x4u

// KEYMNG_INT_ST: Key Manager interrupt status register. (read-write, reset 0x00000000)
#define KEYMNG_INT_ST_ADDRESS 0x6008700cul
#define KEYMNG_INT_ST (*(volatile uint32_t *)0x6008700cul)
#define KEYMNG_INT_ST_PREP_DONE_INT_ST_POS 0   // The masked interrupt status bit for the km_prep_done_int interrupt (read-only)
#define KEYMNG_INT_ST_PREP_DONE_INT_ST_MASK 0x1u
#define KEYMNG_INT_ST_PROC_DONE_INT_ST_POS 1   // The masked interrupt status bit for the km_proc_done_int interrupt (read-only)
#define KEYMNG_INT_ST_PROC_DONE_INT_ST_MASK 0x2u
#define KEYMNG_INT_ST_POST_DONE_INT_ST_POS 2   // The masked interrupt status bit for the km_post_done_int interrupt (read-only)
#define KEYMNG_INT_ST_POST_DONE_INT_ST_MASK 0x4u

// KEYMNG_INT_ENA: Key Manager interrupt enable register. (read-write, reset 0x00000000)
#define KEYMNG_INT_ENA_ADDRESS 0x60087010ul
#define KEYMNG_INT_ENA (*(volatile uint32_t *)0x60087010ul)
#define KEYMNG_INT_ENA_PREP_DONE_INT_ENA_POS 0   // The interrupt enable bit for the km_prep_done_int interrupt
#define KEYMNG_INT_ENA_PREP_DONE_INT_ENA_MASK 0x1u
#define KEYMNG_INT_ENA_PROC_DONE_INT_ENA_POS 1   // The interrupt enable bit for the km_proc_done_int interrupt
#define KEYMNG_INT_ENA_PROC_DONE_INT_ENA_MASK 0x2u
#define KEYMNG_INT_ENA_POST_DONE_INT_ENA_POS 2   // The interrupt enable bit for the km_post_done_int interrupt
#define KEYMNG_INT_ENA_POST_DONE_INT_ENA_MASK 0x4u

// KEYMNG_INT_CLR: Key Manager interrupt clear register. (read-write, reset 0x00000000)
#define KEYMNG_INT_CLR_ADDRESS 0x60087014ul
#define KEYMNG_INT_CLR (*(volatile uint32_t *)0x60087014ul)
#define KEYMNG_INT_CLR_PREP_DONE_INT_CLR_POS 0   // Set this bit to clear the km_prep_done_int interrupt (write-only)
#define KEYMNG_INT_CLR_PREP_DONE_INT_CLR_MASK 0x1u
#define KEYMNG_INT_CLR_PROC_DONE_INT_CLR_POS 1   // Set this bit to clear the km_proc_done_int interrupt (write-only)
#define KEYMNG_INT_CLR_PROC_DONE_INT_CLR_MASK 0x2u
#define KEYMNG_INT_CLR_POST_DONE_INT_CLR_POS 2   // Set this bit to clear the km_post_done_int interrupt (write-only)
#define KEYMNG_INT_CLR_POST_DONE_INT_CLR_MASK 0x4u

// KEYMNG_STATIC: Key Manager static configuration register (read-write, reset 0x000001e0)
#define KEYMNG_STATIC_ADDRESS 0x60087018ul
#define KEYMNG_STATIC (*(volatile uint32_t *)0x60087018ul)
#define KEYMNG_STATIC_USE_EFUSE_KEY_POS 0   // Set each bit to choose efuse key instead of key manager deployed key. Each bit stands for a key type:bit 4 for psram_key; bit 3 for ds_key; bit 2 for hmac_key; bit 1 for flash_key; bit 0 for ecdsa_key
#define KEYMNG_STATIC_USE_EFUSE_KEY_MASK 0x1fu
#define KEYMNG_STATIC_USE_EFUSE_KEY(value) ((((unsigned long)(value)) << 0) & KEYMNG_STATIC_USE_EFUSE_KEY_MASK)
#define KEYMNG_STATIC_RND_SWITCH_CYCLE_POS 5   // The core clock cycle number to sample one rng input data. Please set it bigger than the clock cycle ratio: T_rng/T_km
#define KEYMNG_STATIC_RND_SWITCH_CYCLE_MASK 0x3e0u
#define KEYMNG_STATIC_RND_SWITCH_CYCLE(value) ((((unsigned long)(value)) << 5) & KEYMNG_STATIC_RND_SWITCH_CYCLE_MASK)
