#define PCR_I2S_CONF_I2S_RST_EN_POS 1   // Set 0 to reset i2s module
#define PCR_I2S_CONF_I2S_RST_EN_MASK 0x2u
#define PCR_I2S_CONF_I2S_RX_READY_POS 2   // Query this field before using i2s rx function, after reset i2s module (read-only)
#define PCR_I2S_CONF_I2S_RX_READY_MASK 0x4u
#define PCR_I2S_CONF_I2S_TX_READY_POS 3   // Query this field before using i2s tx function, after reset i2s module (read-only)
