// PCR_I2S_TX_CLKM_CONF: I2S_TX_CLKM configuration register (read-write, reset 0x00002000)
#define PCR_I2S_TX_CLKM_CONF_ADDRESS 0x60096078ul
#define PCR_I2S_TX_CLKM_CONF (*(volatile uint32_t *)0x60096078ul)
#define PCR_I2S_TX_CLKM_CONF_I2S_TX_CLKM_DIV_NUM_POS 12   // Integral I2S TX clock divider value. f_I2S_CLK = f_I2S_CLK_S/(N+b/a). There will be (a-b) * n-div and b * (n+1)-div. So the average combination will be: for b <= a/2, z * [x * n-div + (n+1)-div] + y * n-div. For b > a/2, z * [n-div + x * (n+1)-div] + y * (n+1)-div.
#define PCR_I2S_TX_CLKM_CONF_I2S_TX_CLKM_DIV_NUM_MASK 0xff000ul
#define PCR_I2S_TX_CLKM_CONF_I2S_TX_CLKM_DIV_NUM(value) ((((unsigned long)(value)) << 12) & PCR_I2S_TX_CLKM_CONF_I2S_TX_CLKM_DIV_NUM_MASK)
#define PCR_I2S_TX_CLKM_CONF_I2S_TX_CLKM_SEL_POS 20   // Configures the clock source of I2S TX. 0 (default): XTAL_CLK; 1: PLL_F240M_CLK; 2: PLL_F160M_CLK; 3: I2S_MCLK_in
#define PCR_I2S_TX_CLKM_CONF_I2S_TX_CLKM_SEL_MASK 0x300000ul
#define PCR_I2S_TX_CLKM_CONF_I2S_TX_CLKM_SEL(value) ((((unsigned long)(value)) << 20) & PCR_I2S_TX_CLKM_CONF_I2S_TX_CLKM_SEL_MASK)
#define PCR_I2S_TX_CLKM_CONF_I2S_TX_CLKM_EN_POS 22   // Set 1 to enable i2s_tx function clock
#define PCR_I2S_TX_CLKM_CONF_I2S_TX_CLKM_EN_MASK 0x400000ul

// PCR_I2S_TX_CLKM_DIV_CONF: I2S_TX_CLKM_DIV configuration register (read-write, reset 0x00000200)
#define PCR_I2S_TX_CLKM_DIV_CONF_ADDRESS 0x6009607cul
#define PCR_I2S_TX_CLKM_DIV_CONF (*(volatile uint32_t *)0x6009607cul)
#define PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_Z_POS 0   // For b <= a/2, the value of I2S_TX_CLKM_DIV_Z is b. For b > a/2, the value of I2S_TX_CLKM_DIV_Z is (a-b).
#define PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_Z_MASK 0x1ffu
#define PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_Z(value) ((((unsigned long)(value)) << 0) & PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_Z_MASK)
#define PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_Y_POS 9   // For b <= a/2, the value of I2S_TX_CLKM_DIV_Y is (a%b) . For b > a/2, the value of I2S_TX_CLKM_DIV_Y is (a%(a-b)).
#define PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_Y_MASK 0x3fe00ul
#define PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_Y(value) ((((unsigned long)(value)) << 9) & PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_Y_MASK)
#define PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_X_POS 18   // For b <= a/2, the value of I2S_TX_CLKM_DIV_X is (a/b) - 1. For b > a/2, the value of I2S_TX_CLKM_DIV_X is (a/(a-b)) - 1.
#define PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_X_MASK 0x7fc0000ul
#define PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_X(value) ((((unsigned long)(value)) << 18) & PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_X_MASK)
#define PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_YN1_POS 27   // For b <= a/2, the value of I2S_TX_CLKM_DIV_YN1 is 0 . For b > a/2, the value of I2S_TX_CLKM_DIV_YN1 is 1.
#define PCR_I2S_TX_CLKM_DIV_CONF_I2S_TX_CLKM_DIV_YN1_MASK 0x8000000ul

