// ---- SPI0: SPI (Serial Peripheral Interface) Controller 0

// SPI0_MEM_CMD: SPI0 FSM status register (read-write, reset 0x00000000)
#define SPI0_MEM_CMD_ADDRESS 0x60002000ul
#define SPI0_MEM_CMD (*(volatile uint32_t *)0x60002000ul)
#define SPI0_MEM_CMD_MEM_MST_ST_POS 0   // The current status of SPI0 master FSM: spi0_mst_st. 0: idle state, 1:SPI0_GRANT , 2: program/erase suspend state, 3: SPI0 read data state, 4: wait cache/EDMA sent data is stored in SPI0 TX FIFO, 5: SPI0 write data state. (read-only)
#define SPI0_MEM_CMD_MEM_MST_ST_MASK 0xfu
#define SPI0_MEM_CMD_MEM_MST_ST(value) ((((unsigned long)(value)) << 0) & SPI0_MEM_CMD_MEM_MST_ST_MASK)
#define SPI0_MEM_CMD_MEM_SLV_ST_POS 4   // The current status of SPI0 slave FSM: mspi_st. 0: idle state, 1: preparation state, 2: send command state, 3: send address state, 4: wait state, 5: read data state, 6:write data state, 7: done state, 8: read data end state. (read-only)
#define SPI0_MEM_CMD_MEM_SLV_ST_MASK 0xf0u
#define SPI0_MEM_CMD_MEM_SLV_ST(value) ((((unsigned long)(value)) << 4) & SPI0_MEM_CMD_MEM_SLV_ST_MASK)
#define SPI0_MEM_CMD_MEM_USR_POS 18   // SPI0 USR_CMD start bit, only used when SPI_MEM_AXI_REQ_EN is cleared. An operation will be triggered when the bit is set. The bit will be cleared once the operation done.1: enable 0: disable. (read-only)
#define SPI0_MEM_CMD_MEM_USR_MASK 0x40000ul

// SPI0_MEM_CTRL: SPI0 control register. (read-write, reset 0x802c200c)
#define SPI0_MEM_CTRL_ADDRESS 0x60002008ul
#define SPI0_MEM_CTRL (*(volatile uint32_t *)0x60002008ul)
#define SPI0_MEM_CTRL_MEM_WDUMMY_DQS_ALWAYS_OUT_POS 0   // In the dummy phase of an MSPI write data transfer when accesses to flash, the level of SPI_DQS is output by the MSPI controller.
#define SPI0_MEM_CTRL_MEM_WDUMMY_DQS_ALWAYS_OUT_MASK 0x1u
#define SPI0_MEM_CTRL_MEM_WDUMMY_ALWAYS_OUT_POS 1   // In the dummy phase of an MSPI write data transfer when accesses to flash, the level of SPI_IO[7:0] is output by the MSPI controller.
#define SPI0_MEM_CTRL_MEM_WDUMMY_ALWAYS_OUT_MASK 0x2u
#define SPI0_MEM_CTRL_MEM_FDUMMY_RIN_POS 2   // In an MSPI read data transfer when accesses to flash, the level of SPI_IO[7:0] is output by the MSPI controller in the first half part of dummy phase. It is used to mask invalid SPI_DQS in the half part of dummy phase.
#define SPI0_MEM_CTRL_MEM_FDUMMY_RIN_MASK 0x4u
#define SPI0_MEM_CTRL_MEM_FDUMMY_WOUT_POS 3   // In an MSPI write data transfer when accesses to flash, the level of SPI_IO[7:0] is output by the MSPI controller in the second half part of dummy phase. It is used to pre-drive flash.
#define SPI0_MEM_CTRL_MEM_FDUMMY_WOUT_MASK 0x8u
#define SPI0_MEM_CTRL_MEM_FDOUT_OCT_POS 4   // Apply 8 signals during write-data phase 1:enable 0: disable
#define SPI0_MEM_CTRL_MEM_FDOUT_OCT_MASK 0x10u
#define SPI0_MEM_CTRL_MEM_FDIN_OCT_POS 5   // Apply 8 signals during read-data phase 1:enable 0: disable
#define SPI0_MEM_CTRL_MEM_FDIN_OCT_MASK 0x20u
#define SPI0_MEM_CTRL_MEM_FADDR_OCT_POS 6   // Apply 8 signals during address phase 1:enable 0: disable
#define SPI0_MEM_CTRL_MEM_FADDR_OCT_MASK 0x40u
#define SPI0_MEM_CTRL_MEM_FCMD_QUAD_POS 8   // Apply 4 signals during command phase 1:enable 0: disable
#define SPI0_MEM_CTRL_MEM_FCMD_QUAD_MASK 0x100u
#define SPI0_MEM_CTRL_MEM_FCMD_OCT_POS 9   // Apply 8 signals during command phase 1:enable 0: disable
#define SPI0_MEM_CTRL_MEM_FCMD_OCT_MASK 0x200u
#define SPI0_MEM_CTRL_MEM_FASTRD_MODE_POS 13   // This bit enable the bits: SPI_MEM_FREAD_QIO, SPI_MEM_FREAD_DIO, SPI_MEM_FREAD_QOUT and SPI_MEM_FREAD_DOUT. 1: enable 0: disable.
#define SPI0_MEM_CTRL_MEM_FASTRD_MODE_MASK 0x2000u
#define SPI0_MEM_CTRL_MEM_FREAD_DUAL_POS 14   // In the read operations, read-data phase apply 2 signals. 1: enable 0: disable.
#define SPI0_MEM_CTRL_MEM_FREAD_DUAL_MASK 0x4000u
#define SPI0_MEM_CTRL_MEM_Q_POL_POS 18   // The bit is used to set MISO line polarity, 1: high 0, low
#define SPI0_MEM_CTRL_MEM_Q_POL_MASK 0x40000ul
#define SPI0_MEM_CTRL_MEM_D_POL_POS 19   // The bit is used to set MOSI line polarity, 1: high 0, low
#define SPI0_MEM_CTRL_MEM_D_POL_MASK 0x80000ul
#define SPI0_MEM_CTRL_MEM_FREAD_QUAD_POS 20   // In the read operations read-data phase apply 4 signals. 1: enable 0: disable.
#define SPI0_MEM_CTRL_MEM_FREAD_QUAD_MASK 0x100000ul
#define SPI0_MEM_CTRL_MEM_WP_POS 21   // Write protect signal output when SPI is idle. 1: output high, 0: output low.
#define SPI0_MEM_CTRL_MEM_WP_MASK 0x200000ul
#define SPI0_MEM_CTRL_MEM_FREAD_DIO_POS 23   // In the read operations address phase and read-data phase apply 2 signals. 1: enable 0: disable.
#define SPI0_MEM_CTRL_MEM_FREAD_DIO_MASK 0x800000ul
#define SPI0_MEM_CTRL_MEM_FREAD_QIO_POS 24   // In the read operations address phase and read-data phase apply 4 signals. 1: enable 0: disable.
#define SPI0_MEM_CTRL_MEM_FREAD_QIO_MASK 0x1000000ul
#define SPI0_MEM_CTRL_MEM_DQS_IE_ALWAYS_ON_POS 30   // When accesses to flash, 1: the IE signals of pads connected to SPI_DQS are always 1. 0: Others.
#define SPI0_MEM_CTRL_MEM_DQS_IE_ALWAYS_ON_MASK 0x40000000ul
#define SPI0_MEM_CTRL_MEM_DATA_IE_ALWAYS_ON_POS 31   // When accesses to flash, 1: the IE signals of pads connected to SPI_IO[7:0] are always 1. 0: Others.
#define SPI0_MEM_CTRL_MEM_DATA_IE_ALWAYS_ON_MASK 0x80000000ul

// SPI0_MEM_CTRL1: SPI0 control1 register. (read-write, reset 0x28e00000)
#define SPI0_MEM_CTRL1_ADDRESS 0x6000200cul
#define SPI0_MEM_CTRL1 (*(volatile uint32_t *)0x6000200cul)
#define SPI0_MEM_CTRL1_MEM_CLK_MODE_POS 0   // SPI clock mode bits. 0: SPI clock is off when CS inactive 1: SPI clock is delayed one cycle after CS inactive 2: SPI clock is delayed two cycles after CS inactive 3: SPI clock is alwasy on.
#define SPI0_MEM_CTRL1_MEM_CLK_MODE_MASK 0x3u
#define SPI0_MEM_CTRL1_MEM_CLK_MODE(value) ((((unsigned long)(value)) << 0) & SPI0_MEM_CTRL1_MEM_CLK_MODE_MASK)
#define SPI0_MEM_CTRL1_AR_SIZE0_1_SUPPORT_EN_POS 21   // 1: MSPI supports ARSIZE 0~3. When ARSIZE =0~2, MSPI read address is 4*n and reply the real AXI read data back. 0: When ARSIZE 0~1, MSPI reply SLV_ERR.
#define SPI0_MEM_CTRL1_AR_SIZE0_1_SUPPORT_EN_MASK 0x200000ul
#define SPI0_MEM_CTRL1_AW_SIZE0_1_SUPPORT_EN_POS 22   // 1: MSPI supports AWSIZE 0~3. 0: When AWSIZE 0~1, MSPI reply SLV_ERR.
#define SPI0_MEM_CTRL1_AW_SIZE0_1_SUPPORT_EN_MASK 0x400000ul
#define SPI0_MEM_CTRL1_AXI_RDATA_BACK_FAST_POS 23   // 1: Reply AXI read data to AXI bus when one AXI read beat data is available. 0: Reply AXI read data to AXI bus when all the read data is available.
#define SPI0_MEM_CTRL1_AXI_RDATA_BACK_FAST_MASK 0x800000ul
#define SPI0_MEM_CTRL1_MEM_RRESP_ECC_ERR_EN_POS 24   // 1: RRESP is SLV_ERR when there is a ECC error in AXI read data. 0: RRESP is OKAY when there is a ECC error in AXI read data. The ECC error information is recorded in SPI_MEM_ECC_ERR_ADDR_REG.
#define SPI0_MEM_CTRL1_MEM_RRESP_ECC_ERR_EN_MASK 0x1000000ul
#define SPI0_MEM_CTRL1_MEM_AR_SPLICE_EN_POS 25   // Set this bit to enable AXI Read Splice-transfer.
#define SPI0_MEM_CTRL1_MEM_AR_SPLICE_EN_MASK 0x2000000ul
#define SPI0_MEM_CTRL1_MEM_AW_SPLICE_EN_POS 26   // Set this bit to enable AXI Write Splice-transfer.
#define SPI0_MEM_CTRL1_MEM_AW_SPLICE_EN_MASK 0x4000000ul
#define SPI0_MEM_CTRL1_MEM_RAM0_EN_POS 27   // When SPI_MEM_DUAL_RAM_EN is 0 and SPI_MEM_RAM0_EN is 1, only EXT_RAM0 will be accessed. When SPI_MEM_DUAL_RAM_EN is 0 and SPI_MEM_RAM0_EN is 0, only EXT_RAM1 will be accessed. When SPI_MEM_DUAL_RAM_EN is 1, EXT_RAM0 and EXT_RAM1 will be accessed at the same time. (read-only)
#define SPI0_MEM_CTRL1_MEM_RAM0_EN_MASK 0x8000000ul
#define SPI0_MEM_CTRL1_MEM_DUAL_RAM_EN_POS 28   // Set this bit to enable DUAL-RAM mode, EXT_RAM0 and EXT_RAM1 will be accessed at the same time. (read-only)
#define SPI0_MEM_CTRL1_MEM_DUAL_RAM_EN_MASK 0x10000000ul
#define SPI0_MEM_CTRL1_MEM_FAST_WRITE_EN_POS 29   // Set this bit to write data faster, do not wait write data has been stored in tx_bus_fifo_l2. It will wait 4*T_clk_ctrl to insure the write data has been stored in tx_bus_fifo_l2.
#define SPI0_MEM_CTRL1_MEM_FAST_WRITE_EN_MASK 0x20000000ul
#define SPI0_MEM_CTRL1_MEM_RXFIFO_RST_POS 30   // The synchronous reset signal for SPI0 RX AFIFO and all the AES_MSPI SYNC FIFO to receive signals from AXI. Set this bit to reset these FIFO. (write-only)
#define SPI0_MEM_CTRL1_MEM_RXFIFO_RST_MASK 0x40000000ul
#define SPI0_MEM_CTRL1_MEM_TXFIFO_RST_POS 31   // The synchronous reset signal for SPI0 TX AFIFO and all the AES_MSPI SYNC FIFO to send signals to AXI. Set this bit to reset these FIFO. (write-only)
#define SPI0_MEM_CTRL1_MEM_TXFIFO_RST_MASK 0x80000000ul

// SPI0_MEM_CTRL2: SPI0 control2 register. (read-write, reset 0x00002c21)
#define SPI0_MEM_CTRL2_ADDRESS 0x60002010ul
#define SPI0_MEM_CTRL2 (*(volatile uint32_t *)0x60002010ul)
#define SPI0_MEM_CTRL2_MEM_CS_SETUP_TIME_POS 0   // (cycles-1) of prepare phase by SPI Bus clock, this bits are combined with SPI_MEM_CS_SETUP bit.
#define SPI0_MEM_CTRL2_MEM_CS_SETUP_TIME_MASK 0x1fu
#define SPI0_MEM_CTRL2_MEM_CS_SETUP_TIME(value) ((((unsigned long)(value)) << 0) & SPI0_MEM_CTRL2_MEM_CS_SETUP_TIME_MASK)
#define SPI0_MEM_CTRL2_MEM_CS_HOLD_TIME_POS 5   // SPI CS signal is delayed to inactive by SPI bus clock, this bits are combined with SPI_MEM_CS_HOLD bit.
#define SPI0_MEM_CTRL2_MEM_CS_HOLD_TIME_MASK 0x3e0u
#define SPI0_MEM_CTRL2_MEM_CS_HOLD_TIME(value) ((((unsigned long)(value)) << 5) & SPI0_MEM_CTRL2_MEM_CS_HOLD_TIME_MASK)
#define SPI0_MEM_CTRL2_MEM_ECC_CS_HOLD_TIME_POS 10   // SPI_MEM_CS_HOLD_TIME + SPI_MEM_ECC_CS_HOLD_TIME is the SPI0 CS hold cycle in ECC mode when accessed flash.
#define SPI0_MEM_CTRL2_MEM_ECC_CS_HOLD_TIME_MASK 0x1c00u
#define SPI0_MEM_CTRL2_MEM_ECC_CS_HOLD_TIME(value) ((((unsigned long)(value)) << 10) & SPI0_MEM_CTRL2_MEM_ECC_CS_HOLD_TIME_MASK)
#define SPI0_MEM_CTRL2_MEM_ECC_SKIP_PAGE_CORNER_POS 13   // 1: SPI0 and SPI1 skip page corner when accesses flash. 0: Not skip page corner when accesses flash.
#define SPI0_MEM_CTRL2_MEM_ECC_SKIP_PAGE_CORNER_MASK 0x2000u
#define SPI0_MEM_CTRL2_MEM_ECC_16TO18_BYTE_EN_POS 14   // Set this bit to enable SPI0 and SPI1 ECC 16 bytes data with 2 ECC bytes mode when accesses flash.
#define SPI0_MEM_CTRL2_MEM_ECC_16TO18_BYTE_EN_MASK 0x4000u
#define SPI0_MEM_CTRL2_MEM_SPLIT_TRANS_EN_POS 24   // Set this bit to enable SPI0 split one AXI read flash transfer into two SPI transfers when one transfer will cross flash or EXT_RAM page corner, valid no matter whether there is an ECC region or not.
#define SPI0_MEM_CTRL2_MEM_SPLIT_TRANS_EN_MASK 0x1000000ul
#define SPI0_MEM_CTRL2_MEM_CS_HOLD_DELAY_POS 25   // These bits are used to set the minimum CS high time tSHSL between SPI burst transfer when accesses to flash. tSHSL is (SPI_MEM_CS_HOLD_DELAY[5:0] + 1) MSPI core clock cycles.
#define SPI0_MEM_CTRL2_MEM_CS_HOLD_DELAY_MASK 0x7e000000ul
#define SPI0_MEM_CTRL2_MEM_CS_HOLD_DELAY(value) ((((unsigned long)(value)) << 25) & SPI0_MEM_CTRL2_MEM_CS_HOLD_DELAY_MASK)
#define SPI0_MEM_CTRL2_MEM_SYNC_RESET_POS 31   // The spi0_mst_st and spi0_slv_st will be reset. (write-only)
#define SPI0_MEM_CTRL2_MEM_SYNC_RESET_MASK 0x80000000ul

// SPI0_MEM_CLOCK: SPI clock division control register. (read-write, reset 0x00030103)
#define SPI0_MEM_CLOCK_ADDRESS 0x60002014ul
#define SPI0_MEM_CLOCK (*(volatile uint32_t *)0x60002014ul)
#define SPI0_MEM_CLOCK_MEM_CLKCNT_L_POS 0   // In the master mode it must be equal to spi_mem_clkcnt_N.
#define SPI0_MEM_CLOCK_MEM_CLKCNT_L_MASK 0xffu
#define SPI0_MEM_CLOCK_MEM_CLKCNT_L(value) ((((unsigned long)(value)) << 0) & SPI0_MEM_CLOCK_MEM_CLKCNT_L_MASK)
#define SPI0_MEM_CLOCK_MEM_CLKCNT_H_POS 8   // In the master mode it must be floor((spi_mem_clkcnt_N+1)/2-1).
#define SPI0_MEM_CLOCK_MEM_CLKCNT_H_MASK 0xff00u
#define SPI0_MEM_CLOCK_MEM_CLKCNT_H(value) ((((unsigned long)(value)) << 8) & SPI0_MEM_CLOCK_MEM_CLKCNT_H_MASK)
#define SPI0_MEM_CLOCK_MEM_CLKCNT_N_POS 16   // In the master mode it is the divider of spi_mem_clk. So spi_mem_clk frequency is system/(spi_mem_clkcnt_N+1)
#define SPI0_MEM_CLOCK_MEM_CLKCNT_N_MASK 0xff0000ul
#define SPI0_MEM_CLOCK_MEM_CLKCNT_N(value) ((((unsigned long)(value)) << 16) & SPI0_MEM_CLOCK_MEM_CLKCNT_N_MASK)
#define SPI0_MEM_CLOCK_MEM_CLK_EQU_SYSCLK_POS 31   // 1: 1-division mode, the frequency of SPI bus clock equals to that of MSPI module clock.
#define SPI0_MEM_CLOCK_MEM_CLK_EQU_SYSCLK_MASK 0x80000000ul

// SPI0_MEM_USER: SPI0 user register. (read-write, reset 0x00000000)
#define SPI0_MEM_USER_ADDRESS 0x60002018ul
#define SPI0_MEM_USER (*(volatile uint32_t *)0x60002018ul)
#define SPI0_MEM_USER_MEM_CS_HOLD_POS 6   // spi cs keep low when spi is in done phase. 1: enable 0: disable.
#define SPI0_MEM_USER_MEM_CS_HOLD_MASK 0x40u
#define SPI0_MEM_USER_MEM_CS_SETUP_POS 7   // spi cs is enable when spi is in prepare phase. 1: enable 0: disable.
#define SPI0_MEM_USER_MEM_CS_SETUP_MASK 0x80u
#define SPI0_MEM_USER_MEM_CK_OUT_EDGE_POS 9   // The bit combined with SPI_MEM_CK_IDLE_EDGE bit to control SPI clock mode 0~3.
#define SPI0_MEM_USER_MEM_CK_OUT_EDGE_MASK 0x200u
#define SPI0_MEM_USER_MEM_USR_DUMMY_IDLE_POS 26   // spi clock is disable in dummy phase when the bit is enable.
#define SPI0_MEM_USER_MEM_USR_DUMMY_IDLE_MASK 0x4000000ul
#define SPI0_MEM_USER_MEM_USR_DUMMY_POS 29   // This bit enable the dummy phase of an operation.
#define SPI0_MEM_USER_MEM_USR_DUMMY_MASK 0x20000000ul

// SPI0_MEM_USER1: SPI0 user1 register. (read-write, reset 0x5c000047)
#define SPI0_MEM_USER1_ADDRESS 0x6000201cul
#define SPI0_MEM_USER1 (*(volatile uint32_t *)0x6000201cul)
#define SPI0_MEM_USER1_MEM_USR_DUMMY_CYCLELEN_POS 0   // The length in spi_mem_clk cycles of dummy phase. The register value shall be (cycle_num-1).
#define SPI0_MEM_USER1_MEM_USR_DUMMY_CYCLELEN_MASK 0x3fu
#define SPI0_MEM_USER1_MEM_USR_DUMMY_CYCLELEN(value) ((((unsigned long)(value)) << 0) & SPI0_MEM_USER1_MEM_USR_DUMMY_CYCLELEN_MASK)
#define SPI0_MEM_USER1_MEM_USR_DBYTELEN_POS 6   // SPI0 USR_CMD read or write data byte length -1 (read-only)
#define SPI0_MEM_USER1_MEM_USR_DBYTELEN_MASK 0xfc0u
#define SPI0_MEM_USER1_MEM_USR_DBYTELEN(value) ((((unsigned long)(value)) << 6) & SPI0_MEM_USER1_MEM_USR_DBYTELEN_MASK)
#define SPI0_MEM_USER1_MEM_USR_ADDR_BITLEN_POS 26   // The length in bits of address phase. The register value shall be (bit_num-1).
#define SPI0_MEM_USER1_MEM_USR_ADDR_BITLEN_MASK 0xfc000000ul
#define SPI0_MEM_USER1_MEM_USR_ADDR_BITLEN(value) ((((unsigned long)(value)) << 26) & SPI0_MEM_USER1_MEM_USR_ADDR_BITLEN_MASK)

// SPI0_MEM_USER2: SPI0 user2 register. (read-write, reset 0x70000000)
#define SPI0_MEM_USER2_ADDRESS 0x60002020ul
#define SPI0_MEM_USER2 (*(volatile uint32_t *)0x60002020ul)
#define SPI0_MEM_USER2_MEM_USR_COMMAND_VALUE_POS 0   // The value of command.
#define SPI0_MEM_USER2_MEM_USR_COMMAND_VALUE_MASK 0xffffu
#define SPI0_MEM_USER2_MEM_USR_COMMAND_VALUE(value) ((((unsigned long)(value)) << 0) & SPI0_MEM_USER2_MEM_USR_COMMAND_VALUE_MASK)
#define SPI0_MEM_USER2_MEM_USR_COMMAND_BITLEN_POS 28   // The length in bits of command phase. The register value shall be (bit_num-1)
#define SPI0_MEM_USER2_MEM_USR_COMMAND_BITLEN_MASK 0xf0000000ul
#define SPI0_MEM_USER2_MEM_USR_COMMAND_BITLEN(value) ((((unsigned long)(value)) << 28) & SPI0_MEM_USER2_MEM_USR_COMMAND_BITLEN_MASK)

// SPI0_MEM_RD_STATUS: SPI0 read control register. (read-write, reset 0x00000000)
#define SPI0_MEM_RD_STATUS_ADDRESS 0x6000202cul
#define SPI0_MEM_RD_STATUS (*(volatile uint32_t *)0x6000202cul)
#define SPI0_MEM_RD_STATUS_MEM_WB_MODE_POS 16   // Mode bits in the flash fast read mode it is combined with spi_mem_fastrd_mode bit.
#define SPI0_MEM_RD_STATUS_MEM_WB_MODE_MASK 0xff0000ul
#define SPI0_MEM_RD_STATUS_MEM_WB_MODE(value) ((((unsigned long)(value)) << 16) & SPI0_MEM_RD_STATUS_MEM_WB_MODE_MASK)
#define SPI0_MEM_RD_STATUS_MEM_WB_MODE_BITLEN_POS 24   // Mode bits length for flash fast read mode.
#define SPI0_MEM_RD_STATUS_MEM_WB_MODE_BITLEN_MASK 0x7000000ul
#define SPI0_MEM_RD_STATUS_MEM_WB_MODE_BITLEN(value) ((((unsigned long)(value)) << 24) & SPI0_MEM_RD_STATUS_MEM_WB_MODE_BITLEN_MASK)
#define SPI0_MEM_RD_STATUS_MEM_WB_MODE_EN_POS 27   // Mode bits is valid while this bit is enable. 1: enable 0: disable.
#define SPI0_MEM_RD_STATUS_MEM_WB_MODE_EN_MASK 0x8000000ul

// SPI0_MEM_MISC: SPI0 misc register (read-write, reset 0x00000000)
#define SPI0_MEM_MISC_ADDRESS 0x60002034ul
#define SPI0_MEM_MISC (*(volatile uint32_t *)0x60002034ul)
#define SPI0_MEM_MISC_MEM_FSUB_PIN_POS 7   // For SPI0, flash is connected to SUBPINs. (read-only)
#define SPI0_MEM_MISC_MEM_FSUB_PIN_MASK 0x80u
#define SPI0_MEM_MISC_MEM_SSUB_PIN_POS 8   // For SPI0, sram is connected to SUBPINs. (read-only)
#define SPI0_MEM_MISC_MEM_SSUB_PIN_MASK 0x100u
#define SPI0_MEM_MISC_MEM_CK_IDLE_EDGE_POS 9   // 1: SPI_CLK line is high when idle 0: spi clk line is low when idle
#define SPI0_MEM_MISC_MEM_CK_IDLE_EDGE_MASK 0x200u
#define SPI0_MEM_MISC_MEM_CS_KEEP_ACTIVE_POS 10   // SPI_CS line keep low when the bit is set.
#define SPI0_MEM_MISC_MEM_CS_KEEP_ACTIVE_MASK 0x400u

// SPI0_MEM_CACHE_FCTRL: SPI0 bit mode control register. (read-write, reset 0xc0000000)
#define SPI0_MEM_CACHE_FCTRL_ADDRESS 0x6000203cul
#define SPI0_MEM_CACHE_FCTRL (*(volatile uint32_t *)0x6000203cul)
#define SPI0_MEM_CACHE_FCTRL_MEM_AXI_REQ_EN_POS 0   // For SPI0, AXI master access enable, 1: enable, 0:disable.
#define SPI0_MEM_CACHE_FCTRL_MEM_AXI_REQ_EN_MASK 0x1u
#define SPI0_MEM_CACHE_FCTRL_MEM_CACHE_USR_ADDR_4BYTE_POS 1   // For SPI0, cache read flash with 4 bytes address, 1: enable, 0:disable.
#define SPI0_MEM_CACHE_FCTRL_MEM_CACHE_USR_ADDR_4BYTE_MASK 0x2u
#define SPI0_MEM_CACHE_FCTRL_MEM_CACHE_FLASH_USR_CMD_POS 2   // For SPI0, cache read flash for user define command, 1: enable, 0:disable.
#define SPI0_MEM_CACHE_FCTRL_MEM_CACHE_FLASH_USR_CMD_MASK 0x4u
#define SPI0_MEM_CACHE_FCTRL_MEM_FDIN_DUAL_POS 3   // For SPI0 flash, din phase apply 2 signals. 1: enable 0: disable. The bit is the same with spi_mem_fread_dio.
#define SPI0_MEM_CACHE_FCTRL_MEM_FDIN_DUAL_MASK 0x8u
#define SPI0_MEM_CACHE_FCTRL_MEM_FDOUT_DUAL_POS 4   // For SPI0 flash, dout phase apply 2 signals. 1: enable 0: disable. The bit is the same with spi_mem_fread_dio.
#define SPI0_MEM_CACHE_FCTRL_MEM_FDOUT_DUAL_MASK 0x10u
#define SPI0_MEM_CACHE_FCTRL_MEM_FADDR_DUAL_POS 5   // For SPI0 flash, address phase apply 2 signals. 1: enable 0: disable. The bit is the same with spi_mem_fread_dio.
#define SPI0_MEM_CACHE_FCTRL_MEM_FADDR_DUAL_MASK 0x20u
#define SPI0_MEM_CACHE_FCTRL_MEM_FDIN_QUAD_POS 6   // For SPI0 flash, din phase apply 4 signals. 1: enable 0: disable. The bit is the same with spi_mem_fread_qio.
#define SPI0_MEM_CACHE_FCTRL_MEM_FDIN_QUAD_MASK 0x40u
#define SPI0_MEM_CACHE_FCTRL_MEM_FDOUT_QUAD_POS 7   // For SPI0 flash, dout phase apply 4 signals. 1: enable 0: disable. The bit is the same with spi_mem_fread_qio.
#define SPI0_MEM_CACHE_FCTRL_MEM_FDOUT_QUAD_MASK 0x80u
#define SPI0_MEM_CACHE_FCTRL_MEM_FADDR_QUAD_POS 8   // For SPI0 flash, address phase apply 4 signals. 1: enable 0: disable. The bit is the same with spi_mem_fread_qio.
#define SPI0_MEM_CACHE_FCTRL_MEM_FADDR_QUAD_MASK 0x100u
#define SPI0_MEM_CACHE_FCTRL_SAME_AW_AR_ADDR_CHK_EN_POS 30   // Set this bit to check AXI read/write the same address region.
#define SPI0_MEM_CACHE_FCTRL_SAME_AW_AR_ADDR_CHK_EN_MASK 0x40000000ul
#define SPI0_MEM_CACHE_FCTRL_CLOSE_AXI_INF_EN_POS 31   // Set this bit to close AXI read/write transfer to MSPI, which means that only SLV_ERR will be replied to BRESP/RRESP.
#define SPI0_MEM_CACHE_FCTRL_CLOSE_AXI_INF_EN_MASK 0x80000000ul

// SPI0_MEM_CACHE_SCTRL: SPI0 external RAM control register (read-write, reset 0x0055c070)
#define SPI0_MEM_CACHE_SCTRL_ADDRESS 0x60002040ul
#define SPI0_MEM_CACHE_SCTRL (*(volatile uint32_t *)0x60002040ul)
#define SPI0_MEM_CACHE_SCTRL_MEM_CACHE_USR_SADDR_4BYTE_POS 0   // For SPI0, In the external RAM mode, cache read flash with 4 bytes command, 1: enable, 0:disable.
#define SPI0_MEM_CACHE_SCTRL_MEM_CACHE_USR_SADDR_4BYTE_MASK 0x1u
#define SPI0_MEM_CACHE_SCTRL_MEM_USR_SRAM_DIO_POS 1   // For SPI0, In the external RAM mode, spi dual I/O mode enable, 1: enable, 0:disable
#define SPI0_MEM_CACHE_SCTRL_MEM_USR_SRAM_DIO_MASK 0x2u
#define SPI0_MEM_CACHE_SCTRL_MEM_USR_SRAM_QIO_POS 2   // For SPI0, In the external RAM mode, spi quad I/O mode enable, 1: enable, 0:disable
#define SPI0_MEM_CACHE_SCTRL_MEM_USR_SRAM_QIO_MASK 0x4u
#define SPI0_MEM_CACHE_SCTRL_MEM_USR_WR_SRAM_DUMMY_POS 3   // For SPI0, In the external RAM mode, it is the enable bit of dummy phase for write operations.
#define SPI0_MEM_CACHE_SCTRL_MEM_USR_WR_SRAM_DUMMY_MASK 0x8u
#define SPI0_MEM_CACHE_SCTRL_MEM_USR_RD_SRAM_DUMMY_POS 4   // For SPI0, In the external RAM mode, it is the enable bit of dummy phase for read operations.
#define SPI0_MEM_CACHE_SCTRL_MEM_USR_RD_SRAM_DUMMY_MASK 0x10u
#define SPI0_MEM_CACHE_SCTRL_MEM_CACHE_SRAM_USR_RCMD_POS 5   // For SPI0, In the external RAM mode cache read external RAM for user define command.
#define SPI0_MEM_CACHE_SCTRL_MEM_CACHE_SRAM_USR_RCMD_MASK 0x20u
#define SPI0_MEM_CACHE_SCTRL_MEM_SRAM_RDUMMY_CYCLELEN_POS 6   // For SPI0, In the external RAM mode, it is the length in bits of read dummy phase. The register value shall be (bit_num-1).
#define SPI0_MEM_CACHE_SCTRL_MEM_SRAM_RDUMMY_CYCLELEN_MASK 0xfc0u
#define SPI0_MEM_CACHE_SCTRL_MEM_SRAM_RDUMMY_CYCLELEN(value) ((((unsigned long)(value)) << 6) & SPI0_MEM_CACHE_SCTRL_MEM_SRAM_RDUMMY_CYCLELEN_MASK)
#define SPI0_MEM_CACHE_SCTRL_MEM_SRAM_ADDR_BITLEN_POS 14   // For SPI0, In the external RAM mode, it is the length in bits of address phase. The register value shall be (bit_num-1).
#define SPI0_MEM_CACHE_SCTRL_MEM_SRAM_ADDR_BITLEN_MASK 0xfc000ul
#define SPI0_MEM_CACHE_SCTRL_MEM_SRAM_ADDR_BITLEN(value) ((((unsigned long)(value)) << 14) & SPI0_MEM_CACHE_SCTRL_MEM_SRAM_ADDR_BITLEN_MASK)
#define SPI0_MEM_CACHE_SCTRL_MEM_CACHE_SRAM_USR_WCMD_POS 20   // For SPI0, In the external RAM mode cache write sram for user define command
#define SPI0_MEM_CACHE_SCTRL_MEM_CACHE_SRAM_USR_WCMD_MASK 0x100000ul
#define SPI0_MEM_CACHE_SCTRL_MEM_SRAM_OCT_POS 21   // reserved
#define SPI0_MEM_CACHE_SCTRL_MEM_SRAM_OCT_MASK 0x200000ul
#define SPI0_MEM_CACHE_SCTRL_MEM_SRAM_WDUMMY_CYCLELEN_POS 22   // For SPI0, In the external RAM mode, it is the length in bits of write dummy phase. The register value shall be (bit_num-1).
#define SPI0_MEM_CACHE_SCTRL_MEM_SRAM_WDUMMY_CYCLELEN_MASK 0xfc00000ul
#define SPI0_MEM_CACHE_SCTRL_MEM_SRAM_WDUMMY_CYCLELEN(value) ((((unsigned long)(value)) << 22) & SPI0_MEM_CACHE_SCTRL_MEM_SRAM_WDUMMY_CYCLELEN_MASK)

// SPI0_MEM_SRAM_CMD: SPI0 external RAM mode control register (read-write, reset 0x80c00000)
#define SPI0_MEM_SRAM_CMD_ADDRESS 0x60002044ul
#define SPI0_MEM_SRAM_CMD (*(volatile uint32_t *)0x60002044ul)
#define SPI0_MEM_SRAM_CMD_MEM_SCLK_MODE_POS 0   // SPI clock mode bits. 0: SPI clock is off when CS inactive 1: SPI clock is delayed one cycle after CS inactive 2: SPI clock is delayed two cycles after CS inactive 3: SPI clock is always on.
#define SPI0_MEM_SRAM_CMD_MEM_SCLK_MODE_MASK 0x3u
#define SPI0_MEM_SRAM_CMD_MEM_SCLK_MODE(value) ((((unsigned long)(value)) << 0) & SPI0_MEM_SRAM_CMD_MEM_SCLK_MODE_MASK)
#define SPI0_MEM_SRAM_CMD_MEM_SWB_MODE_POS 2   // Mode bits in the external RAM fast read mode it is combined with spi_mem_fastrd_mode bit.
#define SPI0_MEM_SRAM_CMD_MEM_SWB_MODE_MASK 0x3fcu
#define SPI0_MEM_SRAM_CMD_MEM_SWB_MODE(value) ((((unsigned long)(value)) << 2) & SPI0_MEM_SRAM_CMD_MEM_SWB_MODE_MASK)
#define SPI0_MEM_SRAM_CMD_MEM_SDIN_DUAL_POS 10   // For SPI0 external RAM , din phase apply 2 signals. 1: enable 0: disable. The bit is the same with spi_mem_usr_sram_dio.
#define SPI0_MEM_SRAM_CMD_MEM_SDIN_DUAL_MASK 0x400u
#define SPI0_MEM_SRAM_CMD_MEM_SDOUT_DUAL_POS 11   // For SPI0 external RAM , dout phase apply 2 signals. 1: enable 0: disable. The bit is the same with spi_mem_usr_sram_dio.
#define SPI0_MEM_SRAM_CMD_MEM_SDOUT_DUAL_MASK 0x800u
#define SPI0_MEM_SRAM_CMD_MEM_SADDR_DUAL_POS 12   // For SPI0 external RAM , address phase apply 2 signals. 1: enable 0: disable. The bit is the same with spi_mem_usr_sram_dio.
#define SPI0_MEM_SRAM_CMD_MEM_SADDR_DUAL_MASK 0x1000u
#define SPI0_MEM_SRAM_CMD_MEM_SDIN_QUAD_POS 14   // For SPI0 external RAM , din phase apply 4 signals. 1: enable 0: disable. The bit is the same with spi_mem_usr_sram_qio.
#define SPI0_MEM_SRAM_CMD_MEM_SDIN_QUAD_MASK 0x4000u
#define SPI0_MEM_SRAM_CMD_MEM_SDOUT_QUAD_POS 15   // For SPI0 external RAM , dout phase apply 4 signals. 1: enable 0: disable. The bit is the same with spi_mem_usr_sram_qio.
#define SPI0_MEM_SRAM_CMD_MEM_SDOUT_QUAD_MASK 0x8000u
#define SPI0_MEM_SRAM_CMD_MEM_SADDR_QUAD_POS 16   // For SPI0 external RAM , address phase apply 4 signals. 1: enable 0: disable. The bit is the same with spi_mem_usr_sram_qio.
#define SPI0_MEM_SRAM_CMD_MEM_SADDR_QUAD_MASK 0x10000ul
#define SPI0_MEM_SRAM_CMD_MEM_SCMD_QUAD_POS 17   // For SPI0 external RAM , cmd phase apply 4 signals. 1: enable 0: disable. The bit is the same with spi_mem_usr_sram_qio.
#define SPI0_MEM_SRAM_CMD_MEM_SCMD_QUAD_MASK 0x20000ul
#define SPI0_MEM_SRAM_CMD_MEM_SDIN_OCT_POS 18   // For SPI0 external RAM , din phase apply 8 signals. 1: enable 0: disable.
