#define SPI0_MEM_SRAM_CMD_MEM_SDOUT_OCT_POS 19   // For SPI0 external RAM , dout phase apply 8 signals. 1: enable 0: disable.
#define SPI0_MEM_SRAM_CMD_MEM_SDOUT_OCT_MASK 0x80000ul
#define SPI0_MEM_SRAM_CMD_MEM_SADDR_OCT_POS 20   // For SPI0 external RAM , address phase apply 4 signals. 1: enable 0: disable.
#define SPI0_MEM_SRAM_CMD_MEM_SADDR_OCT_MASK 0x100000ul
#define SPI0_MEM_SRAM_CMD_MEM_SCMD_OCT_POS 21   // For SPI0 external RAM , cmd phase apply 8 signals. 1: enable 0: disable.
#define SPI0_MEM_SRAM_CMD_MEM_SCMD_OCT_MASK 0x200000ul
#define SPI0_MEM_SRAM_CMD_MEM_SDUMMY_RIN_POS 22   // In the dummy phase of a MSPI read data transfer when accesses to external RAM, the signal level of SPI bus is output by the MSPI controller.
