#define SPI0_MEM_SRAM_CMD_MEM_SDUMMY_WOUT_POS 23   // In the dummy phase of a MSPI write data transfer when accesses to external RAM, the signal level of SPI bus is output by the MSPI controller.
#define SPI0_MEM_SRAM_CMD_MEM_SDUMMY_WOUT_MASK 0x800000ul
#define SPI0_MEM_SRAM_CMD_SMEM_WDUMMY_DQS_ALWAYS_OUT_POS 24   // In the dummy phase of an MSPI write data transfer when accesses to external RAM, the level of SPI_DQS is output by the MSPI controller.
#define SPI0_MEM_SRAM_CMD_SMEM_WDUMMY_DQS_ALWAYS_OUT_MASK 0x1000000ul
#define SPI0_MEM_SRAM_CMD_SMEM_WDUMMY_ALWAYS_OUT_POS 25   // In the dummy phase of an MSPI write data transfer when accesses to external RAM, the level of SPI_IO[7:0] is output by the MSPI controller.
#define SPI0_MEM_SRAM_CMD_SMEM_WDUMMY_ALWAYS_OUT_MASK 0x2000000ul
#define SPI0_MEM_SRAM_CMD_MEM_SDIN_HEX_POS 26   // For SPI0 external RAM , din phase apply 16 signals. 1: enable 0: disable. (read-only)
#define SPI0_MEM_SRAM_CMD_MEM_SDIN_HEX_MASK 0x4000000ul
#define SPI0_MEM_SRAM_CMD_MEM_SDOUT_HEX_POS 27   // For SPI0 external RAM , dout phase apply 16 signals. 1: enable 0: disable. (read-only)
#define SPI0_MEM_SRAM_CMD_MEM_SDOUT_HEX_MASK 0x8000000ul
#define SPI0_MEM_SRAM_CMD_SMEM_DQS_IE_ALWAYS_ON_POS 30   // When accesses to external RAM, 1: the IE signals of pads connected to SPI_DQS are always 1. 0: Others.
