#define SPI0_MEM_SRAM_DWR_CMD_MEM_CACHE_SRAM_USR_WR_CMD_BITLEN(value) ((((unsigned long)(value)) << 28) & SPI0_MEM_SRAM_DWR_CMD_MEM_CACHE_SRAM_USR_WR_CMD_BITLEN_MASK)

