#define SPI0_MEM_SRAM_CLK_MEM_SCLKCNT_L(value) ((((unsigned long)(value)) << 0) & SPI0_MEM_SRAM_CLK_MEM_SCLKCNT_L_MASK)
#define SPI0_MEM_SRAM_CLK_MEM_SCLKCNT_H_POS 8   // For SPI0 external RAM interface, it must be floor((spi_mem_clkcnt_N+1)/2-1).
#define SPI0_MEM_SRAM_CLK_MEM_SCLKCNT_H_MASK 0xff00u
#define SPI0_MEM_SRAM_CLK_MEM_SCLKCNT_H(value) ((((unsigned long)(value)) << 8) & SPI0_MEM_SRAM_CLK_MEM_SCLKCNT_H_MASK)
#define SPI0_MEM_SRAM_CLK_MEM_SCLKCNT_N_POS 16   // For SPI0 external RAM interface, it is the divider of spi_mem_clk. So spi_mem_clk frequency is system/(spi_mem_clkcnt_N+1)
#define SPI0_MEM_SRAM_CLK_MEM_SCLKCNT_N_MASK 0xff0000ul
#define SPI0_MEM_SRAM_CLK_MEM_SCLKCNT_N(value) ((((unsigned long)(value)) << 16) & SPI0_MEM_SRAM_CLK_MEM_SCLKCNT_N_MASK)
#define SPI0_MEM_SRAM_CLK_MEM_SCLK_EQU_SYSCLK_POS 31   // For SPI0 external RAM interface, 1: spi_mem_clk is eqaul to system 0: spi_mem_clk is divided from system clock.
