// SPI0_MEM_INT_RAW: SPI0 interrupt raw register (read-write, reset 0x00000000)
#define SPI0_MEM_INT_RAW_ADDRESS 0x600020c8ul
#define SPI0_MEM_INT_RAW (*(volatile uint32_t *)0x600020c8ul)
#define SPI0_MEM_INT_RAW_MEM_SLV_ST_END_INT_RAW_POS 3   // The raw bit for SPI_MEM_SLV_ST_END_INT interrupt. 1: Triggered when spi0_slv_st is changed from non idle state to idle state. It means that SPI_CS raises high. 0: Others
#define SPI0_MEM_INT_RAW_MEM_SLV_ST_END_INT_RAW_MASK 0x8u
#define SPI0_MEM_INT_RAW_MEM_MST_ST_END_INT_RAW_POS 4   // The raw bit for SPI_MEM_MST_ST_END_INT interrupt. 1: Triggered when spi0_mst_st is changed from non idle state to idle state. 0: Others.
#define SPI0_MEM_INT_RAW_MEM_MST_ST_END_INT_RAW_MASK 0x10u
#define SPI0_MEM_INT_RAW_MEM_ECC_ERR_INT_RAW_POS 5   // The raw bit for SPI_MEM_ECC_ERR_INT interrupt. When SPI_FMEM_ECC_ERR_INT_EN is set and SPI_SMEM_ECC_ERR_INT_EN is cleared, this bit is triggered when the error times of SPI0/1 ECC read flash are equal or bigger than SPI_MEM_ECC_ERR_INT_NUM. When SPI_FMEM_ECC_ERR_INT_EN is cleared and SPI_SMEM_ECC_ERR_INT_EN is set, this bit is triggered when the error times of SPI0/1 ECC read external RAM are equal or bigger than SPI_MEM_ECC_ERR_INT_NUM. When SPI_FMEM_ECC_ERR_INT_EN and SPI_SMEM_ECC_ERR_INT_EN are set, this bit is triggered when the total error times of SPI0/1 ECC read external RAM and flash are equal or bigger than SPI_MEM_ECC_ERR_INT_NUM. When SPI_FMEM_ECC_ERR_INT_EN and SPI_SMEM_ECC_ERR_INT_EN are cleared, this bit will not be triggered.
#define SPI0_MEM_INT_RAW_MEM_ECC_ERR_INT_RAW_MASK 0x20u
#define SPI0_MEM_INT_RAW_MEM_PMS_REJECT_INT_RAW_POS 6   // The raw bit for SPI_MEM_PMS_REJECT_INT interrupt. 1: Triggered when SPI1 access is rejected. 0: Others.
#define SPI0_MEM_INT_RAW_MEM_PMS_REJECT_INT_RAW_MASK 0x40u
#define SPI0_MEM_INT_RAW_MEM_AXI_RADDR_ERR_INT_RAW_POS 7   // The raw bit for SPI_MEM_AXI_RADDR_ERR_INT interrupt. 1: Triggered when AXI read address is invalid by compared to MMU configuration. 0: Others.
#define SPI0_MEM_INT_RAW_MEM_AXI_RADDR_ERR_INT_RAW_MASK 0x80u
#define SPI0_MEM_INT_RAW_MEM_AXI_WR_FLASH_ERR_INT_RAW_POS 8   // The raw bit for SPI_MEM_AXI_WR_FALSH_ERR_INT interrupt. 1: Triggered when AXI write flash request is received. 0: Others.
#define SPI0_MEM_INT_RAW_MEM_AXI_WR_FLASH_ERR_INT_RAW_MASK 0x100u
#define SPI0_MEM_INT_RAW_MEM_AXI_WADDR_ERR_INT_RAW_POS 9   // The raw bit for SPI_MEM_AXI_WADDR_ERR_INT interrupt. 1: Triggered when AXI write address is invalid by compared to MMU configuration. 0: Others.
#define SPI0_MEM_INT_RAW_MEM_AXI_WADDR_ERR_INT_RAW_MASK 0x200u
#define SPI0_MEM_INT_RAW_MEM_DQS0_AFIFO_OVF_INT_RAW_POS 28   // The raw bit for SPI_MEM_DQS0_AFIFO_OVF_INT interrupt. 1: Triggered when the AFIFO connected to SPI_DQS1 is overflow.
#define SPI0_MEM_INT_RAW_MEM_DQS0_AFIFO_OVF_INT_RAW_MASK 0x10000000ul
#define SPI0_MEM_INT_RAW_MEM_DQS1_AFIFO_OVF_INT_RAW_POS 29   // The raw bit for SPI_MEM_DQS1_AFIFO_OVF_INT interrupt. 1: Triggered when the AFIFO connected to SPI_DQS is overflow.
#define SPI0_MEM_INT_RAW_MEM_DQS1_AFIFO_OVF_INT_RAW_MASK 0x20000000ul
#define SPI0_MEM_INT_RAW_MEM_BUS_FIFO1_UDF_INT_RAW_POS 30   // The raw bit for SPI_MEM_BUS_FIFO1_UDF_INT interrupt. 1: Triggered when BUS1 FIFO is underflow.
#define SPI0_MEM_INT_RAW_MEM_BUS_FIFO1_UDF_INT_RAW_MASK 0x40000000ul
#define SPI0_MEM_INT_RAW_MEM_BUS_FIFO0_UDF_INT_RAW_POS 31   // The raw bit for SPI_MEM_BUS_FIFO0_UDF_INT interrupt. 1: Triggered when BUS0 FIFO is underflow.
#define SPI0_MEM_INT_RAW_MEM_BUS_FIFO0_UDF_INT_RAW_MASK 0x80000000ul

