// SPI0_MEM_DDR: SPI0 flash DDR mode control register (read-write, reset 0x00003020)
#define SPI0_MEM_DDR_ADDRESS 0x600020d4ul
#define SPI0_MEM_DDR (*(volatile uint32_t *)0x600020d4ul)
#define SPI0_MEM_DDR_FMEM_DDR_EN_POS 0   // 1: in DDR mode, 0 in SDR mode
#define SPI0_MEM_DDR_FMEM_DDR_EN_MASK 0x1u
#define SPI0_MEM_DDR_FMEM_VAR_DUMMY_POS 1   // Set the bit to enable variable dummy cycle in spi DDR mode.
#define SPI0_MEM_DDR_FMEM_VAR_DUMMY_MASK 0x2u
#define SPI0_MEM_DDR_FMEM_DDR_RDAT_SWP_POS 2   // Set the bit to reorder rx data of the word in spi DDR mode.
#define SPI0_MEM_DDR_FMEM_DDR_RDAT_SWP_MASK 0x4u
#define SPI0_MEM_DDR_FMEM_DDR_WDAT_SWP_POS 3   // Set the bit to reorder tx data of the word in spi DDR mode.
#define SPI0_MEM_DDR_FMEM_DDR_WDAT_SWP_MASK 0x8u
#define SPI0_MEM_DDR_FMEM_DDR_CMD_DIS_POS 4   // the bit is used to disable dual edge in command phase when DDR mode.
#define SPI0_MEM_DDR_FMEM_DDR_CMD_DIS_MASK 0x10u
#define SPI0_MEM_DDR_FMEM_OUTMINBYTELEN_POS 5   // It is the minimum output data length in the panda device.
#define SPI0_MEM_DDR_FMEM_OUTMINBYTELEN_MASK 0xfe0u
#define SPI0_MEM_DDR_FMEM_OUTMINBYTELEN(value) ((((unsigned long)(value)) << 5) & SPI0_MEM_DDR_FMEM_OUTMINBYTELEN_MASK)
#define SPI0_MEM_DDR_FMEM_TX_DDR_MSK_EN_POS 12   // Set this bit to mask the first or the last byte in SPI0 ECC DDR write mode, when accesses to flash.
#define SPI0_MEM_DDR_FMEM_TX_DDR_MSK_EN_MASK 0x1000u
#define SPI0_MEM_DDR_FMEM_RX_DDR_MSK_EN_POS 13   // Set this bit to mask the first or the last byte in SPI0 ECC DDR read mode, when accesses to flash.
#define SPI0_MEM_DDR_FMEM_RX_DDR_MSK_EN_MASK 0x2000u
#define SPI0_MEM_DDR_FMEM_USR_DDR_DQS_THD_POS 14   // The delay number of data strobe which from memory based on SPI clock.
#define SPI0_MEM_DDR_FMEM_USR_DDR_DQS_THD_MASK 0x1fc000ul
#define SPI0_MEM_DDR_FMEM_USR_DDR_DQS_THD(value) ((((unsigned long)(value)) << 14) & SPI0_MEM_DDR_FMEM_USR_DDR_DQS_THD_MASK)
#define SPI0_MEM_DDR_FMEM_DDR_DQS_LOOP_POS 21   // 1: Do not need the input of SPI_DQS signal, SPI0 starts to receive data when spi0_slv_st is in SPI_MEM_DIN state. It is used when there is no SPI_DQS signal or SPI_DQS signal is not stable. 0: SPI0 starts to store data at the positive and negative edge of SPI_DQS.
#define SPI0_MEM_DDR_FMEM_DDR_DQS_LOOP_MASK 0x200000ul
#define SPI0_MEM_DDR_FMEM_CLK_DIFF_EN_POS 24   // Set this bit to enable the differential SPI_CLK#.
#define SPI0_MEM_DDR_FMEM_CLK_DIFF_EN_MASK 0x1000000ul
#define SPI0_MEM_DDR_FMEM_DQS_CA_IN_POS 26   // Set this bit to enable the input of SPI_DQS signal in SPI phases of CMD and ADDR.
#define SPI0_MEM_DDR_FMEM_DQS_CA_IN_MASK 0x4000000ul
#define SPI0_MEM_DDR_FMEM_HYPERBUS_DUMMY_2X_POS 27   // Set this bit to enable the vary dummy function in SPI HyperBus mode, when SPI0 accesses flash or SPI1 accesses flash or sram.
#define SPI0_MEM_DDR_FMEM_HYPERBUS_DUMMY_2X_MASK 0x8000000ul
#define SPI0_MEM_DDR_FMEM_CLK_DIFF_INV_POS 28   // Set this bit to invert SPI_DIFF when accesses to flash. .
#define SPI0_MEM_DDR_FMEM_CLK_DIFF_INV_MASK 0x10000000ul
#define SPI0_MEM_DDR_FMEM_OCTA_RAM_ADDR_POS 29   // Set this bit to enable octa_ram address out when accesses to flash, which means ADDR_OUT[31:0] = {spi_usr_addr_value[25:4], 6'd0, spi_usr_addr_value[3:1], 1'b0}.
#define SPI0_MEM_DDR_FMEM_OCTA_RAM_ADDR_MASK 0x20000000ul
#define SPI0_MEM_DDR_FMEM_HYPERBUS_CA_POS 30   // Set this bit to enable HyperRAM address out when accesses to flash, which means ADDR_OUT[31:0] = {spi_usr_addr_value[19:4], 13'd0, spi_usr_addr_value[3:1]}.
#define SPI0_MEM_DDR_FMEM_HYPERBUS_CA_MASK 0x40000000ul

// SPI0_SMEM_DDR: SPI0 external RAM DDR mode control register (read-write, reset 0x00003020)
#define SPI0_SMEM_DDR_ADDRESS 0x600020d8ul
