#define SPI0_SMEM_DDR_RDAT_SWP_POS 2   // Set the bit to reorder rx data of the word in spi DDR mode.
#define SPI0_SMEM_DDR_RDAT_SWP_MASK 0x4u
#define SPI0_SMEM_DDR_WDAT_SWP_POS 3   // Set the bit to reorder tx data of the word in spi DDR mode.
