#define SPI0_SMEM_DDR_SMEM_OUTMINBYTELEN_MASK 0xfe0u
#define SPI0_SMEM_DDR_SMEM_OUTMINBYTELEN(value) ((((unsigned long)(value)) << 5) & SPI0_SMEM_DDR_SMEM_OUTMINBYTELEN_MASK)
#define SPI0_SMEM_DDR_SMEM_TX_DDR_MSK_EN_POS 12   // Set this bit to mask the first or the last byte in SPI0 ECC DDR write mode, when accesses to external RAM.
#define SPI0_SMEM_DDR_SMEM_TX_DDR_MSK_EN_MASK 0x1000u
#define SPI0_SMEM_DDR_SMEM_RX_DDR_MSK_EN_POS 13   // Set this bit to mask the first or the last byte in SPI0 ECC DDR read mode, when accesses to external RAM.
#define SPI0_SMEM_DDR_SMEM_RX_DDR_MSK_EN_MASK 0x2000u
#define SPI0_SMEM_DDR_SMEM_USR_DDR_DQS_THD_POS 14   // The delay number of data strobe which from memory based on SPI clock.
