// SPI0_SMEM_AC: MSPI external RAM ECC and SPI CS timing control register (read-write, reset 0x0000b084)
#define SPI0_SMEM_AC_ADDRESS 0x600021a0ul
#define SPI0_SMEM_AC (*(volatile uint32_t *)0x600021a0ul)
#define SPI0_SMEM_AC_SMEM_CS_SETUP_POS 0   // For SPI0 and SPI1, spi cs is enable when spi is in prepare phase. 1: enable 0: disable.
#define SPI0_SMEM_AC_SMEM_CS_SETUP_MASK 0x1u
#define SPI0_SMEM_AC_SMEM_CS_HOLD_POS 1   // For SPI0 and SPI1, spi cs keep low when spi is in done phase. 1: enable 0: disable.
#define SPI0_SMEM_AC_SMEM_CS_HOLD_MASK 0x2u
#define SPI0_SMEM_AC_SMEM_CS_SETUP_TIME_POS 2   // For spi0, (cycles-1) of prepare phase by spi clock this bits are combined with spi_mem_cs_setup bit.
#define SPI0_SMEM_AC_SMEM_CS_SETUP_TIME_MASK 0x7cu
#define SPI0_SMEM_AC_SMEM_CS_SETUP_TIME(value) ((((unsigned long)(value)) << 2) & SPI0_SMEM_AC_SMEM_CS_SETUP_TIME_MASK)
#define SPI0_SMEM_AC_SMEM_CS_HOLD_TIME_POS 7   // For SPI0 and SPI1, spi cs signal is delayed to inactive by spi clock this bits are combined with spi_mem_cs_hold bit.
#define SPI0_SMEM_AC_SMEM_CS_HOLD_TIME_MASK 0xf80u
#define SPI0_SMEM_AC_SMEM_CS_HOLD_TIME(value) ((((unsigned long)(value)) << 7) & SPI0_SMEM_AC_SMEM_CS_HOLD_TIME_MASK)
#define SPI0_SMEM_AC_SMEM_ECC_CS_HOLD_TIME_POS 12   // SPI_SMEM_CS_HOLD_TIME + SPI_SMEM_ECC_CS_HOLD_TIME is the SPI0 and SPI1 CS hold cycles in ECC mode when accessed external RAM.
#define SPI0_SMEM_AC_SMEM_ECC_CS_HOLD_TIME_MASK 0x7000u
#define SPI0_SMEM_AC_SMEM_ECC_CS_HOLD_TIME(value) ((((unsigned long)(value)) << 12) & SPI0_SMEM_AC_SMEM_ECC_CS_HOLD_TIME_MASK)
#define SPI0_SMEM_AC_SMEM_ECC_SKIP_PAGE_CORNER_POS 15   // 1: SPI0 skips page corner when accesses external RAM. 0: Not skip page corner when accesses external RAM.
#define SPI0_SMEM_AC_SMEM_ECC_SKIP_PAGE_CORNER_MASK 0x8000u
#define SPI0_SMEM_AC_SMEM_ECC_16TO18_BYTE_EN_POS 16   // Set this bit to enable SPI0 and SPI1 ECC 16 bytes data with 2 ECC bytes mode when accesses external RAM.
#define SPI0_SMEM_AC_SMEM_ECC_16TO18_BYTE_EN_MASK 0x10000ul
#define SPI0_SMEM_AC_SMEM_CS_HOLD_DELAY_POS 25   // These bits are used to set the minimum CS high time tSHSL between SPI burst transfer when accesses to external RAM. tSHSL is (SPI_SMEM_CS_HOLD_DELAY[5:0] + 1) MSPI core clock cycles.
#define SPI0_SMEM_AC_SMEM_CS_HOLD_DELAY_MASK 0x7e000000ul
#define SPI0_SMEM_AC_SMEM_CS_HOLD_DELAY(value) ((((unsigned long)(value)) << 25) & SPI0_SMEM_AC_SMEM_CS_HOLD_DELAY_MASK)
#define SPI0_SMEM_AC_SMEM_SPLIT_TRANS_EN_POS 31   // Set this bit to enable SPI0 split one AXI accesses EXT_RAM transfer into two SPI transfers when one transfer will cross flash/EXT_RAM page corner, valid no matter whether there is an ECC region or not.
