#define SPI1_SPI_MEM_CMD_SPI_MEM_USR_POS 18   // User define command enable. An operation will be triggered when the bit is set. The bit will be cleared once the operation done.1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_USR_MASK 0x40000ul
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_HPM_POS 19   // Drive Flash into high performance mode. The bit will be cleared once the operation done.1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_HPM_MASK 0x80000ul
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_RES_POS 20   // This bit combined with reg_resandres bit releases Flash from the power-down state or high performance mode and obtains the devices ID. The bit will be cleared once the operation done.1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_RES_MASK 0x100000ul
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_DP_POS 21   // Drive Flash into power down. An operation will be triggered when the bit is set. The bit will be cleared once the operation done.1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_DP_MASK 0x200000ul
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_CE_POS 22   // Chip erase enable. Chip erase operation will be triggered when the bit is set. The bit will be cleared once the operation done.1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_CE_MASK 0x400000ul
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_BE_POS 23   // Block erase enable(32KB) . Block erase operation will be triggered when the bit is set. The bit will be cleared once the operation done.1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_BE_MASK 0x800000ul
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_SE_POS 24   // Sector erase enable(4KB). Sector erase operation will be triggered when the bit is set. The bit will be cleared once the operation done.1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_SE_MASK 0x1000000ul
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_PP_POS 25   // Page program enable(1 byte ~256 bytes data to be programmed). Page program operation will be triggered when the bit is set. The bit will be cleared once the operation done .1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_PP_MASK 0x2000000ul
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_WRSR_POS 26   // Write status register enable. Write status operation will be triggered when the bit is set. The bit will be cleared once the operation done.1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_WRSR_MASK 0x4000000ul
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_RDSR_POS 27   // Read status register-1. Read status operation will be triggered when the bit is set. The bit will be cleared once the operation done.1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_RDSR_MASK 0x8000000ul
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_RDID_POS 28   // Read JEDEC ID . Read ID command will be sent when the bit is set. The bit will be cleared once the operation done. 1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_RDID_MASK 0x10000000ul
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_WRDI_POS 29   // Write flash disable. Write disable command will be sent when the bit is set. The bit will be cleared once the operation done. 1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_WRDI_MASK 0x20000000ul
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_WREN_POS 30   // Write flash enable. Write enable command will be sent when the bit is set. The bit will be cleared once the operation done. 1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_WREN_MASK 0x40000000ul
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_READ_POS 31   // Read flash enable. Read flash operation will be triggered when the bit is set. The bit will be cleared once the operation done. 1: enable 0: disable.
#define SPI1_SPI_MEM_CMD_SPI_MEM_FLASH_READ_MASK 0x80000000ul

// SPI1_SPI_MEM_ADDR: SPI1 address register (read-write, reset 0x00000000)
#define SPI1_SPI_MEM_ADDR_ADDRESS 0x60003004ul
#define SPI1_SPI_MEM_ADDR (*(volatile uint32_t *)0x60003004ul)
#define SPI1_SPI_MEM_ADDR_SPI_MEM_USR_ADDR_VALUE_POS 0   // In user mode, it is the memory address. other then the bit0-bit23 is the memory address, the bit24-bit31 are the byte length of a transfer.
#define SPI1_SPI_MEM_ADDR_SPI_MEM_USR_ADDR_VALUE_MASK 0xfffffffful
#define SPI1_SPI_MEM_ADDR_SPI_MEM_USR_ADDR_VALUE(value) ((((unsigned long)(value)) << 0) & SPI1_SPI_MEM_ADDR_SPI_MEM_USR_ADDR_VALUE_MASK)

// SPI1_SPI_MEM_CTRL: SPI1 control register. (read-write, reset 0x002ca00c)
#define SPI1_SPI_MEM_CTRL_ADDRESS 0x60003008ul
#define SPI1_SPI_MEM_CTRL (*(volatile uint32_t *)0x60003008ul)
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FDUMMY_RIN_POS 2   // In the dummy phase of a MSPI read data transfer when accesses to flash, the signal level of SPI bus is output by the MSPI controller.
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FDUMMY_RIN_MASK 0x4u
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FDUMMY_WOUT_POS 3   // In the dummy phase of a MSPI write data transfer when accesses to flash, the signal level of SPI bus is output by the MSPI controller.
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FDUMMY_WOUT_MASK 0x8u
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FDOUT_OCT_POS 4   // Apply 8 signals during write-data phase 1:enable 0: disable
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FDOUT_OCT_MASK 0x10u
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FDIN_OCT_POS 5   // Apply 8 signals during read-data phase 1:enable 0: disable
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FDIN_OCT_MASK 0x20u
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FADDR_OCT_POS 6   // Apply 8 signals during address phase 1:enable 0: disable
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FADDR_OCT_MASK 0x40u
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FCMD_QUAD_POS 8   // Apply 4 signals during command phase 1:enable 0: disable
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FCMD_QUAD_MASK 0x100u
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FCMD_OCT_POS 9   // Apply 8 signals during command phase 1:enable 0: disable
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FCMD_OCT_MASK 0x200u
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FCS_CRC_EN_POS 10   // For SPI1, initialize crc32 module before writing encrypted data to flash. Active low.
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FCS_CRC_EN_MASK 0x400u
#define SPI1_SPI_MEM_CTRL_SPI_MEM_TX_CRC_EN_POS 11   // For SPI1, enable crc32 when writing encrypted data to flash. 1: enable 0:disable
#define SPI1_SPI_MEM_CTRL_SPI_MEM_TX_CRC_EN_MASK 0x800u
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FASTRD_MODE_POS 13   // This bit enable the bits: spi_mem_fread_qio, spi_mem_fread_dio, spi_mem_fread_qout and spi_mem_fread_dout. 1: enable 0: disable.
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FASTRD_MODE_MASK 0x2000u
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FREAD_DUAL_POS 14   // In the read operations, read-data phase apply 2 signals. 1: enable 0: disable.
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FREAD_DUAL_MASK 0x4000u
#define SPI1_SPI_MEM_CTRL_SPI_MEM_RESANDRES_POS 15   // The Device ID is read out to SPI_MEM_RD_STATUS register, this bit combine with spi_mem_flash_res bit. 1: enable 0: disable.
#define SPI1_SPI_MEM_CTRL_SPI_MEM_RESANDRES_MASK 0x8000u
#define SPI1_SPI_MEM_CTRL_SPI_MEM_Q_POL_POS 18   // The bit is used to set MISO line polarity, 1: high 0, low
#define SPI1_SPI_MEM_CTRL_SPI_MEM_Q_POL_MASK 0x40000ul
#define SPI1_SPI_MEM_CTRL_SPI_MEM_D_POL_POS 19   // The bit is used to set MOSI line polarity, 1: high 0, low
#define SPI1_SPI_MEM_CTRL_SPI_MEM_D_POL_MASK 0x80000ul
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FREAD_QUAD_POS 20   // In the read operations read-data phase apply 4 signals. 1: enable 0: disable.
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FREAD_QUAD_MASK 0x100000ul
#define SPI1_SPI_MEM_CTRL_SPI_MEM_WP_POS 21   // Write protect signal output when SPI is idle. 1: output high, 0: output low.
#define SPI1_SPI_MEM_CTRL_SPI_MEM_WP_MASK 0x200000ul
#define SPI1_SPI_MEM_CTRL_SPI_MEM_WRSR_2B_POS 22   // two bytes data will be written to status register when it is set. 1: enable 0: disable.
#define SPI1_SPI_MEM_CTRL_SPI_MEM_WRSR_2B_MASK 0x400000ul
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FREAD_DIO_POS 23   // In the read operations address phase and read-data phase apply 2 signals. 1: enable 0: disable.
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FREAD_DIO_MASK 0x800000ul
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FREAD_QIO_POS 24   // In the read operations address phase and read-data phase apply 4 signals. 1: enable 0: disable.
#define SPI1_SPI_MEM_CTRL_SPI_MEM_FREAD_QIO_MASK 0x1000000ul

// SPI1_SPI_MEM_CTRL1: SPI1 control1 register. (read-write, reset 0x00000ffc)
#define SPI1_SPI_MEM_CTRL1_ADDRESS 0x6000300cul
#define SPI1_SPI_MEM_CTRL1 (*(volatile uint32_t *)0x6000300cul)
#define SPI1_SPI_MEM_CTRL1_SPI_MEM_CLK_MODE_POS 0   // SPI clock mode bits. 0: SPI clock is off when CS inactive 1: SPI clock is delayed one cycle after CS inactive 2: SPI clock is delayed two cycles after CS inactive 3: SPI clock is alwasy on.
#define SPI1_SPI_MEM_CTRL1_SPI_MEM_CLK_MODE_MASK 0x3u
#define SPI1_SPI_MEM_CTRL1_SPI_MEM_CLK_MODE(value) ((((unsigned long)(value)) << 0) & SPI1_SPI_MEM_CTRL1_SPI_MEM_CLK_MODE_MASK)
#define SPI1_SPI_MEM_CTRL1_SPI_MEM_CS_HOLD_DLY_RES_POS 2   // After RES/DP/HPM command is sent, SPI1 waits (SPI_MEM_CS_HOLD_DELAY_RES[9:0] * 512) SPI_CLK cycles.
#define SPI1_SPI_MEM_CTRL1_SPI_MEM_CS_HOLD_DLY_RES_MASK 0xffcu
#define SPI1_SPI_MEM_CTRL1_SPI_MEM_CS_HOLD_DLY_RES(value) ((((unsigned long)(value)) << 2) & SPI1_SPI_MEM_CTRL1_SPI_MEM_CS_HOLD_DLY_RES_MASK)

// SPI1_SPI_MEM_CTRL2: SPI1 control2 register. (read-write, reset 0x00000000)
#define SPI1_SPI_MEM_CTRL2_ADDRESS 0x60003010ul
#define SPI1_SPI_MEM_CTRL2 (*(volatile uint32_t *)0x60003010ul)
#define SPI1_SPI_MEM_CTRL2_SPI_MEM_SYNC_RESET_POS 31   // The FSM will be reset. (write-only)
#define SPI1_SPI_MEM_CTRL2_SPI_MEM_SYNC_RESET_MASK 0x80000000ul

// SPI1_SPI_MEM_CLOCK: SPI1 clock division control register. (read-write, reset 0x00030103)
#define SPI1_SPI_MEM_CLOCK_ADDRESS 0x60003014ul
#define SPI1_SPI_MEM_CLOCK (*(volatile uint32_t *)0x60003014ul)
#define SPI1_SPI_MEM_CLOCK_SPI_MEM_CLKCNT_L_POS 0   // In the master mode it must be equal to spi_mem_clkcnt_N.
#define SPI1_SPI_MEM_CLOCK_SPI_MEM_CLKCNT_L_MASK 0xffu
#define SPI1_SPI_MEM_CLOCK_SPI_MEM_CLKCNT_L(value) ((((unsigned long)(value)) << 0) & SPI1_SPI_MEM_CLOCK_SPI_MEM_CLKCNT_L_MASK)
#define SPI1_SPI_MEM_CLOCK_SPI_MEM_CLKCNT_H_POS 8   // In the master mode it must be floor((spi_mem_clkcnt_N+1)/2-1).
#define SPI1_SPI_MEM_CLOCK_SPI_MEM_CLKCNT_H_MASK 0xff00u
#define SPI1_SPI_MEM_CLOCK_SPI_MEM_CLKCNT_H(value) ((((unsigned long)(value)) << 8) & SPI1_SPI_MEM_CLOCK_SPI_MEM_CLKCNT_H_MASK)
#define SPI1_SPI_MEM_CLOCK_SPI_MEM_CLKCNT_N_POS 16   // In the master mode it is the divider of spi_mem_clk. So spi_mem_clk frequency is system/(spi_mem_clkcnt_N+1)
#define SPI1_SPI_MEM_CLOCK_SPI_MEM_CLKCNT_N_MASK 0xff0000ul
#define SPI1_SPI_MEM_CLOCK_SPI_MEM_CLKCNT_N(value) ((((unsigned long)(value)) << 16) & SPI1_SPI_MEM_CLOCK_SPI_MEM_CLKCNT_N_MASK)
#define SPI1_SPI_MEM_CLOCK_SPI_MEM_CLK_EQU_SYSCLK_POS 31   // reserved
#define SPI1_SPI_MEM_CLOCK_SPI_MEM_CLK_EQU_SYSCLK_MASK 0x80000000ul

// SPI1_SPI_MEM_USER: SPI1 user register. (read-write, reset 0x80000000)
#define SPI1_SPI_MEM_USER_ADDRESS 0x60003018ul
#define SPI1_SPI_MEM_USER (*(volatile uint32_t *)0x60003018ul)
#define SPI1_SPI_MEM_USER_SPI_MEM_CK_OUT_EDGE_POS 9   // the bit combined with spi_mem_mosi_delay_mode bits to set mosi signal delay mode.
#define SPI1_SPI_MEM_USER_SPI_MEM_CK_OUT_EDGE_MASK 0x200u
#define SPI1_SPI_MEM_USER_SPI_MEM_FWRITE_DUAL_POS 12   // In the write operations read-data phase apply 2 signals
#define SPI1_SPI_MEM_USER_SPI_MEM_FWRITE_DUAL_MASK 0x1000u
#define SPI1_SPI_MEM_USER_SPI_MEM_FWRITE_QUAD_POS 13   // In the write operations read-data phase apply 4 signals
#define SPI1_SPI_MEM_USER_SPI_MEM_FWRITE_QUAD_MASK 0x2000u
#define SPI1_SPI_MEM_USER_SPI_MEM_FWRITE_DIO_POS 14   // In the write operations address phase and read-data phase apply 2 signals.
#define SPI1_SPI_MEM_USER_SPI_MEM_FWRITE_DIO_MASK 0x4000u
#define SPI1_SPI_MEM_USER_SPI_MEM_FWRITE_QIO_POS 15   // In the write operations address phase and read-data phase apply 4 signals.
#define SPI1_SPI_MEM_USER_SPI_MEM_FWRITE_QIO_MASK 0x8000u
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_MISO_HIGHPART_POS 24   // read-data phase only access to high-part of the buffer spi_mem_w8~spi_mem_w15. 1: enable 0: disable.
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_MISO_HIGHPART_MASK 0x1000000ul
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_MOSI_HIGHPART_POS 25   // write-data phase only access to high-part of the buffer spi_mem_w8~spi_mem_w15. 1: enable 0: disable.
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_MOSI_HIGHPART_MASK 0x2000000ul
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_DUMMY_IDLE_POS 26   // SPI clock is disable in dummy phase when the bit is enable.
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_DUMMY_IDLE_MASK 0x4000000ul
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_MOSI_POS 27   // This bit enable the write-data phase of an operation.
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_MOSI_MASK 0x8000000ul
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_MISO_POS 28   // This bit enable the read-data phase of an operation.
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_MISO_MASK 0x10000000ul
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_DUMMY_POS 29   // This bit enable the dummy phase of an operation.
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_DUMMY_MASK 0x20000000ul
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_ADDR_POS 30   // This bit enable the address phase of an operation.
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_ADDR_MASK 0x40000000ul
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_COMMAND_POS 31   // This bit enable the command phase of an operation.
#define SPI1_SPI_MEM_USER_SPI_MEM_USR_COMMAND_MASK 0x80000000ul

// SPI1_SPI_MEM_USER1: SPI1 user1 register. (read-write, reset 0x5c000007)
#define SPI1_SPI_MEM_USER1_ADDRESS 0x6000301cul
#define SPI1_SPI_MEM_USER1 (*(volatile uint32_t *)0x6000301cul)
#define SPI1_SPI_MEM_USER1_SPI_MEM_USR_DUMMY_CYCLELEN_POS 0   // The length in spi_mem_clk cycles of dummy phase. The register value shall be (cycle_num-1).
#define SPI1_SPI_MEM_USER1_SPI_MEM_USR_DUMMY_CYCLELEN_MASK 0x3fu
