#define SPI1_SPI_MEM_USER1_SPI_MEM_USR_ADDR_BITLEN_POS 26   // The length in bits of address phase. The register value shall be (bit_num-1).
#define SPI1_SPI_MEM_USER1_SPI_MEM_USR_ADDR_BITLEN_MASK 0xfc000000ul
#define SPI1_SPI_MEM_USER1_SPI_MEM_USR_ADDR_BITLEN(value) ((((unsigned long)(value)) << 26) & SPI1_SPI_MEM_USER1_SPI_MEM_USR_ADDR_BITLEN_MASK)

// SPI1_SPI_MEM_USER2: SPI1 user2 register. (read-write, reset 0x70000000)
