#define SPI1_SPI_MEM_USER2_SPI_MEM_USR_COMMAND_VALUE_POS 0   // The value of command.
#define SPI1_SPI_MEM_USER2_SPI_MEM_USR_COMMAND_VALUE_MASK 0xffffu
#define SPI1_SPI_MEM_USER2_SPI_MEM_USR_COMMAND_VALUE(value) ((((unsigned long)(value)) << 0) & SPI1_SPI_MEM_USER2_SPI_MEM_USR_COMMAND_VALUE_MASK)
#define SPI1_SPI_MEM_USER2_SPI_MEM_USR_COMMAND_BITLEN_POS 28   // The length in bits of command phase. The register value shall be (bit_num-1)
#define SPI1_SPI_MEM_USER2_SPI_MEM_USR_COMMAND_BITLEN_MASK 0xf0000000ul
#define SPI1_SPI_MEM_USER2_SPI_MEM_USR_COMMAND_BITLEN(value) ((((unsigned long)(value)) << 28) & SPI1_SPI_MEM_USER2_SPI_MEM_USR_COMMAND_BITLEN_MASK)

// SPI1_SPI_MEM_MOSI_DLEN: SPI1 send data bit length control register. (read-write, reset 0x00000000)
