#define SPI1_SPI_MEM_MOSI_DLEN_SPI_MEM_USR_MOSI_DBITLEN_POS 0   // The length in bits of write-data. The register value shall be (bit_num-1).
#define SPI1_SPI_MEM_MOSI_DLEN_SPI_MEM_USR_MOSI_DBITLEN_MASK 0x3ffu
#define SPI1_SPI_MEM_MOSI_DLEN_SPI_MEM_USR_MOSI_DBITLEN(value) ((((unsigned long)(value)) << 0) & SPI1_SPI_MEM_MOSI_DLEN_SPI_MEM_USR_MOSI_DBITLEN_MASK)

// SPI1_SPI_MEM_MISO_DLEN: SPI1 receive data bit length control register. (read-write, reset 0x00000000)
