#define SPI1_SPI_MEM_MISO_DLEN_SPI_MEM_USR_MISO_DBITLEN(value) ((((unsigned long)(value)) << 0) & SPI1_SPI_MEM_MISO_DLEN_SPI_MEM_USR_MISO_DBITLEN_MASK)

// SPI1_SPI_MEM_RD_STATUS: SPI1 status register. (read-write, reset 0x00000000)
