#define SPI1_SPI_MEM_RD_STATUS_SPI_MEM_WB_MODE_POS 16   // Mode bits in the flash fast read mode it is combined with spi_mem_fastrd_mode bit.
#define SPI1_SPI_MEM_RD_STATUS_SPI_MEM_WB_MODE_MASK 0xff0000ul
