#define SPI1_SPI_MEM_RD_STATUS_SPI_MEM_WB_MODE_BITLEN(value) ((((unsigned long)(value)) << 24) & SPI1_SPI_MEM_RD_STATUS_SPI_MEM_WB_MODE_BITLEN_MASK)
#define SPI1_SPI_MEM_RD_STATUS_SPI_MEM_WB_MODE_EN_POS 27   // Mode bits is valid while this bit is enable. 1: enable 0: disable.
