#define SPI1_SPI_MEM_CACHE_FCTRL_SPI_MEM_FDOUT_DUAL_POS 4   // For SPI1, dout phase apply 2 signals. 1: enable 0: disable. The bit is the same with spi_mem_fread_dio.
#define SPI1_SPI_MEM_CACHE_FCTRL_SPI_MEM_FDOUT_DUAL_MASK 0x10u
