#define SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_EN_POS 0   // 1: The hardware will wait idle after SE/PP/WRSR automatically, and hardware auto Suspend/Resume can be enabled. 0: The functions of hardware wait idle and auto Suspend/Resume are not supported.
#define SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_EN_MASK 0x1u
