#define SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_ADDR_EN_POS 2   // 1: Output address 0 in RDSR or read SUS command transfer. 0: Do not send out address in RDSR or read SUS command transfer.
#define SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_ADDR_EN_MASK 0x4u
#define SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_ADDR_CYCLELEN_POS 3   // When SPI_MEM_WAITI_ADDR_EN is set, the cycle length of sent out address is (SPI_MEM_WAITI_ADDR_CYCLELEN[1:0] + 1) SPI bus clock cycles. It is not active when SPI_MEM_WAITI_ADDR_EN is cleared.
