#define SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_ADDR_CYCLELEN(value) ((((unsigned long)(value)) << 3) & SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_ADDR_CYCLELEN_MASK)
#define SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_CMD_2B_POS 9   // 1:The wait idle command bit length is 16. 0: The wait idle command bit length is 8.
#define SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_CMD_2B_MASK 0x200u
#define SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_DUMMY_CYCLELEN_POS 10   // The dummy cycle length when wait flash idle(RDSR).
#define SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_DUMMY_CYCLELEN_MASK 0xfc00u
#define SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_DUMMY_CYCLELEN(value) ((((unsigned long)(value)) << 10) & SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_DUMMY_CYCLELEN_MASK)
#define SPI1_SPI_MEM_FLASH_WAITI_CTRL_SPI_MEM_WAITI_CMD_POS 16   // The command value to wait flash idle(RDSR).
