// SPI1_SPI_MEM_FLASH_SUS_CTRL: SPI1 flash suspend control register (read-write, reset 0x08002000)
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_ADDRESS 0x6000309cul
#define SPI1_SPI_MEM_FLASH_SUS_CTRL (*(volatile uint32_t *)0x6000309cul)
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_FLASH_PER_POS 0   // program erase resume bit, program erase suspend operation will be triggered when the bit is set. The bit will be cleared once the operation done.1: enable 0: disable.
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_FLASH_PER_MASK 0x1u
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_FLASH_PES_POS 1   // program erase suspend bit, program erase suspend operation will be triggered when the bit is set. The bit will be cleared once the operation done.1: enable 0: disable.
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_FLASH_PES_MASK 0x2u
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_FLASH_PER_WAIT_EN_POS 2   // 1: SPI1 waits (SPI_MEM_CS_HOLD_DELAY_RES[9:0] * 4 or *128) SPI_CLK cycles after program erase resume command is sent. 0: SPI1 does not wait after program erase resume command is sent.
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_FLASH_PER_WAIT_EN_MASK 0x4u
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_FLASH_PES_WAIT_EN_POS 3   // 1: SPI1 waits (SPI_MEM_CS_HOLD_DELAY_RES[9:0] * 4 or *128) SPI_CLK cycles after program erase suspend command is sent. 0: SPI1 does not wait after program erase suspend command is sent.
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_FLASH_PES_WAIT_EN_MASK 0x8u
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_PES_PER_EN_POS 4   // Set this bit to enable PES end triggers PER transfer option. If this bit is 0, application should send PER after PES is done.
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_PES_PER_EN_MASK 0x10u
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_FLASH_PES_EN_POS 5   // Set this bit to enable Auto-suspending function.
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_FLASH_PES_EN_MASK 0x20u
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_PESR_END_MSK_POS 6   // The mask value when check SUS/SUS1/SUS2 status bit. If the read status value is status_in[15:0](only status_in[7:0] is valid when only one byte of data is read out, status_in[15:0] is valid when two bytes of data are read out), SUS/SUS1/SUS2 = status_in[15:0]^ SPI_MEM_PESR_END_MSK[15:0].
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_PESR_END_MSK_MASK 0x3fffc0ul
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_PESR_END_MSK(value) ((((unsigned long)(value)) << 6) & SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_PESR_END_MSK_MASK)
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_FMEM_RD_SUS_2B_POS 22   // 1: Read two bytes when check flash SUS/SUS1/SUS2 status bit. 0: Read one byte when check flash SUS/SUS1/SUS2 status bit
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_FMEM_RD_SUS_2B_MASK 0x400000ul
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_PER_END_EN_POS 23   // 1: Both WIP and SUS/SUS1/SUS2 bits should be checked to insure the resume status of flash. 0: Only need to check WIP is 0.
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_PER_END_EN_MASK 0x800000ul
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_PES_END_EN_POS 24   // 1: Both WIP and SUS/SUS1/SUS2 bits should be checked to insure the suspend status of flash. 0: Only need to check WIP is 0.
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_PES_END_EN_MASK 0x1000000ul
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_SUS_TIMEOUT_CNT_POS 25   // When SPI1 checks SUS/SUS1/SUS2 bits fail for SPI_MEM_SUS_TIMEOUT_CNT[6:0] times, it will be treated as check pass.
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_SUS_TIMEOUT_CNT_MASK 0xfe000000ul
#define SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_SUS_TIMEOUT_CNT(value) ((((unsigned long)(value)) << 25) & SPI1_SPI_MEM_FLASH_SUS_CTRL_SPI_MEM_SUS_TIMEOUT_CNT_MASK)

// SPI1_SPI_MEM_FLASH_SUS_CMD: SPI1 flash suspend command register (read-write, reset 0x00057575)
#define SPI1_SPI_MEM_FLASH_SUS_CMD_ADDRESS 0x600030a0ul
#define SPI1_SPI_MEM_FLASH_SUS_CMD (*(volatile uint32_t *)0x600030a0ul)
#define SPI1_SPI_MEM_FLASH_SUS_CMD_SPI_MEM_FLASH_PES_COMMAND_POS 0   // Program/Erase suspend command.
