// SPI1_SPI_MEM_SUS_STATUS: SPI1 flash suspend status register (read-write, reset 0x7a7a0000)
#define SPI1_SPI_MEM_SUS_STATUS_ADDRESS 0x600030a4ul
#define SPI1_SPI_MEM_SUS_STATUS (*(volatile uint32_t *)0x600030a4ul)
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_SUS_POS 0   // The status of flash suspend, only used in SPI1.
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_SUS_MASK 0x1u
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_WAIT_PESR_CMD_2B_POS 1   // 1: SPI1 sends out SPI_MEM_WAIT_PESR_COMMAND[15:0] to check SUS/SUS1/SUS2 bit. 0: SPI1 sends out SPI_MEM_WAIT_PESR_COMMAND[7:0] to check SUS/SUS1/SUS2 bit.
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_WAIT_PESR_CMD_2B_MASK 0x2u
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_HPM_DLY_128_POS 2   // 1: SPI1 waits (SPI_MEM_CS_HOLD_DELAY_RES[9:0] * 128) SPI_CLK cycles after HPM command is sent. 0: SPI1 waits (SPI_MEM_CS_HOLD_DELAY_RES[9:0] * 4) SPI_CLK cycles after HPM command is sent.
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_HPM_DLY_128_MASK 0x4u
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_RES_DLY_128_POS 3   // 1: SPI1 waits (SPI_MEM_CS_HOLD_DELAY_RES[9:0] * 128) SPI_CLK cycles after RES command is sent. 0: SPI1 waits (SPI_MEM_CS_HOLD_DELAY_RES[9:0] * 4) SPI_CLK cycles after RES command is sent.
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_RES_DLY_128_MASK 0x8u
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_DP_DLY_128_POS 4   // 1: SPI1 waits (SPI_MEM_CS_HOLD_DELAY_RES[9:0] * 128) SPI_CLK cycles after DP command is sent. 0: SPI1 waits (SPI_MEM_CS_HOLD_DELAY_RES[9:0] * 4) SPI_CLK cycles after DP command is sent.
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_DP_DLY_128_MASK 0x10u
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_PER_DLY_128_POS 5   // Valid when SPI_MEM_FLASH_PER_WAIT_EN is 1. 1: SPI1 waits (SPI_MEM_CS_HOLD_DELAY_RES[9:0] * 128) SPI_CLK cycles after PER command is sent. 0: SPI1 waits (SPI_MEM_CS_HOLD_DELAY_RES[9:0] * 4) SPI_CLK cycles after PER command is sent.
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_PER_DLY_128_MASK 0x20u
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_PES_DLY_128_POS 6   // Valid when SPI_MEM_FLASH_PES_WAIT_EN is 1. 1: SPI1 waits (SPI_MEM_CS_HOLD_DELAY_RES[9:0] * 128) SPI_CLK cycles after PES command is sent. 0: SPI1 waits (SPI_MEM_CS_HOLD_DELAY_RES[9:0] * 4) SPI_CLK cycles after PES command is sent.
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_PES_DLY_128_MASK 0x40u
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_SPI0_LOCK_EN_POS 7   // 1: Enable SPI0 lock SPI0/1 arbiter option. 0: Disable it.
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_SPI0_LOCK_EN_MASK 0x80u
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_PESR_CMD_2B_POS 15   // 1: The bit length of Program/Erase Suspend/Resume command is 16. 0: The bit length of Program/Erase Suspend/Resume command is 8.
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_PESR_CMD_2B_MASK 0x8000u
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_PER_COMMAND_POS 16   // Program/Erase resume command.
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_PER_COMMAND_MASK 0xffff0000ul
#define SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_PER_COMMAND(value) ((((unsigned long)(value)) << 16) & SPI1_SPI_MEM_SUS_STATUS_SPI_MEM_FLASH_PER_COMMAND_MASK)

