#define SPI1_SPI_MEM_INT_ENA_SPI_MEM_PES_END_INT_ENA_POS 1   // The enable bit for SPI_MEM_PES_END_INT interrupt.
#define SPI1_SPI_MEM_INT_ENA_SPI_MEM_PES_END_INT_ENA_MASK 0x2u
#define SPI1_SPI_MEM_INT_ENA_SPI_MEM_WPE_END_INT_ENA_POS 2   // The enable bit for SPI_MEM_WPE_END_INT interrupt.
#define SPI1_SPI_MEM_INT_ENA_SPI_MEM_WPE_END_INT_ENA_MASK 0x4u
#define SPI1_SPI_MEM_INT_ENA_SPI_MEM_SLV_ST_END_INT_ENA_POS 3   // The enable bit for SPI_MEM_SLV_ST_END_INT interrupt.
#define SPI1_SPI_MEM_INT_ENA_SPI_MEM_SLV_ST_END_INT_ENA_MASK 0x8u
#define SPI1_SPI_MEM_INT_ENA_SPI_MEM_MST_ST_END_INT_ENA_POS 4   // The enable bit for SPI_MEM_MST_ST_END_INT interrupt.
#define SPI1_SPI_MEM_INT_ENA_SPI_MEM_MST_ST_END_INT_ENA_MASK 0x10u
#define SPI1_SPI_MEM_INT_ENA_SPI_MEM_BROWN_OUT_INT_ENA_POS 10   // The enable bit for SPI_MEM_BROWN_OUT_INT interrupt.
#define SPI1_SPI_MEM_INT_ENA_SPI_MEM_BROWN_OUT_INT_ENA_MASK 0x400u

// SPI1_SPI_MEM_INT_CLR: SPI1 interrupt clear register (read-write, reset 0x00000000)
#define SPI1_SPI_MEM_INT_CLR_ADDRESS 0x600030c4ul
#define SPI1_SPI_MEM_INT_CLR (*(volatile uint32_t *)0x600030c4ul)
#define SPI1_SPI_MEM_INT_CLR_SPI_MEM_PER_END_INT_CLR_POS 0   // The clear bit for SPI_MEM_PER_END_INT interrupt. (write-only)
#define SPI1_SPI_MEM_INT_CLR_SPI_MEM_PER_END_INT_CLR_MASK 0x1u
#define SPI1_SPI_MEM_INT_CLR_SPI_MEM_PES_END_INT_CLR_POS 1   // The clear bit for SPI_MEM_PES_END_INT interrupt. (write-only)
#define SPI1_SPI_MEM_INT_CLR_SPI_MEM_PES_END_INT_CLR_MASK 0x2u
#define SPI1_SPI_MEM_INT_CLR_SPI_MEM_WPE_END_INT_CLR_POS 2   // The clear bit for SPI_MEM_WPE_END_INT interrupt. (write-only)
#define SPI1_SPI_MEM_INT_CLR_SPI_MEM_WPE_END_INT_CLR_MASK 0x4u
#define SPI1_SPI_MEM_INT_CLR_SPI_MEM_SLV_ST_END_INT_CLR_POS 3   // The clear bit for SPI_MEM_SLV_ST_END_INT interrupt. (write-only)
#define SPI1_SPI_MEM_INT_CLR_SPI_MEM_SLV_ST_END_INT_CLR_MASK 0x8u
#define SPI1_SPI_MEM_INT_CLR_SPI_MEM_MST_ST_END_INT_CLR_POS 4   // The clear bit for SPI_MEM_MST_ST_END_INT interrupt. (write-only)
#define SPI1_SPI_MEM_INT_CLR_SPI_MEM_MST_ST_END_INT_CLR_MASK 0x10u
#define SPI1_SPI_MEM_INT_CLR_SPI_MEM_BROWN_OUT_INT_CLR_POS 10   // The status bit for SPI_MEM_BROWN_OUT_INT interrupt. (write-only)
#define SPI1_SPI_MEM_INT_CLR_SPI_MEM_BROWN_OUT_INT_CLR_MASK 0x400u

// SPI1_SPI_MEM_INT_RAW: SPI1 interrupt raw register (read-write, reset 0x00000000)
#define SPI1_SPI_MEM_INT_RAW_ADDRESS 0x600030c8ul
#define SPI1_SPI_MEM_INT_RAW (*(volatile uint32_t *)0x600030c8ul)
#define SPI1_SPI_MEM_INT_RAW_SPI_MEM_PER_END_INT_RAW_POS 0   // The raw bit for SPI_MEM_PER_END_INT interrupt. 1: Triggered when Auto Resume command (0x7A) is sent and flash is resumed successfully. 0: Others.
#define SPI1_SPI_MEM_INT_RAW_SPI_MEM_PER_END_INT_RAW_MASK 0x1u
#define SPI1_SPI_MEM_INT_RAW_SPI_MEM_PES_END_INT_RAW_POS 1   // The raw bit for SPI_MEM_PES_END_INT interrupt.1: Triggered when Auto Suspend command (0x75) is sent and flash is suspended successfully. 0: Others.
#define SPI1_SPI_MEM_INT_RAW_SPI_MEM_PES_END_INT_RAW_MASK 0x2u
#define SPI1_SPI_MEM_INT_RAW_SPI_MEM_WPE_END_INT_RAW_POS 2   // The raw bit for SPI_MEM_WPE_END_INT interrupt. 1: Triggered when WRSR/PP/SE/BE/CE is sent and flash is already idle. 0: Others.
#define SPI1_SPI_MEM_INT_RAW_SPI_MEM_WPE_END_INT_RAW_MASK 0x4u
#define SPI1_SPI_MEM_INT_RAW_SPI_MEM_SLV_ST_END_INT_RAW_POS 3   // The raw bit for SPI_MEM_SLV_ST_END_INT interrupt. 1: Triggered when spi1_slv_st is changed from non idle state to idle state. It means that SPI_CS raises high. 0: Others
#define SPI1_SPI_MEM_INT_RAW_SPI_MEM_SLV_ST_END_INT_RAW_MASK 0x8u
#define SPI1_SPI_MEM_INT_RAW_SPI_MEM_MST_ST_END_INT_RAW_POS 4   // The raw bit for SPI_MEM_MST_ST_END_INT interrupt. 1: Triggered when spi1_mst_st is changed from non idle state to idle state. 0: Others.
#define SPI1_SPI_MEM_INT_RAW_SPI_MEM_MST_ST_END_INT_RAW_MASK 0x10u
#define SPI1_SPI_MEM_INT_RAW_SPI_MEM_BROWN_OUT_INT_RAW_POS 10   // The raw bit for SPI_MEM_BROWN_OUT_INT interrupt. 1: Triggered condition is that chip is loosing power and RTC module sends out brown out close flash request to SPI1. After SPI1 sends out suspend command to flash, this interrupt is triggered and MSPI returns to idle state. 0: Others.
#define SPI1_SPI_MEM_INT_RAW_SPI_MEM_BROWN_OUT_INT_RAW_MASK 0x400u

// SPI1_SPI_MEM_INT_ST: SPI1 interrupt status register (read-write, reset 0x00000000)
#define SPI1_SPI_MEM_INT_ST_ADDRESS 0x600030ccul
#define SPI1_SPI_MEM_INT_ST (*(volatile uint32_t *)0x600030ccul)
#define SPI1_SPI_MEM_INT_ST_SPI_MEM_PER_END_INT_ST_POS 0   // The status bit for SPI_MEM_PER_END_INT interrupt. (read-only)
#define SPI1_SPI_MEM_INT_ST_SPI_MEM_PER_END_INT_ST_MASK 0x1u
#define SPI1_SPI_MEM_INT_ST_SPI_MEM_PES_END_INT_ST_POS 1   // The status bit for SPI_MEM_PES_END_INT interrupt. (read-only)
#define SPI1_SPI_MEM_INT_ST_SPI_MEM_PES_END_INT_ST_MASK 0x2u
#define SPI1_SPI_MEM_INT_ST_SPI_MEM_WPE_END_INT_ST_POS 2   // The status bit for SPI_MEM_WPE_END_INT interrupt. (read-only)
#define SPI1_SPI_MEM_INT_ST_SPI_MEM_WPE_END_INT_ST_MASK 0x4u
#define SPI1_SPI_MEM_INT_ST_SPI_MEM_SLV_ST_END_INT_ST_POS 3   // The status bit for SPI_MEM_SLV_ST_END_INT interrupt. (read-only)
#define SPI1_SPI_MEM_INT_ST_SPI_MEM_SLV_ST_END_INT_ST_MASK 0x8u
#define SPI1_SPI_MEM_INT_ST_SPI_MEM_MST_ST_END_INT_ST_POS 4   // The status bit for SPI_MEM_MST_ST_END_INT interrupt. (read-only)
#define SPI1_SPI_MEM_INT_ST_SPI_MEM_MST_ST_END_INT_ST_MASK 0x10u
#define SPI1_SPI_MEM_INT_ST_SPI_MEM_BROWN_OUT_INT_ST_POS 10   // The status bit for SPI_MEM_BROWN_OUT_INT interrupt. (read-only)
#define SPI1_SPI_MEM_INT_ST_SPI_MEM_BROWN_OUT_INT_ST_MASK 0x400u

// SPI1_SPI_MEM_DDR: SPI1 DDR control register (read-write, reset 0x00000020)
#define SPI1_SPI_MEM_DDR_ADDRESS 0x600030d4ul
#define SPI1_SPI_MEM_DDR (*(volatile uint32_t *)0x600030d4ul)
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_DDR_EN_POS 0   // 1: in ddr mode, 0 in sdr mode
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_DDR_EN_MASK 0x1u
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_VAR_DUMMY_POS 1   // Set the bit to enable variable dummy cycle in spi ddr mode.
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_VAR_DUMMY_MASK 0x2u
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_DDR_RDAT_SWP_POS 2   // Set the bit to reorder rx data of the word in spi ddr mode.
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_DDR_RDAT_SWP_MASK 0x4u
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_DDR_WDAT_SWP_POS 3   // Set the bit to reorder tx data of the word in spi ddr mode.
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_DDR_WDAT_SWP_MASK 0x8u
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_DDR_CMD_DIS_POS 4   // the bit is used to disable dual edge in command phase when ddr mode.
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_DDR_CMD_DIS_MASK 0x10u
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_OUTMINBYTELEN_POS 5   // It is the minimum output data length in the panda device.
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_OUTMINBYTELEN_MASK 0xfe0u
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_OUTMINBYTELEN(value) ((((unsigned long)(value)) << 5) & SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_OUTMINBYTELEN_MASK)
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_USR_DDR_DQS_THD_POS 14   // The delay number of data strobe which from memory based on SPI clock.
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_USR_DDR_DQS_THD_MASK 0x1fc000ul
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_USR_DDR_DQS_THD(value) ((((unsigned long)(value)) << 14) & SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_USR_DDR_DQS_THD_MASK)
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_DDR_DQS_LOOP_POS 21   // 1: Do not need the input of SPI_DQS signal, SPI0 starts to receive data when spi0_slv_st is in SPI_MEM_DIN state. It is used when there is no SPI_DQS signal or SPI_DQS signal is not stable. 0: SPI0 starts to store data at the positive and negative edge of SPI_DQS.
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_DDR_DQS_LOOP_MASK 0x200000ul
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_CLK_DIFF_EN_POS 24   // Set this bit to enable the differential SPI_CLK#.
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_CLK_DIFF_EN_MASK 0x1000000ul
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_DQS_CA_IN_POS 26   // Set this bit to enable the input of SPI_DQS signal in SPI phases of CMD and ADDR.
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_DQS_CA_IN_MASK 0x4000000ul
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_HYPERBUS_DUMMY_2X_POS 27   // Set this bit to enable the vary dummy function in SPI HyperBus mode, when SPI0 accesses flash or SPI1 accesses flash or sram.
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_HYPERBUS_DUMMY_2X_MASK 0x8000000ul
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_CLK_DIFF_INV_POS 28   // Set this bit to invert SPI_DIFF when accesses to flash. .
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_CLK_DIFF_INV_MASK 0x10000000ul
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_OCTA_RAM_ADDR_POS 29   // Set this bit to enable octa_ram address out when accesses to flash, which means ADDR_OUT[31:0] = {spi_usr_addr_value[25:4], 6'd0, spi_usr_addr_value[3:1], 1'b0}.
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_OCTA_RAM_ADDR_MASK 0x20000000ul
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_HYPERBUS_CA_POS 30   // Set this bit to enable HyperRAM address out when accesses to flash, which means ADDR_OUT[31:0] = {spi_usr_addr_value[19:4], 13'd0, spi_usr_addr_value[3:1]}.
#define SPI1_SPI_MEM_DDR_SPI_MEM_FMEM_HYPERBUS_CA_MASK 0x40000000ul

// SPI1_SPI_MEM_TIMING_CALI: SPI1 timing control register (read-write, reset 0x00000000)
#define SPI1_SPI_MEM_TIMING_CALI_ADDRESS 0x60003180ul
#define SPI1_SPI_MEM_TIMING_CALI (*(volatile uint32_t *)0x60003180ul)
#define SPI1_SPI_MEM_TIMING_CALI_SPI_MEM_TIMING_CALI_POS 1   // The bit is used to enable timing auto-calibration for all reading operations.
#define SPI1_SPI_MEM_TIMING_CALI_SPI_MEM_TIMING_CALI_MASK 0x2u
#define SPI1_SPI_MEM_TIMING_CALI_SPI_MEM_EXTRA_DUMMY_CYCLELEN_POS 2   // add extra dummy spi clock cycle length for spi clock calibration.
#define SPI1_SPI_MEM_TIMING_CALI_SPI_MEM_EXTRA_DUMMY_CYCLELEN_MASK 0x1cu
#define SPI1_SPI_MEM_TIMING_CALI_SPI_MEM_EXTRA_DUMMY_CYCLELEN(value) ((((unsigned long)(value)) << 2) & SPI1_SPI_MEM_TIMING_CALI_SPI_MEM_EXTRA_DUMMY_CYCLELEN_MASK)

// SPI1_SPI_MEM_CLOCK_GATE: SPI1 clk_gate register (read-write, reset 0x00000001)
