// ---- SPI2: SPI (Serial Peripheral Interface) Controller 2

// SPI2_SPI_CMD: Command control register (read-write, reset 0x00000000)
#define SPI2_SPI_CMD_ADDRESS 0x60081000ul
#define SPI2_SPI_CMD (*(volatile uint32_t *)0x60081000ul)
#define SPI2_SPI_CMD_SPI_CONF_BITLEN_POS 0   // Configures the SPI_CLK cycles of SPI CONF state. Measurement unit: SPI_CLK clock cycle. Can be configured in CONF state.
#define SPI2_SPI_CMD_SPI_CONF_BITLEN_MASK 0x3fffful
#define SPI2_SPI_CMD_SPI_CONF_BITLEN(value) ((((unsigned long)(value)) << 0) & SPI2_SPI_CMD_SPI_CONF_BITLEN_MASK)
#define SPI2_SPI_CMD_SPI_UPDATE_POS 23   // Configures whether or not to synchronize SPI registers from APB clock domain into SPI module clock domain. 0: Not synchronize; 1: Synchronize; This bit is only used in SPI master transfer. (write-only)
#define SPI2_SPI_CMD_SPI_UPDATE_MASK 0x800000ul
#define SPI2_SPI_CMD_SPI_USR_POS 24   // Configures whether or not to enable user-defined command. 0: Not enable; 1: Enable; An SPI operation will be triggered when the bit is set. This bit will be cleared once the operation is done. Can not be changed by CONF_buf.
#define SPI2_SPI_CMD_SPI_USR_MASK 0x1000000ul

// SPI2_SPI_ADDR: Address value register (read-write, reset 0x00000000)
#define SPI2_SPI_ADDR_ADDRESS 0x60081004ul
#define SPI2_SPI_ADDR (*(volatile uint32_t *)0x60081004ul)
#define SPI2_SPI_ADDR_SPI_USR_ADDR_VALUE_POS 0   // Configures the address to slave. Can be configured in CONF state.
#define SPI2_SPI_ADDR_SPI_USR_ADDR_VALUE_MASK 0xfffffffful
#define SPI2_SPI_ADDR_SPI_USR_ADDR_VALUE(value) ((((unsigned long)(value)) << 0) & SPI2_SPI_ADDR_SPI_USR_ADDR_VALUE_MASK)

// SPI2_SPI_CTRL: SPI control register (read-write, reset 0x003c0000)
#define SPI2_SPI_CTRL_ADDRESS 0x60081008ul
#define SPI2_SPI_CTRL (*(volatile uint32_t *)0x60081008ul)
#define SPI2_SPI_CTRL_SPI_DUMMY_OUT_POS 3   // Configures whether or not to output the FSPI bus signals in DUMMY state. 0: Not output; 1: Output; Can be configured in CONF state.
#define SPI2_SPI_CTRL_SPI_DUMMY_OUT_MASK 0x8u
#define SPI2_SPI_CTRL_SPI_FADDR_DUAL_POS 5   // Configures whether or not to enable 2-bit mode during address (ADDR) state. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_CTRL_SPI_FADDR_DUAL_MASK 0x20u
#define SPI2_SPI_CTRL_SPI_FADDR_QUAD_POS 6   // Configures whether or not to enable 4-bit mode during address (ADDR) state. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_CTRL_SPI_FADDR_QUAD_MASK 0x40u
#define SPI2_SPI_CTRL_SPI_FADDR_OCT_POS 7   // Configures whether or not to enable 8-bit mode during address (ADDR) state. 0: Disable; 1: Enable; Can be configured in CONF state. (read-only)
#define SPI2_SPI_CTRL_SPI_FADDR_OCT_MASK 0x80u
#define SPI2_SPI_CTRL_SPI_FCMD_DUAL_POS 8   // Configures whether or not to enable 2-bit mode during command (CMD) state. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_CTRL_SPI_FCMD_DUAL_MASK 0x100u
#define SPI2_SPI_CTRL_SPI_FCMD_QUAD_POS 9   // Configures whether or not to enable 4-bit mode during command (CMD) state. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_CTRL_SPI_FCMD_QUAD_MASK 0x200u
#define SPI2_SPI_CTRL_SPI_FCMD_OCT_POS 10   // Configures whether or not to enable 8-bit mode during command (CMD) state. 0: Disable; 1: Enable; Can be configured in CONF state. (read-only)
#define SPI2_SPI_CTRL_SPI_FCMD_OCT_MASK 0x400u
#define SPI2_SPI_CTRL_SPI_FREAD_DUAL_POS 14   // Configures whether or not to enable the 2-bit mode of read-data (DIN) state in read operations. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_CTRL_SPI_FREAD_DUAL_MASK 0x4000u
#define SPI2_SPI_CTRL_SPI_FREAD_QUAD_POS 15   // Configures whether or not to enable the 4-bit mode of read-data (DIN) state in read operations. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_CTRL_SPI_FREAD_QUAD_MASK 0x8000u
#define SPI2_SPI_CTRL_SPI_FREAD_OCT_POS 16   // Configures whether or not to enable the 8-bit mode of read-data (DIN) state in read operations. 0: Disable; 1: Enable; Can be configured in CONF state. (read-only)
#define SPI2_SPI_CTRL_SPI_FREAD_OCT_MASK 0x10000ul
#define SPI2_SPI_CTRL_SPI_Q_POL_POS 18   // Configures MISO line polarity. 0: Low; 1: High; Can be configured in CONF state.
#define SPI2_SPI_CTRL_SPI_Q_POL_MASK 0x40000ul
#define SPI2_SPI_CTRL_SPI_D_POL_POS 19   // Configures MOSI line polarity. 0: Low; 1: High; Can be configured in CONF state.
#define SPI2_SPI_CTRL_SPI_D_POL_MASK 0x80000ul
#define SPI2_SPI_CTRL_SPI_HOLD_POL_POS 20   // Configures SPI_HOLD output value when SPI is in idle. 0: Output low; 1: Output high; Can be configured in CONF state.
#define SPI2_SPI_CTRL_SPI_HOLD_POL_MASK 0x100000ul
#define SPI2_SPI_CTRL_SPI_WP_POL_POS 21   // Configures the output value of write-protect signal when SPI is in idle. 0: Output low; 1: Output high; Can be configured in CONF state.
#define SPI2_SPI_CTRL_SPI_WP_POL_MASK 0x200000ul
#define SPI2_SPI_CTRL_SPI_RD_BIT_ORDER_POS 23   // Configures the bit order in read-data (MISO) state. 0: MSB first; 1: LSB first; Can be configured in CONF state.
#define SPI2_SPI_CTRL_SPI_RD_BIT_ORDER_MASK 0x1800000ul
#define SPI2_SPI_CTRL_SPI_RD_BIT_ORDER(value) ((((unsigned long)(value)) << 23) & SPI2_SPI_CTRL_SPI_RD_BIT_ORDER_MASK)
#define SPI2_SPI_CTRL_SPI_WR_BIT_ORDER_POS 25   // Configures the bit order in command (CMD), address (ADDR), and write-data (MOSI) states. 0: MSB first; 1: LSB first; Can be configured in CONF state.
#define SPI2_SPI_CTRL_SPI_WR_BIT_ORDER_MASK 0x6000000ul
#define SPI2_SPI_CTRL_SPI_WR_BIT_ORDER(value) ((((unsigned long)(value)) << 25) & SPI2_SPI_CTRL_SPI_WR_BIT_ORDER_MASK)

// SPI2_SPI_CLOCK: SPI clock control register (read-write, reset 0x80003043)
#define SPI2_SPI_CLOCK_ADDRESS 0x6008100cul
#define SPI2_SPI_CLOCK (*(volatile uint32_t *)0x6008100cul)
#define SPI2_SPI_CLOCK_SPI_CLKCNT_L_POS 0   // In master transfer, this field must be equal to SPI_CLKCNT_N. In slave mode, it must be 0. Can be configured in CONF state.
#define SPI2_SPI_CLOCK_SPI_CLKCNT_L_MASK 0x3fu
#define SPI2_SPI_CLOCK_SPI_CLKCNT_L(value) ((((unsigned long)(value)) << 0) & SPI2_SPI_CLOCK_SPI_CLKCNT_L_MASK)
#define SPI2_SPI_CLOCK_SPI_CLKCNT_H_POS 6   // Configures the duty cycle of SPI_CLK (high level) in master transfer. It's recommended to configure this value to floor((SPI_CLKCNT_N + 1)/2 - 1). floor() here is to round a number down, e.g., floor(2.2) = 2. In slave mode, it must be 0. Can be configured in CONF state.
#define SPI2_SPI_CLOCK_SPI_CLKCNT_H_MASK 0xfc0u
#define SPI2_SPI_CLOCK_SPI_CLKCNT_H(value) ((((unsigned long)(value)) << 6) & SPI2_SPI_CLOCK_SPI_CLKCNT_H_MASK)
#define SPI2_SPI_CLOCK_SPI_CLKCNT_N_POS 12   // Configures the divider of SPI_CLK in master transfer. SPI_CLK frequency is 12_{\textrm{apb_clk}}$/(SPI_CLKDIV_PRE + 1)/(SPI_CLKCNT_N + 1). Can be configured in CONF state.
#define SPI2_SPI_CLOCK_SPI_CLKCNT_N_MASK 0x3f000ul
#define SPI2_SPI_CLOCK_SPI_CLKCNT_N(value) ((((unsigned long)(value)) << 12) & SPI2_SPI_CLOCK_SPI_CLKCNT_N_MASK)
#define SPI2_SPI_CLOCK_SPI_CLKDIV_PRE_POS 18   // Configures the pre-divider of SPI_CLK in master transfer. Can be configured in CONF state.
#define SPI2_SPI_CLOCK_SPI_CLKDIV_PRE_MASK 0x3c0000ul
#define SPI2_SPI_CLOCK_SPI_CLKDIV_PRE(value) ((((unsigned long)(value)) << 18) & SPI2_SPI_CLOCK_SPI_CLKDIV_PRE_MASK)
#define SPI2_SPI_CLOCK_SPI_CLK_EQU_SYSCLK_POS 31   // Configures whether or not the SPI_CLK is equal to APB_CLK in master transfer. 0: SPI_CLK is divided from APB_CLK. 1: SPI_CLK is eqaul to APB_CLK. Can be configured in CONF state.
#define SPI2_SPI_CLOCK_SPI_CLK_EQU_SYSCLK_MASK 0x80000000ul

// SPI2_SPI_USER: SPI USER control register (read-write, reset 0x800000c0)
#define SPI2_SPI_USER_ADDRESS 0x60081010ul
#define SPI2_SPI_USER (*(volatile uint32_t *)0x60081010ul)
#define SPI2_SPI_USER_SPI_DOUTDIN_POS 0   // Configures whether or not to enable full-duplex communication. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_DOUTDIN_MASK 0x1u
#define SPI2_SPI_USER_SPI_QPI_MODE_POS 3   // Configures whether or not to enable QPI mode. 0: Disable; 1: Enable; This configuration is applicable when the SPI controller works as master or slave. Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_QPI_MODE_MASK 0x8u
#define SPI2_SPI_USER_SPI_OPI_MODE_POS 4   // Just for master mode. 1: spi controller is in OPI mode (all in 8-b-m). 0: others. Can be configured in CONF state. (read-only)
#define SPI2_SPI_USER_SPI_OPI_MODE_MASK 0x10u
#define SPI2_SPI_USER_SPI_TSCK_I_EDGE_POS 5   // Configures whether or not to change the polarity of TSCK in slave transfer. 0: TSCK = SPI_CK_I; 1: TSCK = !SPI_CK_I
#define SPI2_SPI_USER_SPI_TSCK_I_EDGE_MASK 0x20u
#define SPI2_SPI_USER_SPI_CS_HOLD_POS 6   // Configures whether or not to keep SPI CS low when SPI is in DONE state. 0: Not keep low; 1: Keep low; Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_CS_HOLD_MASK 0x40u
#define SPI2_SPI_USER_SPI_CS_SETUP_POS 7   // Configures whether or not to enable SPI CS when SPI is in prepare (PREP) state. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_CS_SETUP_MASK 0x80u
#define SPI2_SPI_USER_SPI_RSCK_I_EDGE_POS 8   // Configures whether or not to change the polarity of RSCK in slave transfer. 0: RSCK = !SPI_CK_I; 1: RSCK = SPI_CK_I
#define SPI2_SPI_USER_SPI_RSCK_I_EDGE_MASK 0x100u
