#define SPI2_SPI_USER_SPI_CK_OUT_EDGE_MASK 0x200u
#define SPI2_SPI_USER_SPI_FWRITE_DUAL_POS 12   // Configures whether or not to enable the 2-bit mode of read-data phase in write operations. 0: Not enable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_FWRITE_DUAL_MASK 0x1000u
#define SPI2_SPI_USER_SPI_FWRITE_QUAD_POS 13   // Configures whether or not to enable the 4-bit mode of read-data phase in write operations. 0: Not enable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_FWRITE_QUAD_MASK 0x2000u
#define SPI2_SPI_USER_SPI_FWRITE_OCT_POS 14   // In the write operations read-data phase apply 8 signals. Can be configured in CONF state. (read-only)
#define SPI2_SPI_USER_SPI_FWRITE_OCT_MASK 0x4000u
#define SPI2_SPI_USER_SPI_USR_CONF_NXT_POS 15   // Configures whether or not to enable the CONF state for the next transaction (segment) in a configurable segmented transfer. 0: this transfer will end after the current transaction (segment) is finished. Or this is not a configurable segmented transfer. 1: this configurable segmented transfer will continue its next transaction (segment). Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_USR_CONF_NXT_MASK 0x8000u
#define SPI2_SPI_USER_SPI_SIO_POS 17   // Configures whether or not to enable 3-line half-duplex communication, where MOSI and MISO signals share the same pin. 0: Disable; 1: Enable; Can be configured in CONF state.
