#define SPI2_SPI_USER_SPI_USR_MISO_HIGHPART_POS 24   // Configures whether or not to enable high part mode, i.e., only access to high part of the buffers: SPI_W8_REG ~ SPI_W15_REG in read-data phase. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_USR_MISO_HIGHPART_MASK 0x1000000ul
#define SPI2_SPI_USER_SPI_USR_MOSI_HIGHPART_POS 25   // Configures whether or not to enable high part mode, i.e., only access to high part of the buffers: SPI_W8_REG ~ SPI_W15_REG in write-data phase. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_USR_MOSI_HIGHPART_MASK 0x2000000ul
#define SPI2_SPI_USER_SPI_USR_DUMMY_IDLE_POS 26   // Configures whether or not to disable SPI clock in DUMMY state. 0: Not disable; 1: Disable; Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_USR_DUMMY_IDLE_MASK 0x4000000ul
#define SPI2_SPI_USER_SPI_USR_MOSI_POS 27   // Configures whether or not to enable the write-data (DOUT) state of an operation. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_USR_MOSI_MASK 0x8000000ul
#define SPI2_SPI_USER_SPI_USR_MISO_POS 28   // Configures whether or not to enable the read-data (DIN) state of an operation. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_USR_MISO_MASK 0x10000000ul
#define SPI2_SPI_USER_SPI_USR_DUMMY_POS 29   // Configures whether or not to enable the DUMMY state of an operation. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_USR_DUMMY_MASK 0x20000000ul
#define SPI2_SPI_USER_SPI_USR_ADDR_POS 30   // Configures whether or not to enable the address (ADDR) state of an operation. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_USR_ADDR_MASK 0x40000000ul
#define SPI2_SPI_USER_SPI_USR_COMMAND_POS 31   // Configures whether or not to enable the command (CMD) state of an operation. 0: Disable; 1: Enable; Can be configured in CONF state.
#define SPI2_SPI_USER_SPI_USR_COMMAND_MASK 0x80000000ul

// SPI2_SPI_USER1: SPI USER control register 1 (read-write, reset 0xb8410007)
#define SPI2_SPI_USER1_ADDRESS 0x60081014ul
