#define SPI2_SPI_USER1_SPI_CS_HOLD_TIME(value) ((((unsigned long)(value)) << 22) & SPI2_SPI_USER1_SPI_CS_HOLD_TIME_MASK)
#define SPI2_SPI_USER1_SPI_USR_ADDR_BITLEN_POS 27   // Configures the bit length in address state. This value is (expected bit number - 1). Can be configured in CONF state.
