#define SPI2_SPI_MISC_SPI_CS3_DIS_POS 3   // Configures whether or not to disable SPI_CS3 pin. 0: SPI_CS3 signal is from/to SPI_CS3 pin. 1: Disable SPI_CS3 pin. Can be configured in CONF state.
#define SPI2_SPI_MISC_SPI_CS3_DIS_MASK 0x8u
#define SPI2_SPI_MISC_SPI_CS4_DIS_POS 4   // Configures whether or not to disable SPI_CS4 pin. 0: SPI_CS4 signal is from/to SPI_CS4 pin. 1: Disable SPI_CS4 pin. Can be configured in CONF state.
#define SPI2_SPI_MISC_SPI_CS4_DIS_MASK 0x10u
#define SPI2_SPI_MISC_SPI_CS5_DIS_POS 5   // Configures whether or not to disable SPI_CS5 pin. 0: SPI_CS5 signal is from/to SPI_CS5 pin. 1: Disable SPI_CS5 pin. Can be configured in CONF state.
#define SPI2_SPI_MISC_SPI_CS5_DIS_MASK 0x20u
#define SPI2_SPI_MISC_SPI_CK_DIS_POS 6   // Configures whether or not to disable SPI_CLK output. 0: Enable; 1: Disable; Can be configured in CONF state.
#define SPI2_SPI_MISC_SPI_CK_DIS_MASK 0x40u
#define SPI2_SPI_MISC_SPI_MASTER_CS_POL_POS 7   // Configures the polarity of SPI_CS7 (7 = 0-5) line in master transfer. 0: SPI_CS7 is low active. 1: SPI_CS7 is high active. Can be configured in CONF state.
#define SPI2_SPI_MISC_SPI_MASTER_CS_POL_MASK 0x1f80u
