#define SPI2_SPI_MISC_SPI_CLK_DATA_DTR_EN_POS 16   // 1: SPI master DTR mode is applied to SPI clk, data and spi_dqs. 0: SPI master DTR mode is only applied to spi_dqs. This bit should be used with bit 17/18/19. (read-only)
#define SPI2_SPI_MISC_SPI_CLK_DATA_DTR_EN_MASK 0x10000ul
