#define SPI2_SPI_MISC_SPI_CMD_DTR_EN_MASK 0x80000ul
#define SPI2_SPI_MISC_SPI_SLAVE_CS_POL_POS 23   // Configures whether or not invert SPI slave input CS polarity. 0: Not change; 1: Invert; Can be configured in CONF state.
#define SPI2_SPI_MISC_SPI_SLAVE_CS_POL_MASK 0x800000ul
#define SPI2_SPI_MISC_SPI_DQS_IDLE_EDGE_POS 24   // The default value of spi_dqs. Can be configured in CONF state. (read-only)
#define SPI2_SPI_MISC_SPI_DQS_IDLE_EDGE_MASK 0x1000000ul
