#define SPI2_SPI_DIN_MODE_SPI_DIN2_MODE_MASK 0x30u
#define SPI2_SPI_DIN_MODE_SPI_DIN2_MODE(value) ((((unsigned long)(value)) << 4) & SPI2_SPI_DIN_MODE_SPI_DIN2_MODE_MASK)
#define SPI2_SPI_DIN_MODE_SPI_DIN3_MODE_POS 6   // Configures the input mode for FSPIHD signal. 0: Input without delay; 1: Input at the (SPI_DIN3_NUM + 1)th falling edge of clk_spi_mst; 2: Input at the (SPI_DIN3_NUM + 1)th rising edge of clk_hclk plus one clk_spi_mst rising edge cycle; 3: Input at the (SPI_DIN3_NUM + 1)th rising edge of clk_hclk plus one clk_spi_mst falling edge cycle; Can be configured in CONF state.
#define SPI2_SPI_DIN_MODE_SPI_DIN3_MODE_MASK 0xc0u
