#define SPI2_SPI_DIN_MODE_SPI_DIN4_MODE_MASK 0x300u
#define SPI2_SPI_DIN_MODE_SPI_DIN4_MODE(value) ((((unsigned long)(value)) << 8) & SPI2_SPI_DIN_MODE_SPI_DIN4_MODE_MASK)
#define SPI2_SPI_DIN_MODE_SPI_DIN5_MODE_POS 10   // the input signals are delayed by SPI module clock cycles, 0: input without delayed, 1: input with the posedge of clk_apb,2 input with the negedge of clk_apb, 3: input with the spi_clk. Can be configured in CONF state. (read-only)
#define SPI2_SPI_DIN_MODE_SPI_DIN5_MODE_MASK 0xc00u
#define SPI2_SPI_DIN_MODE_SPI_DIN5_MODE(value) ((((unsigned long)(value)) << 10) & SPI2_SPI_DIN_MODE_SPI_DIN5_MODE_MASK)
#define SPI2_SPI_DIN_MODE_SPI_DIN6_MODE_POS 12   // the input signals are delayed by SPI module clock cycles, 0: input without delayed, 1: input with the posedge of clk_apb,2 input with the negedge of clk_apb, 3: input with the spi_clk. Can be configured in CONF state. (read-only)
#define SPI2_SPI_DIN_MODE_SPI_DIN6_MODE_MASK 0x3000u
#define SPI2_SPI_DIN_MODE_SPI_DIN6_MODE(value) ((((unsigned long)(value)) << 12) & SPI2_SPI_DIN_MODE_SPI_DIN6_MODE_MASK)
#define SPI2_SPI_DIN_MODE_SPI_DIN7_MODE_POS 14   // the input signals are delayed by SPI module clock cycles, 0: input without delayed, 1: input with the posedge of clk_apb,2 input with the negedge of clk_apb, 3: input with the spi_clk. Can be configured in CONF state. (read-only)
#define SPI2_SPI_DIN_MODE_SPI_DIN7_MODE_MASK 0xc000u
