// SPI2_SPI_DMA_CONF: SPI DMA control register (read-write, reset 0x00000003)
#define SPI2_SPI_DMA_CONF_ADDRESS 0x60081030ul
#define SPI2_SPI_DMA_CONF (*(volatile uint32_t *)0x60081030ul)
#define SPI2_SPI_DMA_CONF_SPI_DMA_OUTFIFO_EMPTY_POS 0   // Represents whether or not the DMA TX FIFO is ready for sending data. 0: Ready; 1: Not ready (read-only)
#define SPI2_SPI_DMA_CONF_SPI_DMA_OUTFIFO_EMPTY_MASK 0x1u
#define SPI2_SPI_DMA_CONF_SPI_DMA_INFIFO_FULL_POS 1   // Represents whether or not the DMA RX FIFO is ready for receiving data. 0: Ready; 1: Not ready (read-only)
#define SPI2_SPI_DMA_CONF_SPI_DMA_INFIFO_FULL_MASK 0x2u
#define SPI2_SPI_DMA_CONF_SPI_DMA_SLV_SEG_TRANS_EN_POS 18   // Configures whether or not to enable DMA-controlled segmented transfer in slave half-duplex communication. 0: Disable; 1: Enable
#define SPI2_SPI_DMA_CONF_SPI_DMA_SLV_SEG_TRANS_EN_MASK 0x40000ul
#define SPI2_SPI_DMA_CONF_SPI_SLV_RX_SEG_TRANS_CLR_EN_POS 19   // In slave segmented transfer, if the size of the DMA RX buffer is smaller than the size of the received data,; 1: the data in all the following Wr_DMA transactions will not be received; 0: the data in this Wr_DMA transaction will not be received, but in the following transactions,; - if the size of DMA RX buffer is not 0, the data in following Wr_DMA transactions will be received. - if the size of DMA RX buffer is 0, the data in following Wr_DMA transactions will not be received.
#define SPI2_SPI_DMA_CONF_SPI_SLV_RX_SEG_TRANS_CLR_EN_MASK 0x80000ul
#define SPI2_SPI_DMA_CONF_SPI_SLV_TX_SEG_TRANS_CLR_EN_POS 20   // In slave segmented transfer, if the size of the DMA TX buffer is smaller than the size of the transmitted data,; 1: the data in the following transactions will not be updated, i.e. the old data is transmitted repeatedly. 0: the data in this transaction will not be updated. But in the following transactions,; - if new data is filled in DMA TX FIFO, new data will be transmitted. - if no new data is filled in DMA TX FIFO, no new data will be transmitted.
#define SPI2_SPI_DMA_CONF_SPI_SLV_TX_SEG_TRANS_CLR_EN_MASK 0x100000ul
#define SPI2_SPI_DMA_CONF_SPI_RX_EOF_EN_POS 21   // 1: In a DAM-controlled transfer, if the bit number of transferred data is equal to (SPI_MS_DATA_BITLEN + 1), then GDMA_IN_SUC_EOF_CH\it{n}_INT_RAW will be set by hardware. 0: GDMA_IN_SUC_EOF_CH\it{n}_INT_RAW is set by SPI_TRANS_DONE_INT event in a single transfer, or by an SPI_DMA_SEG_TRANS_DONE_INT event in a segmented transfer.
#define SPI2_SPI_DMA_CONF_SPI_RX_EOF_EN_MASK 0x200000ul
#define SPI2_SPI_DMA_CONF_SPI_DMA_RX_ENA_POS 27   // Configures whether or not to enable DMA-controlled receive data transfer. 0: Disable; 1: Enable
#define SPI2_SPI_DMA_CONF_SPI_DMA_RX_ENA_MASK 0x8000000ul
#define SPI2_SPI_DMA_CONF_SPI_DMA_TX_ENA_POS 28   // Configures whether or not to enable DMA-controlled send data transfer. 0: Disable; 1: Enable
#define SPI2_SPI_DMA_CONF_SPI_DMA_TX_ENA_MASK 0x10000000ul
#define SPI2_SPI_DMA_CONF_SPI_RX_AFIFO_RST_POS 29   // Configures whether or not to reset spi_rx_afifo as shown in Figure <a href="fig:spi-master-data-flow-control">link</a> and in Figure <a href="fig:spi-slave-data-flow-control">link</a>. 0: Not reset; 1: Reset; spi_rx_afifo is used to receive data in SPI master and slave transfer. (write-only)
#define SPI2_SPI_DMA_CONF_SPI_RX_AFIFO_RST_MASK 0x20000000ul
#define SPI2_SPI_DMA_CONF_SPI_BUF_AFIFO_RST_POS 30   // Configures whether or not to reset buf_tx_afifo as shown in Figure <a href="fig:spi-master-data-flow-control">link</a> and in Figure <a href="fig:spi-slave-data-flow-control">link</a>. 0: Not reset; 1: Reset; buf_tx_afifo is used to send data out in CPU-controlled master and slave transfer. (write-only)
#define SPI2_SPI_DMA_CONF_SPI_BUF_AFIFO_RST_MASK 0x40000000ul
#define SPI2_SPI_DMA_CONF_SPI_DMA_AFIFO_RST_POS 31   // Configures whether or not to reset dma_tx_afifo as shown in Figure <a href="fig:spi-master-data-flow-control">link</a> and in Figure <a href="fig:spi-slave-data-flow-control">link</a>. 0: Not reset; 1: Reset; dma_tx_afifo is used to send data out in DMA-controlled slave transfer. (write-only)
