#define TRACE_TRIGGER_ADDRESS 0x600c0020ul
#define TRACE_TRIGGER (*(volatile uint32_t *)0x600c0020ul)
#define TRACE_TRIGGER_ON_POS 0   // Configure whether to enable the encoder. 0: Invalid; 1: Enable (write-only)
#define TRACE_TRIGGER_ON_MASK 0x1u
#define TRACE_TRIGGER_OFF_POS 1   // Configure whether to disable the encoder. 0: Invalid; 1: Disable (write-only)
#define TRACE_TRIGGER_OFF_MASK 0x2u
#define TRACE_TRIGGER_MEM_LOOP_POS 2   // Configure the memory writing mode. 0: Non-loop mode. 1: Loop mode
#define TRACE_TRIGGER_MEM_LOOP_MASK 0x4u
#define TRACE_TRIGGER_RESTART_ENA_POS 3   // Configure whether or not enable automatic restart function for the encoder. 0: Disable; 1: Enable
#define TRACE_TRIGGER_RESTART_ENA_MASK 0x8u

// TRACE_CONFIG: trace configuration register (read-write, reset 0x00000000)
#define TRACE_CONFIG_ADDRESS 0x600c0024ul
#define TRACE_CONFIG (*(volatile uint32_t *)0x600c0024ul)
#define TRACE_CONFIG_DM_TRIGGER_ENA_POS 0   // Configure whether to enable the trigger signal. 0: Disable; 1:enable
#define TRACE_CONFIG_DM_TRIGGER_ENA_MASK 0x1u
#define TRACE_CONFIG_RESET_ENA_POS 1   // Configure whether to reset, when enabeld, if cpu have reset, the encoder will output a packet to report the address of the last instruction, and upon reset deassertion, the encoder start again. 0: Disable; 0: Enable
#define TRACE_CONFIG_RESET_ENA_MASK 0x2u
#define TRACE_CONFIG_HALT_ENA_POS 2   // Configure whether to enable the halt signal. 1: Disable; 1: Enable
#define TRACE_CONFIG_HALT_ENA_MASK 0x4u
#define TRACE_CONFIG_STALL_ENA_POS 3   // Configure whether to enable the stall signal. 0: Disable. 1: Enable
#define TRACE_CONFIG_STALL_ENA_MASK 0x8u
#define TRACE_CONFIG_FULL_ADDRESS_POS 4   // Configure the address mode. 0: Delta address mode. 1: Full address mode.
#define TRACE_CONFIG_FULL_ADDRESS_MASK 0x10u
#define TRACE_CONFIG_IMPLICIT_EXCEPT_POS 5   // Configure whether or not enabel implicit exception mode. When enabled,, do not sent exception address, only exception cause in exception packets. 1: enabled; 0: disabled
#define TRACE_CONFIG_IMPLICIT_EXCEPT_MASK 0x20u

// TRACE_FILTER_CONTROL: filter control register (read-write, reset 0x00000000)
#define TRACE_FILTER_CONTROL_ADDRESS 0x600c0028ul
#define TRACE_FILTER_CONTROL (*(volatile uint32_t *)0x600c0028ul)
#define TRACE_FILTER_CONTROL_FILTER_EN_POS 0   // Configure whether to enable filtering. 0: Disable, always match. 1: Enable
#define TRACE_FILTER_CONTROL_FILTER_EN_MASK 0x1u
#define TRACE_FILTER_CONTROL_MATCH_COMP_POS 1   // Configure whether to enable the comparator match mode. 0: Disable; 1: Enable, the comparator must be high in order for the filter to match
#define TRACE_FILTER_CONTROL_MATCH_COMP_MASK 0x2u
#define TRACE_FILTER_CONTROL_MATCH_PRIVILEGE_POS 2   // Configure whether to enable the privilege match mode. 0: Disable; 1: Enable, match privilege levels specified by \hyperref[fielddesc:TRACEMATCHCHOICEPRIVILEGE]{TRACE_MATCH_CHOICE_PRIVILEGE}.
#define TRACE_FILTER_CONTROL_MATCH_PRIVILEGE_MASK 0x4u
#define TRACE_FILTER_CONTROL_MATCH_ECAUSE_POS 3   // Configure whether to enable ecause match mode. 0: Disable; 1: Enable, start matching from exception cause codes specified by \hyperref[fielddesc:TRACEMATCHCHOICEECAUSE]{TRACE_MATCH_CHOICE_ECAUSE}, and stop matching upon return from the 1st matching exception.
#define TRACE_FILTER_CONTROL_MATCH_ECAUSE_MASK 0x8u
#define TRACE_FILTER_CONTROL_MATCH_INTERRUPT_POS 4   // Configure whether to enable the interrupt match mode. 0: Disable; 1: Enable, start matching from a trap with the interrupt level codes specified by \hyperref[fielddesc:TRACEMATCHVALUEINTERRUPT]{TRACE_MATCH_VALUE_INTERRUPT}, and stop matching upon return from the 1st matching trap.
#define TRACE_FILTER_CONTROL_MATCH_INTERRUPT_MASK 0x10u

// TRACE_FILTER_MATCH_CONTROL: filter match control register (read-write, reset 0x00000000)
#define TRACE_FILTER_MATCH_CONTROL_ADDRESS 0x600c002cul
#define TRACE_FILTER_MATCH_CONTROL (*(volatile uint32_t *)0x600c002cul)
#define TRACE_FILTER_MATCH_CONTROL_MATCH_CHOICE_PRIVILEGE_POS 0   // Configures the privilege level for matching. Valid only when \hyperref[fielddesc:TRACEMATCHPRIVILEGE]{TRACE_MATCH_PRIVILEGE} is set. 0: User mode. 1: Machine mode
#define TRACE_FILTER_MATCH_CONTROL_MATCH_CHOICE_PRIVILEGE_MASK 0x1u
#define TRACE_FILTER_MATCH_CONTROL_MATCH_VALUE_INTERRUPT_POS 1   // Configures the interrupt level for match. Valid only when when \hyperref[fielddesc:TRACEMATCHINTERRUPT]{TRACE_MATCH_INTERRUP} is set. 0: itype=2. 0: itype=2.
#define TRACE_FILTER_MATCH_CONTROL_MATCH_VALUE_INTERRUPT_MASK 0x2u
#define TRACE_FILTER_MATCH_CONTROL_MATCH_CHOICE_ECAUSE_POS 2   // Configures the ecause code for matching.
#define TRACE_FILTER_MATCH_CONTROL_MATCH_CHOICE_ECAUSE_MASK 0xfcu
#define TRACE_FILTER_MATCH_CONTROL_MATCH_CHOICE_ECAUSE(value) ((((unsigned long)(value)) << 2) & TRACE_FILTER_MATCH_CONTROL_MATCH_CHOICE_ECAUSE_MASK)

// TRACE_FILTER_COMPARATOR_CONTROL: filter comparator match control register (read-write, reset 0x00000000)
#define TRACE_FILTER_COMPARATOR_CONTROL_ADDRESS 0x600c0030ul
#define TRACE_FILTER_COMPARATOR_CONTROL (*(volatile uint32_t *)0x600c0030ul)
#define TRACE_FILTER_COMPARATOR_CONTROL_P_INPUT_POS 0   // Configures the input of the primary comparator for matching: 0: iaddr; 1: tval
#define TRACE_FILTER_COMPARATOR_CONTROL_P_INPUT_MASK 0x1u
#define TRACE_FILTER_COMPARATOR_CONTROL_P_FUNCTION_POS 2   // Configures the function for the primary comparator. 0: Equal,; 1: Not equal,; 2: Less than,; 3: Less than or equal,; 4: Greater than,; 5: Greater than or equal,; Other: Always match
#define TRACE_FILTER_COMPARATOR_CONTROL_P_FUNCTION_MASK 0x1cu
#define TRACE_FILTER_COMPARATOR_CONTROL_P_FUNCTION(value) ((((unsigned long)(value)) << 2) & TRACE_FILTER_COMPARATOR_CONTROL_P_FUNCTION_MASK)
#define TRACE_FILTER_COMPARATOR_CONTROL_P_NOTIFY_POS 5   // Configure whether to explicitly report an instruction address matched against the primary comparator. 0:Not report; 1:Report
#define TRACE_FILTER_COMPARATOR_CONTROL_P_NOTIFY_MASK 0x20u
#define TRACE_FILTER_COMPARATOR_CONTROL_S_INPUT_POS 8   // Configures the input of the secondary comparator for matching: 0: iaddr; 1: tval
#define TRACE_FILTER_COMPARATOR_CONTROL_S_INPUT_MASK 0x100u
#define TRACE_FILTER_COMPARATOR_CONTROL_S_FUNCTION_POS 10   // Configures the function for the secondary comparator. 0: Equal,; 1: Not equal,; 2: Less than,; 3: Less than or equal,; 4: Greater than,; 5: Greater than or equal,; Other: Always match
#define TRACE_FILTER_COMPARATOR_CONTROL_S_FUNCTION_MASK 0x1c00u
#define TRACE_FILTER_COMPARATOR_CONTROL_S_FUNCTION(value) ((((unsigned long)(value)) << 10) & TRACE_FILTER_COMPARATOR_CONTROL_S_FUNCTION_MASK)
#define TRACE_FILTER_COMPARATOR_CONTROL_S_NOTIFY_POS 13   // Generate a trace packet explicitly reporting the address that cause the secondary match
#define TRACE_FILTER_COMPARATOR_CONTROL_S_NOTIFY_MASK 0x2000u
#define TRACE_FILTER_COMPARATOR_CONTROL_MATCH_MODE_POS 16   // Configures the comparator match mode: 0: Only the primary comparator matches; 1: Both primary and secondary comparator matches(P\&\&S); 2:Neither primary or secondary comparator matches !(P\&\&S); 3: Start filtering when the primary comparator matches and stop filtering when the secondary comparator matches
#define TRACE_FILTER_COMPARATOR_CONTROL_MATCH_MODE_MASK 0x30000ul
#define TRACE_FILTER_COMPARATOR_CONTROL_MATCH_MODE(value) ((((unsigned long)(value)) << 16) & TRACE_FILTER_COMPARATOR_CONTROL_MATCH_MODE_MASK)

// TRACE_FILTER_P_COMPARATOR_MATCH: primary comparator match value (read-write, reset 0x00000000)
#define TRACE_FILTER_P_COMPARATOR_MATCH_ADDRESS 0x600c0034ul
#define TRACE_FILTER_P_COMPARATOR_MATCH (*(volatile uint32_t *)0x600c0034ul)
#define TRACE_FILTER_P_COMPARATOR_MATCH_P_MATCH_POS 0   // Configures the match value for the primary comparator
#define TRACE_FILTER_P_COMPARATOR_MATCH_P_MATCH_MASK 0xfffffffful
#define TRACE_FILTER_P_COMPARATOR_MATCH_P_MATCH(value) ((((unsigned long)(value)) << 0) & TRACE_FILTER_P_COMPARATOR_MATCH_P_MATCH_MASK)

// TRACE_FILTER_S_COMPARATOR_MATCH: secondary comparator match value (read-write, reset 0x00000000)
#define TRACE_FILTER_S_COMPARATOR_MATCH_ADDRESS 0x600c0038ul
#define TRACE_FILTER_S_COMPARATOR_MATCH (*(volatile uint32_t *)0x600c0038ul)
#define TRACE_FILTER_S_COMPARATOR_MATCH_S_MATCH_POS 0   // Configures the match value for the secondary comparator
#define TRACE_FILTER_S_COMPARATOR_MATCH_S_MATCH_MASK 0xfffffffful
#define TRACE_FILTER_S_COMPARATOR_MATCH_S_MATCH(value) ((((unsigned long)(value)) << 0) & TRACE_FILTER_S_COMPARATOR_MATCH_S_MATCH_MASK)

// TRACE_RESYNC_PROLONGED: Resync configuration register (read-write, reset 0x00000080)
#define TRACE_RESYNC_PROLONGED_ADDRESS 0x600c003cul
#define TRACE_RESYNC_PROLONGED (*(volatile uint32_t *)0x600c003cul)
#define TRACE_RESYNC_PROLONGED_RESYNC_PROLONGED_POS 0   // Configures the threshold for synchronization counter
#define TRACE_RESYNC_PROLONGED_RESYNC_PROLONGED_MASK 0xfffffful
#define TRACE_RESYNC_PROLONGED_RESYNC_PROLONGED(value) ((((unsigned long)(value)) << 0) & TRACE_RESYNC_PROLONGED_RESYNC_PROLONGED_MASK)
#define TRACE_RESYNC_PROLONGED_RESYNC_MODE_POS 24   // Configures the synchronization mode: 0: Disable the synchronization counter; 1: Invalid; 2: Synchronization counter counts by packet; 3: Synchronization counter counts by cycle
#define TRACE_RESYNC_PROLONGED_RESYNC_MODE_MASK 0x3000000ul
#define TRACE_RESYNC_PROLONGED_RESYNC_MODE(value) ((((unsigned long)(value)) << 24) & TRACE_RESYNC_PROLONGED_RESYNC_MODE_MASK)

// TRACE_AHB_CONFIG: AHB config register (read-write, reset 0x00000000)
#define TRACE_AHB_CONFIG_ADDRESS 0x600c0040ul
#define TRACE_AHB_CONFIG (*(volatile uint32_t *)0x600c0040ul)
#define TRACE_AHB_CONFIG_HBURST_POS 0   // Configures the AHB burst mode. 0: SIGNLE; 1: INCR(length not defined); 2:INCR4; 4:INCR8; Others:Invalid
#define TRACE_AHB_CONFIG_HBURST_MASK 0x7u
#define TRACE_AHB_CONFIG_HBURST(value) ((((unsigned long)(value)) << 0) & TRACE_AHB_CONFIG_HBURST_MASK)
#define TRACE_AHB_CONFIG_MAX_INCR_POS 3   // Configures the maximum burst length for INCR mode
#define TRACE_AHB_CONFIG_MAX_INCR_MASK 0x38u
#define TRACE_AHB_CONFIG_MAX_INCR(value) ((((unsigned long)(value)) << 3) & TRACE_AHB_CONFIG_MAX_INCR_MASK)

// TRACE_CLOCK_GATE: Clock gate control register (read-write, reset 0x00000001)
#define TRACE_CLOCK_GATE_ADDRESS 0x600c0044ul
#define TRACE_CLOCK_GATE (*(volatile uint32_t *)0x600c0044ul)
#define TRACE_CLOCK_GATE_CLK_EN_POS 0   // Configures register clock gating. 0: Support clock only when the application writes registers to save power. 1:Always force the clock on for registers; This bit does't affect register access.
#define TRACE_CLOCK_GATE_CLK_EN_MASK 0x1u

// TRACE_DATE: Version control register (read-write, reset 0x02211300)
#define TRACE_DATE_ADDRESS 0x600c03fcul
#define TRACE_DATE (*(volatile uint32_t *)0x600c03fcul)
#define TRACE_DATE_DATE_POS 0   // Version control register.
#define TRACE_DATE_DATE_MASK 0xffffffful
#define TRACE_DATE_DATE(value) ((((unsigned long)(value)) << 0) & TRACE_DATE_DATE_MASK)

// ---- TWAI0: Two-Wire Automotive Interface

// TWAI0_DEVICE_ID_VERSION: TWAI FD device id status register (read-write, reset 0x0204cafd)
#define TWAI0_DEVICE_ID_VERSION_ADDRESS 0x6000b000ul
#define TWAI0_DEVICE_ID_VERSION (*(volatile uint32_t *)0x6000b000ul)
#define TWAI0_DEVICE_ID_VERSION_DEVICE_ID_POS 0   // Represents whether CAN IP function is mapped correctly on its base address. (read-only)
#define TWAI0_DEVICE_ID_VERSION_DEVICE_ID_MASK 0xffffu
#define TWAI0_DEVICE_ID_VERSION_DEVICE_ID(value) ((((unsigned long)(value)) << 0) & TWAI0_DEVICE_ID_VERSION_DEVICE_ID_MASK)
#define TWAI0_DEVICE_ID_VERSION_VER_MINOR_POS 16   // TWAI FD IP version (read-only)
#define TWAI0_DEVICE_ID_VERSION_VER_MINOR_MASK 0xff0000ul
#define TWAI0_DEVICE_ID_VERSION_VER_MINOR(value) ((((unsigned long)(value)) << 16) & TWAI0_DEVICE_ID_VERSION_VER_MINOR_MASK)
#define TWAI0_DEVICE_ID_VERSION_VER_MAJOR_POS 24   // TWAI FD IP version (read-only)
#define TWAI0_DEVICE_ID_VERSION_VER_MAJOR_MASK 0xff000000ul
#define TWAI0_DEVICE_ID_VERSION_VER_MAJOR(value) ((((unsigned long)(value)) << 24) & TWAI0_DEVICE_ID_VERSION_VER_MAJOR_MASK)

// TWAI0_MODE_SETTINGS: TWAI FD mode setting register (read-write, reset 0x02000210)
#define TWAI0_MODE_SETTINGS_ADDRESS 0x6000b004ul
#define TWAI0_MODE_SETTINGS (*(volatile uint32_t *)0x6000b004ul)
#define TWAI0_MODE_SETTINGS_RST_POS 0   // Soft reset. Writing logic 1 resets CTU CAN FD. After writing logic 1, logic 0 does not need to be written, this bit is automatically cleared. 0: invalid 1: reset. (write-only)
#define TWAI0_MODE_SETTINGS_RST_MASK 0x1u
#define TWAI0_MODE_SETTINGS_BMM_POS 1   // Bus monitoring mode. In this mode CTU CAN FD only receives frames and sends only recessive bits on CAN bus. When a dominant bit is sent, it is re-routed internally so that bus value is not changed. When this mode is enabled, CTU CAN FD will not transmit any frame from TXT Buffers, 0b0 - BMM_DISABLED - Bus monitoring mode disabled. 0b1 - BMM_ENABLED - Bus monitoring mode enabled.
#define TWAI0_MODE_SETTINGS_BMM_MASK 0x2u
#define TWAI0_MODE_SETTINGS_STM_POS 2   // Self Test Mode. In this mode transmitted frame is considered valid even if dominant acknowledge was not received. 0b0 - STM_DISABLED - Self test mode disabled. 0b1 - STM_ENABLED - Self test mode enabled.
#define TWAI0_MODE_SETTINGS_STM_MASK 0x4u
#define TWAI0_MODE_SETTINGS_AFM_POS 3   // Acceptance Filters Mode. If enabled, only RX frames which pass Frame filters are stored in RX buffer. If disabled, every received frame is stored to RX buffer. This bit has meaning only if there is at least one filter available. Otherwise, this bit is reserved. 0b0 - AFM_DISABLED - Acceptance filter mode disabled 0b1 - AFM_ENABLED - Acceptance filter mode enabled
#define TWAI0_MODE_SETTINGS_AFM_MASK 0x8u
#define TWAI0_MODE_SETTINGS_FDE_POS 4   // Flexible data rate enable. When flexible data rate is enabled CTU CAN FD recognizes CAN FD frames (FDF bit = 1). 0b0 - FDE_DISABLE - Flexible data-rate support disabled. 0b1 - FDE_ENABLE - Flexible data-rate support enabled.
#define TWAI0_MODE_SETTINGS_FDE_MASK 0x10u
#define TWAI0_MODE_SETTINGS_TTTM_POS 5   // Time triggered transmission mode. 0b0 - TTTM_DISABLED - 0b1 - TTTM_ENABLED -
#define TWAI0_MODE_SETTINGS_TTTM_MASK 0x20u
#define TWAI0_MODE_SETTINGS_ROM_POS 6   // Restricted operation mode. 0b0 - ROM_DISABLED - Restricted operation mode is disabled. 0b1 - ROM_ENABLED - Restricted operation mode is enabled.
#define TWAI0_MODE_SETTINGS_ROM_MASK 0x40u
#define TWAI0_MODE_SETTINGS_ACF_POS 7   // Acknowledge Forbidden Mode. When enabled, acknowledge is not sent even if received CRC matches the calculated one. 0b0 - ACF_DISABLED - Acknowledge forbidden mode disabled. 0b1 - ACF_ENABLED - Acknowledge forbidden mode enabled.
#define TWAI0_MODE_SETTINGS_ACF_MASK 0x80u
#define TWAI0_MODE_SETTINGS_TSTM_POS 8   // Test Mode. In test mode several registers have special features. Reffer to description of Test mode for further Details.
#define TWAI0_MODE_SETTINGS_TSTM_MASK 0x100u
#define TWAI0_MODE_SETTINGS_RXBAM_POS 9   // RX Buffer automatic mode. 0b0 - RXBAM_DISABLED - 0b1 - RXBAM_ENABLED -
#define TWAI0_MODE_SETTINGS_RXBAM_MASK 0x200u
#define TWAI0_MODE_SETTINGS_TXBBM_POS 10   // TXT Buffer Backup mode; 0b0 - TXBBM_DISABLED - TXT Buffer Backup mode disabled; 0b1 - TXBBM_ENABLED - TXT Buffer Backup mode enabled
#define TWAI0_MODE_SETTINGS_TXBBM_MASK 0x400u
#define TWAI0_MODE_SETTINGS_SAM_POS 11   // Self-acknowledge mode. 0b0 - SAM_DISABLE - Do not send dominant ACK bit when CTU CAN FD sends Acknowledge bit. 0b1 - SAM_ENABLE - Send dominant ACK bit when CTU CAN FD transmits CAN frame.
#define TWAI0_MODE_SETTINGS_SAM_MASK 0x800u
#define TWAI0_MODE_SETTINGS_RTRLE_POS 16   // Retransmitt Limit Enable. If enabled, CTU CAN FD only attempts to retransmitt each frame up to RTR_TH times. 0b0 - RTRLE_DISABLED - Retransmitt limit is disabled. 0b1 - RTRLE_ENABLED - Retransmitt limit is enabled.
#define TWAI0_MODE_SETTINGS_RTRLE_MASK 0x10000ul
#define TWAI0_MODE_SETTINGS_RTRTH_POS 17   // Retransmitt Limit Threshold. Maximal amount of retransmission attempts when SETTINGS[RTRLE] is en- Abled.
#define TWAI0_MODE_SETTINGS_RTRTH_MASK 0x1e0000ul
#define TWAI0_MODE_SETTINGS_RTRTH(value) ((((unsigned long)(value)) << 17) & TWAI0_MODE_SETTINGS_RTRTH_MASK)
#define TWAI0_MODE_SETTINGS_ILBP_POS 21   // Internal Loop Back mode. When enabled, CTU CAN FD receives any frame it transmitts. 0b0 - INT_LOOP_DISABLED - Internal loop-back is disabled. 0b1 - INT_LOOP_ENABLED - Internal loop-back is enabled.
#define TWAI0_MODE_SETTINGS_ILBP_MASK 0x200000ul
#define TWAI0_MODE_SETTINGS_ENA_POS 22   // Main enable bit of CTU CAN FD. When enabled, CTU CAN FD communicates on CAN bus. When disabled, it is bus-off and does not take part of CAN bus communication. 0b0 - CTU_CAN_DISABLED - The CAN Core is disabled. 0b1 - CTU_CAN_ENABLED - The CAN Core is enabled.
#define TWAI0_MODE_SETTINGS_ENA_MASK 0x400000ul
#define TWAI0_MODE_SETTINGS_NISOFD_POS 23   // Non ISO FD. When this bit is set, CTU CAN FD is compliant to NON-ISO CAN FD specification (no stuff count field). This bit should be modified only when SETTINGS[ENA]=0. 0b0 - ISO_FD - The CAN Controller conforms to ISO CAN FD specification. 0b1 - NON_ISO_FD - The CAN Controller conforms to NON ISO CAN FD specification. CANFD 1.0
#define TWAI0_MODE_SETTINGS_NISOFD_MASK 0x800000ul
#define TWAI0_MODE_SETTINGS_PEX_POS 24   // Protocol exception handling. When this bit is set, CTU CAN FD will start integration upon detection of protocol exception. This should be modified only when SETTINGS[ENA] = ’0’. 0b0 - PROTOCOL_EXCEPTION_DISABLED - Protocol exception handling is disabled. 0b1 - PROTOCOL_EXCEPTION_ENABLED - Protocol exception handling is enabled.
#define TWAI0_MODE_SETTINGS_PEX_MASK 0x1000000ul
#define TWAI0_MODE_SETTINGS_TBFBO_POS 25   // All TXT buffers shall go to "TX failed" state when CTU CAN FD becomes bus-off. 0b0 - TXTBUF_FAILED_BUS_OFF_DISABLED - TXT Buffers dont go to "TX failed" state when CTU CAN FD becomes bus-off. 0b1 - TXTBUF_FAILED_BUS_OFF_ENABLED - TXT Buffers go to "TX failed" state when CTU CAN FD becomes bus-off.
#define TWAI0_MODE_SETTINGS_TBFBO_MASK 0x2000000ul
#define TWAI0_MODE_SETTINGS_FDRF_POS 26   // Frame filters drop Remote frames. 0b0 - DROP_RF_DISABLED - Frame filters accept RTR frames. 0b1 - DROP_RF_ENABLED - Frame filters drop RTR frames.
#define TWAI0_MODE_SETTINGS_FDRF_MASK 0x4000000ul
#define TWAI0_MODE_SETTINGS_PCHKE_POS 27   // Enable Parity checks in TXT Buffers and RX Buffer.
#define TWAI0_MODE_SETTINGS_PCHKE_MASK 0x8000000ul

// TWAI0_STATUS: TWAI FD status register (read-write, reset 0x00070084)
#define TWAI0_STATUS_ADDRESS 0x6000b008ul
#define TWAI0_STATUS (*(volatile uint32_t *)0x6000b008ul)
#define TWAI0_STATUS_RXNE_POS 0   // RX buffer not empty. This bit is 1 when least one frame is stored in RX buffer. 0: empty 1: not empty (read-only)
#define TWAI0_STATUS_RXNE_MASK 0x1u
#define TWAI0_STATUS_DOR_POS 1   // Data Overrun flag. This bit is set when frame was dropped due to lack of space in RX buffer. This bit can be cleared by COMMAND[RRB]. 0: not overrun 1: overrun (read-only)
#define TWAI0_STATUS_DOR_MASK 0x2u
#define TWAI0_STATUS_TXNF_POS 2   // TXT buffers status. This bit is set if at least one TXT buffer is in "Empty" state. 0: not full 1: full (read-only)
#define TWAI0_STATUS_TXNF_MASK 0x4u
#define TWAI0_STATUS_EFT_POS 3   // Error frame is being transmitted at the moment. 0: not being transmitted 1: being transmitted (read-only)
#define TWAI0_STATUS_EFT_MASK 0x8u
#define TWAI0_STATUS_RXS_POS 4   // CTU CAN FD is receiver of CAN Frame. 0: not receiving 1: receiving (read-only)
#define TWAI0_STATUS_RXS_MASK 0x10u
#define TWAI0_STATUS_TXS_POS 5   // CTU CAN FD is transmitter of CAN Frame. 0: not transmitting 1: transmitting (read-only)
#define TWAI0_STATUS_TXS_MASK 0x20u
#define TWAI0_STATUS_EWL_POS 6   // TX Error counter (TEC) or RX Error counter (REC) is equal to, or higher than Error warning limit (EWL). 0: not reached 1: reached (read-only)
#define TWAI0_STATUS_EWL_MASK 0x40u
#define TWAI0_STATUS_IDLE_POS 7   // Bus is idle (no frame is being transmitted/received) or CTU CAN FD is bus-off. 0: active 1: not active (read-only)
#define TWAI0_STATUS_IDLE_MASK 0x80u
#define TWAI0_STATUS_PEXS_POS 8   // Protocol exception status (flag). Set when Protocol exception occurs. Cleared by writing COMMAND[CPEXS]=1. (read-only)
#define TWAI0_STATUS_PEXS_MASK 0x100u
#define TWAI0_STATUS_RXPE_POS 9   // Set when parity error is detected during read of CAN frame from RX Buffer via RX_DATA register. (read-only)
#define TWAI0_STATUS_RXPE_MASK 0x200u
#define TWAI0_STATUS_TXPE_POS 10   // TXT Buffers Parity Error flag. Set When Parity Error is detected in a TXT Buffer during transmission from this Buffer. (read-only)
#define TWAI0_STATUS_TXPE_MASK 0x400u
#define TWAI0_STATUS_TXDPE_POS 11   // TXT Buffer double parity error. Set in TXT Buffer Backup mode when parity error is detected in "backup" TXT Buffer. (read-only)
#define TWAI0_STATUS_TXDPE_MASK 0x800u
#define TWAI0_STATUS_STCNT_POS 16   // Support of Traffic counters. When this bit is 1, Traffic counters are present. (read-only)
#define TWAI0_STATUS_STCNT_MASK 0x10000ul
#define TWAI0_STATUS_STRGS_POS 17   // Support of Test Registers for memory testability. When this bit is 1, Test Registers are present. (read-only)
#define TWAI0_STATUS_STRGS_MASK 0x20000ul
#define TWAI0_STATUS_SPRT_POS 18   // Support of Parity protection on each word of TXT Buffer RAM and RX Buffer RAM. (read-only)
#define TWAI0_STATUS_SPRT_MASK 0x40000ul

// TWAI0_COMMAND: TWAI FD command register (read-write, reset 0x00000000)
#define TWAI0_COMMAND_ADDRESS 0x6000b00cul
#define TWAI0_COMMAND (*(volatile uint32_t *)0x6000b00cul)
#define TWAI0_COMMAND_RXRPMV_POS 1   // RX Buffer read pointer move. (write-only)
#define TWAI0_COMMAND_RXRPMV_MASK 0x2u
#define TWAI0_COMMAND_RRB_POS 2   // Release RX Buffer. This command flushes RX buffer and resets its memory pointers. 0: invalid 1: delete (write-only)
#define TWAI0_COMMAND_RRB_MASK 0x4u
#define TWAI0_COMMAND_CDO_POS 3   // Clear Data Overrun flag in RX buffer. 0: invalid 1: clear (write-only)
#define TWAI0_COMMAND_CDO_MASK 0x8u
#define TWAI0_COMMAND_ERCRST_POS 4   // Error Counters Reset. When unit is bus off, issuing this command will request erasing TEC, REC counters after 128 consecutive ocurrences of 11 recessive bits. Upon completion, TEC and REC are erased and fault confinement State is set to error-active. When unit is not bus-off, or when unit is bus-off due to being disabled (SETTINGS[ENA] = ’0’), this command has no effect. (write-only)
#define TWAI0_COMMAND_ERCRST_MASK 0x10u
#define TWAI0_COMMAND_RXFCRST_POS 5   // Clear RX bus traffic counter (RX_COUNTER register). (write-only)
#define TWAI0_COMMAND_RXFCRST_MASK 0x20u
#define TWAI0_COMMAND_TXFCRST_POS 6   // Clear TX bus traffic counter (TX_COUNTER register). (write-only)
#define TWAI0_COMMAND_TXFCRST_MASK 0x40u
#define TWAI0_COMMAND_CPEXS_POS 7   // Clear Protocol exception status (STATUS[PEXS]). (write-only)
#define TWAI0_COMMAND_CPEXS_MASK 0x80u
