#define TWAI0_INT_STAT_FCSI_INT_ST_MASK 0x10u
#define TWAI0_INT_STAT_ALI_INT_ST_POS 5   // The masked interrupt status of TWAIFD_ALI_INT. Arbitration lost interrupt.
#define TWAI0_INT_STAT_ALI_INT_ST_MASK 0x20u
#define TWAI0_INT_STAT_BEI_INT_ST_POS 6   // The masked interrupt status of TWAIFD_BEI_INT. Bus error interrupt.
#define TWAI0_INT_STAT_BEI_INT_ST_MASK 0x40u
#define TWAI0_INT_STAT_OFI_INT_ST_POS 7   // The masked interrupt status of TWAIFD_OFI_INT. Overload frame interrupt.
#define TWAI0_INT_STAT_OFI_INT_ST_MASK 0x80u
#define TWAI0_INT_STAT_RXFI_INT_ST_POS 8   // The masked interrupt status of TWAIFD_RXFI_INT. RX buffer full interrupt.
#define TWAI0_INT_STAT_RXFI_INT_ST_MASK 0x100u
#define TWAI0_INT_STAT_BSI_INT_ST_POS 9   // The masked interrupt status of TWAIFD_BSI_INT. Bit rate shifted interrupt.
#define TWAI0_INT_STAT_BSI_INT_ST_MASK 0x200u
#define TWAI0_INT_STAT_RBNEI_INT_ST_POS 10   // The masked interrupt status of TWAIFD_RBNEI_INT. RX buffer not empty interrupt. Clearing this interrupt and not reading out content of RX Buffer via RX_DATA will re-activate the interrupt.
#define TWAI0_INT_STAT_RBNEI_INT_ST_MASK 0x400u
#define TWAI0_INT_STAT_TXBHCI_INT_ST_POS 11   // The masked interrupt status of TWAIFD_TXBHCI_INT. TXT buffer HW command interrupt. Anytime TXT buffer receives HW command from CAN Core which changes TXT buffer state to "TX OK", "Error" or "Aborted", this interrupt will be generated.
#define TWAI0_INT_STAT_TXBHCI_INT_ST_MASK 0x800u

