#define TWAI0_TX_PRIORITY_TXT7P(value) ((((unsigned long)(value)) << 24) & TWAI0_TX_PRIORITY_TXT7P_MASK)
#define TWAI0_TX_PRIORITY_TXT8P_POS 28   // Priority of TXT buffer 8. If number of TXT Buffers is less than 8, this field is reserved and has no function.
#define TWAI0_TX_PRIORITY_TXT8P_MASK 0x70000000ul
#define TWAI0_TX_PRIORITY_TXT8P(value) ((((unsigned long)(value)) << 28) & TWAI0_TX_PRIORITY_TXT8P_MASK)

// TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO: TWAI FD error capture & retransmit counter & arbitration lost & timestamp integration information register (read-write, reset 0x0000001f)
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ADDRESS 0x6000b07cul
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO (*(volatile uint32_t *)0x6000b07cul)
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ERR_POS_POS 0   // 0b00000 - ERC_POS_SOF - Error in Start of Frame 0b00001 - ERC_POS_ARB - Error in Arbitration Filed 0b00010 - ERC_POS_CTRL - Error in Control field 0b00011 - ERC_POS_DATA - Error in Data Field 0b00100 - ERC_POS_CRC - Error in CRC Field 0b00101 - ERC_POS_ACK - Error in CRC delimiter, ACK field or ACK delimiter 0b00110 - ERC_POS_EOF - Error in End of frame field 0b00111 - ERC_POS_ERR - Error during Error frame 0b01000 - ERC_POS_OVRL - Error in Overload frame 0b11111 - ERC_POS_OTHER - Other position of error (read-only)
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ERR_POS_MASK 0x1fu
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ERR_POS(value) ((((unsigned long)(value)) << 0) & TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ERR_POS_MASK)
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ERR_TYPE_POS 5   // Type of last error. 0b000 - ERC_BIT_ERR - Bit Error 0b001 - ERC_CRC_ERR - CRC Error 0b010 - ERC_FRM_ERR - Form Error 0b011 - ERC_ACK_ERR - Acknowledge Error 0b100 - ERC_STUF_ERR - Stuff Error (read-only)
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ERR_TYPE_MASK 0xe0u
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ERR_TYPE(value) ((((unsigned long)(value)) << 5) & TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ERR_TYPE_MASK)
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_RETR_CTR_VAL_POS 8   // Current value of retransmitt counter. (read-only)
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_RETR_CTR_VAL_MASK 0xf00u
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_RETR_CTR_VAL(value) ((((unsigned long)(value)) << 8) & TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_RETR_CTR_VAL_MASK)
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ALC_BIT_POS 16   // Arbitration lost capture bit position. If ALC_ID_FIELD = ALC_BASE_ID then bit index of BASE identifier in which arbitration was lost is given as: 11 - ALC_VAL. If ALC_ID_FIELD = ALC_EXTENSION then bit index of EXTENDED identifier in which arbitration was lost is given as: 18 - ALC_VAL. For other values of ALC_ID_FIELD, this value is undefined. (read-only)
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ALC_BIT_MASK 0x1f0000ul
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ALC_BIT(value) ((((unsigned long)(value)) << 16) & TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ALC_BIT_MASK)
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ALC_ID_FIELD_POS 21   // Part of CAN Identifier in which arbitration was lost. 0b000 - ALC_RSVD - Unit did not loose arbitration since last reset. 0b001 - ALC_BASE_ID - Arbitration was lost during base identifier. 0b010 - ALC_SRR_RTR - Arbitration was lost during first bit after base identifier (SRR of Extended Frame, RTR bit of CAN 2.0 Base Frame) 0b011 - ALC_IDE - Arbitration was lost during IDE bit. 0b100 - ALC_EXTENSION - Arbitration was lost during Identifier extension. 0b101 - ALC_RTR - Arbitration was lost during RTR bit after Identifier extension! (read-only)
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ALC_ID_FIELD_MASK 0xe00000ul
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ALC_ID_FIELD(value) ((((unsigned long)(value)) << 21) & TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_ALC_ID_FIELD_MASK)
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_TS_BITS_POS 24   // Number of active bits of CTU CAN FD time-base minus 1 (0x3F = 64 bit time-base). (read-only)
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_TS_BITS_MASK 0x3f000000ul
#define TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_TS_BITS(value) ((((unsigned long)(value)) << 24) & TWAI0_ERR_CAPT_RETR_CTR_ALC_TS_INFO_TS_BITS_MASK)

// TWAI0_TRV_DELAY_SSP_CFG: TWAI FD transmit delay & secondary sample point configuration register (read-write, reset 0x000a0000)
#define TWAI0_TRV_DELAY_SSP_CFG_ADDRESS 0x6000b080ul
