// TWAI1_MODE_SETTINGS: TWAI FD mode setting register (read-write, reset 0x02000210)
#define TWAI1_MODE_SETTINGS_ADDRESS 0x6000d004ul
#define TWAI1_MODE_SETTINGS (*(volatile uint32_t *)0x6000d004ul)
#define TWAI1_MODE_SETTINGS_RST_POS 0   // Soft reset. Writing logic 1 resets CTU CAN FD. After writing logic 1, logic 0 does not need to be written, this bit is automatically cleared. 0: invalid 1: reset. (write-only)
#define TWAI1_MODE_SETTINGS_RST_MASK 0x1u
#define TWAI1_MODE_SETTINGS_BMM_POS 1   // Bus monitoring mode. In this mode CTU CAN FD only receives frames and sends only recessive bits on CAN bus. When a dominant bit is sent, it is re-routed internally so that bus value is not changed. When this mode is enabled, CTU CAN FD will not transmit any frame from TXT Buffers, 0b0 - BMM_DISABLED - Bus monitoring mode disabled. 0b1 - BMM_ENABLED - Bus monitoring mode enabled.
#define TWAI1_MODE_SETTINGS_BMM_MASK 0x2u
#define TWAI1_MODE_SETTINGS_STM_POS 2   // Self Test Mode. In this mode transmitted frame is considered valid even if dominant acknowledge was not received. 0b0 - STM_DISABLED - Self test mode disabled. 0b1 - STM_ENABLED - Self test mode enabled.
#define TWAI1_MODE_SETTINGS_STM_MASK 0x4u
#define TWAI1_MODE_SETTINGS_AFM_POS 3   // Acceptance Filters Mode. If enabled, only RX frames which pass Frame filters are stored in RX buffer. If disabled, every received frame is stored to RX buffer. This bit has meaning only if there is at least one filter available. Otherwise, this bit is reserved. 0b0 - AFM_DISABLED - Acceptance filter mode disabled 0b1 - AFM_ENABLED - Acceptance filter mode enabled
#define TWAI1_MODE_SETTINGS_AFM_MASK 0x8u
#define TWAI1_MODE_SETTINGS_FDE_POS 4   // Flexible data rate enable. When flexible data rate is enabled CTU CAN FD recognizes CAN FD frames (FDF bit = 1). 0b0 - FDE_DISABLE - Flexible data-rate support disabled. 0b1 - FDE_ENABLE - Flexible data-rate support enabled.
#define TWAI1_MODE_SETTINGS_FDE_MASK 0x10u
#define TWAI1_MODE_SETTINGS_TTTM_POS 5   // Time triggered transmission mode. 0b0 - TTTM_DISABLED - 0b1 - TTTM_ENABLED -
#define TWAI1_MODE_SETTINGS_TTTM_MASK 0x20u
#define TWAI1_MODE_SETTINGS_ROM_POS 6   // Restricted operation mode. 0b0 - ROM_DISABLED - Restricted operation mode is disabled. 0b1 - ROM_ENABLED - Restricted operation mode is enabled.
#define TWAI1_MODE_SETTINGS_ROM_MASK 0x40u
#define TWAI1_MODE_SETTINGS_ACF_POS 7   // Acknowledge Forbidden Mode. When enabled, acknowledge is not sent even if received CRC matches the calculated one. 0b0 - ACF_DISABLED - Acknowledge forbidden mode disabled. 0b1 - ACF_ENABLED - Acknowledge forbidden mode enabled.
#define TWAI1_MODE_SETTINGS_ACF_MASK 0x80u
#define TWAI1_MODE_SETTINGS_TSTM_POS 8   // Test Mode. In test mode several registers have special features. Reffer to description of Test mode for further Details.
#define TWAI1_MODE_SETTINGS_TSTM_MASK 0x100u
#define TWAI1_MODE_SETTINGS_RXBAM_POS 9   // RX Buffer automatic mode. 0b0 - RXBAM_DISABLED - 0b1 - RXBAM_ENABLED -
#define TWAI1_MODE_SETTINGS_RXBAM_MASK 0x200u
#define TWAI1_MODE_SETTINGS_TXBBM_POS 10   // TXT Buffer Backup mode; 0b0 - TXBBM_DISABLED - TXT Buffer Backup mode disabled; 0b1 - TXBBM_ENABLED - TXT Buffer Backup mode enabled
#define TWAI1_MODE_SETTINGS_TXBBM_MASK 0x400u
#define TWAI1_MODE_SETTINGS_SAM_POS 11   // Self-acknowledge mode. 0b0 - SAM_DISABLE - Do not send dominant ACK bit when CTU CAN FD sends Acknowledge bit. 0b1 - SAM_ENABLE - Send dominant ACK bit when CTU CAN FD transmits CAN frame.
#define TWAI1_MODE_SETTINGS_SAM_MASK 0x800u
#define TWAI1_MODE_SETTINGS_RTRLE_POS 16   // Retransmitt Limit Enable. If enabled, CTU CAN FD only attempts to retransmitt each frame up to RTR_TH times. 0b0 - RTRLE_DISABLED - Retransmitt limit is disabled. 0b1 - RTRLE_ENABLED - Retransmitt limit is enabled.
#define TWAI1_MODE_SETTINGS_RTRLE_MASK 0x10000ul
#define TWAI1_MODE_SETTINGS_RTRTH_POS 17   // Retransmitt Limit Threshold. Maximal amount of retransmission attempts when SETTINGS[RTRLE] is en- Abled.
#define TWAI1_MODE_SETTINGS_RTRTH_MASK 0x1e0000ul
#define TWAI1_MODE_SETTINGS_RTRTH(value) ((((unsigned long)(value)) << 17) & TWAI1_MODE_SETTINGS_RTRTH_MASK)
#define TWAI1_MODE_SETTINGS_ILBP_POS 21   // Internal Loop Back mode. When enabled, CTU CAN FD receives any frame it transmitts. 0b0 - INT_LOOP_DISABLED - Internal loop-back is disabled. 0b1 - INT_LOOP_ENABLED - Internal loop-back is enabled.
#define TWAI1_MODE_SETTINGS_ILBP_MASK 0x200000ul
#define TWAI1_MODE_SETTINGS_ENA_POS 22   // Main enable bit of CTU CAN FD. When enabled, CTU CAN FD communicates on CAN bus. When disabled, it is bus-off and does not take part of CAN bus communication. 0b0 - CTU_CAN_DISABLED - The CAN Core is disabled. 0b1 - CTU_CAN_ENABLED - The CAN Core is enabled.
#define TWAI1_MODE_SETTINGS_ENA_MASK 0x400000ul
#define TWAI1_MODE_SETTINGS_NISOFD_POS 23   // Non ISO FD. When this bit is set, CTU CAN FD is compliant to NON-ISO CAN FD specification (no stuff count field). This bit should be modified only when SETTINGS[ENA]=0. 0b0 - ISO_FD - The CAN Controller conforms to ISO CAN FD specification. 0b1 - NON_ISO_FD - The CAN Controller conforms to NON ISO CAN FD specification. CANFD 1.0
#define TWAI1_MODE_SETTINGS_NISOFD_MASK 0x800000ul
#define TWAI1_MODE_SETTINGS_PEX_POS 24   // Protocol exception handling. When this bit is set, CTU CAN FD will start integration upon detection of protocol exception. This should be modified only when SETTINGS[ENA] = ’0’. 0b0 - PROTOCOL_EXCEPTION_DISABLED - Protocol exception handling is disabled. 0b1 - PROTOCOL_EXCEPTION_ENABLED - Protocol exception handling is enabled.
#define TWAI1_MODE_SETTINGS_PEX_MASK 0x1000000ul
#define TWAI1_MODE_SETTINGS_TBFBO_POS 25   // All TXT buffers shall go to "TX failed" state when CTU CAN FD becomes bus-off. 0b0 - TXTBUF_FAILED_BUS_OFF_DISABLED - TXT Buffers dont go to "TX failed" state when CTU CAN FD becomes bus-off. 0b1 - TXTBUF_FAILED_BUS_OFF_ENABLED - TXT Buffers go to "TX failed" state when CTU CAN FD becomes bus-off.
#define TWAI1_MODE_SETTINGS_TBFBO_MASK 0x2000000ul
#define TWAI1_MODE_SETTINGS_FDRF_POS 26   // Frame filters drop Remote frames. 0b0 - DROP_RF_DISABLED - Frame filters accept RTR frames. 0b1 - DROP_RF_ENABLED - Frame filters drop RTR frames.
#define TWAI1_MODE_SETTINGS_FDRF_MASK 0x4000000ul
#define TWAI1_MODE_SETTINGS_PCHKE_POS 27   // Enable Parity checks in TXT Buffers and RX Buffer.
#define TWAI1_MODE_SETTINGS_PCHKE_MASK 0x8000000ul

// TWAI1_STATUS: TWAI FD status register (read-write, reset 0x00070084)
#define TWAI1_STATUS_ADDRESS 0x6000d008ul
#define TWAI1_STATUS (*(volatile uint32_t *)0x6000d008ul)
#define TWAI1_STATUS_RXNE_POS 0   // RX buffer not empty. This bit is 1 when least one frame is stored in RX buffer. 0: empty 1: not empty (read-only)
#define TWAI1_STATUS_RXNE_MASK 0x1u
#define TWAI1_STATUS_DOR_POS 1   // Data Overrun flag. This bit is set when frame was dropped due to lack of space in RX buffer. This bit can be cleared by COMMAND[RRB]. 0: not overrun 1: overrun (read-only)
#define TWAI1_STATUS_DOR_MASK 0x2u
#define TWAI1_STATUS_TXNF_POS 2   // TXT buffers status. This bit is set if at least one TXT buffer is in "Empty" state. 0: not full 1: full (read-only)
#define TWAI1_STATUS_TXNF_MASK 0x4u
#define TWAI1_STATUS_EFT_POS 3   // Error frame is being transmitted at the moment. 0: not being transmitted 1: being transmitted (read-only)
#define TWAI1_STATUS_EFT_MASK 0x8u
#define TWAI1_STATUS_RXS_POS 4   // CTU CAN FD is receiver of CAN Frame. 0: not receiving 1: receiving (read-only)
#define TWAI1_STATUS_RXS_MASK 0x10u
#define TWAI1_STATUS_TXS_POS 5   // CTU CAN FD is transmitter of CAN Frame. 0: not transmitting 1: transmitting (read-only)
#define TWAI1_STATUS_TXS_MASK 0x20u
#define TWAI1_STATUS_EWL_POS 6   // TX Error counter (TEC) or RX Error counter (REC) is equal to, or higher than Error warning limit (EWL). 0: not reached 1: reached (read-only)
#define TWAI1_STATUS_EWL_MASK 0x40u
#define TWAI1_STATUS_IDLE_POS 7   // Bus is idle (no frame is being transmitted/received) or CTU CAN FD is bus-off. 0: active 1: not active (read-only)
#define TWAI1_STATUS_IDLE_MASK 0x80u
#define TWAI1_STATUS_PEXS_POS 8   // Protocol exception status (flag). Set when Protocol exception occurs. Cleared by writing COMMAND[CPEXS]=1. (read-only)
#define TWAI1_STATUS_PEXS_MASK 0x100u
#define TWAI1_STATUS_RXPE_POS 9   // Set when parity error is detected during read of CAN frame from RX Buffer via RX_DATA register. (read-only)
#define TWAI1_STATUS_RXPE_MASK 0x200u
#define TWAI1_STATUS_TXPE_POS 10   // TXT Buffers Parity Error flag. Set When Parity Error is detected in a TXT Buffer during transmission from this Buffer. (read-only)
#define TWAI1_STATUS_TXPE_MASK 0x400u
#define TWAI1_STATUS_TXDPE_POS 11   // TXT Buffer double parity error. Set in TXT Buffer Backup mode when parity error is detected in "backup" TXT Buffer. (read-only)
#define TWAI1_STATUS_TXDPE_MASK 0x800u
#define TWAI1_STATUS_STCNT_POS 16   // Support of Traffic counters. When this bit is 1, Traffic counters are present. (read-only)
#define TWAI1_STATUS_STCNT_MASK 0x10000ul
#define TWAI1_STATUS_STRGS_POS 17   // Support of Test Registers for memory testability. When this bit is 1, Test Registers are present. (read-only)
#define TWAI1_STATUS_STRGS_MASK 0x20000ul
#define TWAI1_STATUS_SPRT_POS 18   // Support of Parity protection on each word of TXT Buffer RAM and RX Buffer RAM. (read-only)
#define TWAI1_STATUS_SPRT_MASK 0x40000ul

// TWAI1_COMMAND: TWAI FD command register (read-write, reset 0x00000000)
#define TWAI1_COMMAND_ADDRESS 0x6000d00cul
#define TWAI1_COMMAND (*(volatile uint32_t *)0x6000d00cul)
#define TWAI1_COMMAND_RXRPMV_POS 1   // RX Buffer read pointer move. (write-only)
#define TWAI1_COMMAND_RXRPMV_MASK 0x2u
#define TWAI1_COMMAND_RRB_POS 2   // Release RX Buffer. This command flushes RX buffer and resets its memory pointers. 0: invalid 1: delete (write-only)
#define TWAI1_COMMAND_RRB_MASK 0x4u
#define TWAI1_COMMAND_CDO_POS 3   // Clear Data Overrun flag in RX buffer. 0: invalid 1: clear (write-only)
#define TWAI1_COMMAND_CDO_MASK 0x8u
#define TWAI1_COMMAND_ERCRST_POS 4   // Error Counters Reset. When unit is bus off, issuing this command will request erasing TEC, REC counters after 128 consecutive ocurrences of 11 recessive bits. Upon completion, TEC and REC are erased and fault confinement State is set to error-active. When unit is not bus-off, or when unit is bus-off due to being disabled (SETTINGS[ENA] = ’0’), this command has no effect. (write-only)
#define TWAI1_COMMAND_ERCRST_MASK 0x10u
#define TWAI1_COMMAND_RXFCRST_POS 5   // Clear RX bus traffic counter (RX_COUNTER register). (write-only)
#define TWAI1_COMMAND_RXFCRST_MASK 0x20u
#define TWAI1_COMMAND_TXFCRST_POS 6   // Clear TX bus traffic counter (TX_COUNTER register). (write-only)
#define TWAI1_COMMAND_TXFCRST_MASK 0x40u
#define TWAI1_COMMAND_CPEXS_POS 7   // Clear Protocol exception status (STATUS[PEXS]). (write-only)
#define TWAI1_COMMAND_CPEXS_MASK 0x80u
#define TWAI1_COMMAND_CRXPE_POS 8   // Clear STATUS[RXPE] flag. (write-only)
#define TWAI1_COMMAND_CRXPE_MASK 0x100u
#define TWAI1_COMMAND_CTXPE_POS 9   // Clear STATUS[TXPE] flag. (write-only)
#define TWAI1_COMMAND_CTXPE_MASK 0x200u
#define TWAI1_COMMAND_CTXDPE_POS 10   // Clear STATUS[TXDPE] flag. (write-only)
#define TWAI1_COMMAND_CTXDPE_MASK 0x400u

// TWAI1_INT_STAT: TWAI FD command register (read-write, reset 0x00000000)
#define TWAI1_INT_STAT_ADDRESS 0x6000d010ul
#define TWAI1_INT_STAT (*(volatile uint32_t *)0x6000d010ul)
#define TWAI1_INT_STAT_RXI_INT_ST_POS 0   // The masked interrupt status of TWAIFD_RXI_INT. Frame received interrupt.
#define TWAI1_INT_STAT_RXI_INT_ST_MASK 0x1u
#define TWAI1_INT_STAT_TXI_INT_ST_POS 1   // The masked interrupt status of TWAIFD_TXI_INT. Frame transmitted interrupt.
#define TWAI1_INT_STAT_TXI_INT_ST_MASK 0x2u
#define TWAI1_INT_STAT_EWLI_INT_ST_POS 2   // The masked interrupt status of TWAIFD_EWLI_INT. Error warning limit interrupt. When both TEC and REC are lower than EWL and one of the becomes equal to or higher than EWL, or when both TEC and REC become less than EWL, this interrupt is generated. When Interrupt is cleared and REC, or TEC is still equal to or higher than EWL, Interrupt is not generated again.
#define TWAI1_INT_STAT_EWLI_INT_ST_MASK 0x4u
#define TWAI1_INT_STAT_DOI_INT_ST_POS 3   // The masked interrupt status of TWAIFD_DOI_INT. Data overrun interrupt. Before this Interrupt is cleared , STATUS[DOR] must be cleared to avoid setting of this Interrupt again.
#define TWAI1_INT_STAT_DOI_INT_ST_MASK 0x8u
#define TWAI1_INT_STAT_FCSI_INT_ST_POS 4   // The masked interrupt status of TWAIFD_FCSI_INT. Fault confinement state changed interrupt. Interrupt is set when node turns error-passive (from error-active), bus-off (from error-passive) or error-active (from bus-off after reintegration or from error-passive).
#define TWAI1_INT_STAT_FCSI_INT_ST_MASK 0x10u
#define TWAI1_INT_STAT_ALI_INT_ST_POS 5   // The masked interrupt status of TWAIFD_ALI_INT. Arbitration lost interrupt.
#define TWAI1_INT_STAT_ALI_INT_ST_MASK 0x20u
#define TWAI1_INT_STAT_BEI_INT_ST_POS 6   // The masked interrupt status of TWAIFD_BEI_INT. Bus error interrupt.
#define TWAI1_INT_STAT_BEI_INT_ST_MASK 0x40u
#define TWAI1_INT_STAT_OFI_INT_ST_POS 7   // The masked interrupt status of TWAIFD_OFI_INT. Overload frame interrupt.
#define TWAI1_INT_STAT_OFI_INT_ST_MASK 0x80u
#define TWAI1_INT_STAT_RXFI_INT_ST_POS 8   // The masked interrupt status of TWAIFD_RXFI_INT. RX buffer full interrupt.
#define TWAI1_INT_STAT_RXFI_INT_ST_MASK 0x100u
#define TWAI1_INT_STAT_BSI_INT_ST_POS 9   // The masked interrupt status of TWAIFD_BSI_INT. Bit rate shifted interrupt.
#define TWAI1_INT_STAT_BSI_INT_ST_MASK 0x200u
#define TWAI1_INT_STAT_RBNEI_INT_ST_POS 10   // The masked interrupt status of TWAIFD_RBNEI_INT. RX buffer not empty interrupt. Clearing this interrupt and not reading out content of RX Buffer via RX_DATA will re-activate the interrupt.
#define TWAI1_INT_STAT_RBNEI_INT_ST_MASK 0x400u
#define TWAI1_INT_STAT_TXBHCI_INT_ST_POS 11   // The masked interrupt status of TWAIFD_TXBHCI_INT. TXT buffer HW command interrupt. Anytime TXT buffer receives HW command from CAN Core which changes TXT buffer state to "TX OK", "Error" or "Aborted", this interrupt will be generated.
#define TWAI1_INT_STAT_TXBHCI_INT_ST_MASK 0x800u

