#define TWAI1_INT_ENA_SET_RBNEI_INT_ENA_MASK_POS 10   // Write 1 to enable TWAIFD_RBNEI_INT.
#define TWAI1_INT_ENA_SET_RBNEI_INT_ENA_MASK_MASK 0x400u
#define TWAI1_INT_ENA_SET_TXBHCI_INT_ENA_MASK_POS 11   // Write 1 to enable TWAIFD_TXBHCI_INT.
#define TWAI1_INT_ENA_SET_TXBHCI_INT_ENA_MASK_MASK 0x800u

