#define TWAI1_RX_STATUS_RX_SETTINGS_RTSOP_POS 16   // Receive buffer timestamp option. This register should be modified only when SETTINGS[ENA]=0. 0b0 - RTS_END - Timestamp of received frame in RX FIFO is captured in last bit of EOF field. 0b1 - RTS_BEG - Timestamp of received frame in RX FIFO is captured in SOF field.
#define TWAI1_RX_STATUS_RX_SETTINGS_RTSOP_MASK 0x10000ul

