// TWAI1_TX_STATUS: TWAI FD TX buffer status register (read-write, reset 0x00008888)
#define TWAI1_TX_STATUS_ADDRESS 0x6000d070ul
#define TWAI1_TX_STATUS (*(volatile uint32_t *)0x6000d070ul)
#define TWAI1_TX_STATUS_TXTB0_STATE_POS 0   // Status of TXT buffer 1. 0b0000 - TXT_NOT_EXIST - TXT buffer does not exist in the core (applies only to TXT buffers 3-8, when CTU CAN FD was synthesized with less than 8 TXT buffers). 0b0001 - TXT_RDY - TXT buffer is in "Ready" state, it is waiting for CTU CAN FD to start transmission from it. 0b0010 - TXT_TRAN - TXT buffer is in "TX in progress" state. CTU CAN FD is transmitting frame. 0b0011 - TXT_ABTP - TXT buffer is in "Abort in progress" state. 0b0100 - TXT_TOK - TXT buffer is in "TX OK" state. 0b0110 - TXT_ERR - TXT buffer is in "Failed" state. 0b0111 - TXT_ABT - TXT buffer is in "Aborted" state. 0b1000 - TXT_ETY - TXT buffer is in "Empty" state. (read-only)
#define TWAI1_TX_STATUS_TXTB0_STATE_MASK 0xfu
#define TWAI1_TX_STATUS_TXTB0_STATE(value) ((((unsigned long)(value)) << 0) & TWAI1_TX_STATUS_TXTB0_STATE_MASK)
#define TWAI1_TX_STATUS_TX2S_POS 4   // Status of TXT buffer 2. Bit field meaning is analogous to TX1S. (read-only)
#define TWAI1_TX_STATUS_TX2S_MASK 0xf0u
#define TWAI1_TX_STATUS_TX2S(value) ((((unsigned long)(value)) << 4) & TWAI1_TX_STATUS_TX2S_MASK)
#define TWAI1_TX_STATUS_TX3S_POS 8   // Status of TXT buffer 3. Bit field meaning is analogous to TX1S. (read-only)
#define TWAI1_TX_STATUS_TX3S_MASK 0xf00u
#define TWAI1_TX_STATUS_TX3S(value) ((((unsigned long)(value)) << 8) & TWAI1_TX_STATUS_TX3S_MASK)
#define TWAI1_TX_STATUS_TX4S_POS 12   // Status of TXT buffer 4. Bit field meaning is analogous to TX1S. (read-only)
#define TWAI1_TX_STATUS_TX4S_MASK 0xf000u
#define TWAI1_TX_STATUS_TX4S(value) ((((unsigned long)(value)) << 12) & TWAI1_TX_STATUS_TX4S_MASK)
#define TWAI1_TX_STATUS_TX5S_POS 16   // Status of TXT buffer 5. Bit field meaning is analogous to TX1S. (read-only)
#define TWAI1_TX_STATUS_TX5S_MASK 0xf0000ul
#define TWAI1_TX_STATUS_TX5S(value) ((((unsigned long)(value)) << 16) & TWAI1_TX_STATUS_TX5S_MASK)
#define TWAI1_TX_STATUS_TX6S_POS 20   // Status of TXT buffer 6. Bit field meaning is analogous to TX1S. (read-only)
#define TWAI1_TX_STATUS_TX6S_MASK 0xf00000ul
#define TWAI1_TX_STATUS_TX6S(value) ((((unsigned long)(value)) << 20) & TWAI1_TX_STATUS_TX6S_MASK)
#define TWAI1_TX_STATUS_TX7S_POS 24   // Status of TXT buffer 7. Bit field meaning is analogous to TX1S. (read-only)
