#define TWAI1_TX_COMMAND_TXTB_INFO_TXB2_POS 9   // Command is issued to TXT Buffer 2. (write-only)
#define TWAI1_TX_COMMAND_TXTB_INFO_TXB2_MASK 0x200u
#define TWAI1_TX_COMMAND_TXTB_INFO_TXB3_POS 10   // Command is issued to TXT Buffer 3. If number of TXT Buffers is less than 3, this field is reserved and has no Function. (write-only)
