#define TWAI1_TX_COMMAND_TXTB_INFO_TXB7_POS 14   // Command is issued to TXT Buffer 7. If number of TXT Buffers is less than 7, this field is reserved and has no Function. (write-only)
#define TWAI1_TX_COMMAND_TXTB_INFO_TXB7_MASK 0x4000u
#define TWAI1_TX_COMMAND_TXTB_INFO_TXB8_POS 15   // Command is issued to TXT Buffer 8. If number of TXT Buffers is less than 8, this field is reserved and has no Function. (write-only)
