// TWAI1_DEBUG: TWAI FD debug register (read-write, reset 0x00000000)
#define TWAI1_DEBUG_ADDRESS 0x6000d08cul
#define TWAI1_DEBUG (*(volatile uint32_t *)0x6000d08cul)
#define TWAI1_DEBUG_STUFF_COUNT_POS 0   // Actual stuff count modulo 8 as definned in ISO FD protocol. Stuff count is erased in the beginning of CAN frame and increased by one with each stuff bit until Stuff count field in ISO FD frame. Then it stays fixed until the beginning of next frame. In non-ISO FD or normal CAN stuff bits are counted until the end of a frame. Note that this field is NOT gray encoded as defined in ISO FD standard. Stuff count is calculated only as long as controller is transceiving on the bus. During the reception this value remains fixed! (read-only)
#define TWAI1_DEBUG_STUFF_COUNT_MASK 0x7u
#define TWAI1_DEBUG_STUFF_COUNT(value) ((((unsigned long)(value)) << 0) & TWAI1_DEBUG_STUFF_COUNT_MASK)
#define TWAI1_DEBUG_DESTUFF_COUNT_POS 3   // Actual de-stuff count modulo 8 as defined in ISO FD protocol. De-Stuff count is erased in the beginning of the frame and increased by one with each de-stuffed bit until Stuff count field in ISO FD Frame. Then it stays fixed until beginning of next frame. In non-ISO FD or normal CAN de-stuff bits are counted until the end of the frame. Note that this field is NOT grey encoded as defined in ISO FD standard. De-stuff count is calculated in both. Transceiver as well as receiver. (read-only)
#define TWAI1_DEBUG_DESTUFF_COUNT_MASK 0x38u
#define TWAI1_DEBUG_DESTUFF_COUNT(value) ((((unsigned long)(value)) << 3) & TWAI1_DEBUG_DESTUFF_COUNT_MASK)
#define TWAI1_DEBUG_PC_ARB_POS 6   // Protocol control state machine is in Arbitration field. (read-only)
#define TWAI1_DEBUG_PC_ARB_MASK 0x40u
#define TWAI1_DEBUG_PC_CON_POS 7   // Protocol control state machine is in Control field. (read-only)
#define TWAI1_DEBUG_PC_CON_MASK 0x80u
#define TWAI1_DEBUG_PC_DAT_POS 8   // Protocol control state machine is in Data field. (read-only)
#define TWAI1_DEBUG_PC_DAT_MASK 0x100u
#define TWAI1_DEBUG_PC_STC_POS 9   // Protocol control state machine is in Stuff Count field. (read-only)
#define TWAI1_DEBUG_PC_STC_MASK 0x200u
#define TWAI1_DEBUG_PC_CRC_POS 10   // Protocol control state machine is in CRC field. (read-only)
#define TWAI1_DEBUG_PC_CRC_MASK 0x400u
#define TWAI1_DEBUG_PC_CRCD_POS 11   // Protocol control state machine is in CRC Delimiter field. (read-only)
#define TWAI1_DEBUG_PC_CRCD_MASK 0x800u
#define TWAI1_DEBUG_PC_ACK_POS 12   // Protocol control state machine is in ACK field. (read-only)
#define TWAI1_DEBUG_PC_ACK_MASK 0x1000u
#define TWAI1_DEBUG_PC_ACKD_POS 13   // Protocol control state machine is in ACK Delimiter field. (read-only)
#define TWAI1_DEBUG_PC_ACKD_MASK 0x2000u
#define TWAI1_DEBUG_PC_EOF_POS 14   // Protocol control state machine is in End of file field. (read-only)
#define TWAI1_DEBUG_PC_EOF_MASK 0x4000u
#define TWAI1_DEBUG_PC_INT_POS 15   // Protocol control state machine is in Intermission field. (read-only)
#define TWAI1_DEBUG_PC_INT_MASK 0x8000u
#define TWAI1_DEBUG_PC_SUSP_POS 16   // Protocol control state machine is in Suspend transmission field. (read-only)
#define TWAI1_DEBUG_PC_SUSP_MASK 0x10000ul
#define TWAI1_DEBUG_PC_OVR_POS 17   // Protocol control state machine is in Overload field. (read-only)
