#define CLIC_INT_CTRL46_SHV_POS 16   // vectored: through mtvt's table, not the trap entry
#define CLIC_INT_CTRL46_SHV_MASK 0x10000ul
#define CLIC_INT_CTRL46_IE_POS 8   // enabled
#define CLIC_INT_CTRL46_IE_MASK 0x100u
#define CLIC_INT_CTRL46_IP_POS 0   // pending (an edge-triggered one is cleared by writing 0)
#define CLIC_INT_CTRL46_IP_MASK 0x1u

// CLIC_INT_CTRL47: an interrupt's pending, enable, attributes and level (read-write)
#define CLIC_INT_CTRL47_ADDRESS 0x208010bcul
#define CLIC_INT_CTRL47 (*(volatile uint32_t *)0x208010bcul)
#define CLIC_INT_CTRL47_CTL_POS 24   // level and priority
#define CLIC_INT_CTRL47_CTL_MASK 0xff000000ul
#define CLIC_INT_CTRL47_CTL(value) ((((unsigned long)(value)) << 24) & CLIC_INT_CTRL47_CTL_MASK)
#define CLIC_INT_CTRL47_MODE_POS 22   // privilege mode
#define CLIC_INT_CTRL47_MODE_MASK 0xc00000ul
#define CLIC_INT_CTRL47_MODE(value) ((((unsigned long)(value)) << 22) & CLIC_INT_CTRL47_MODE_MASK)
#define CLIC_INT_CTRL47_MODE_USER (0x0u << 22)
#define CLIC_INT_CTRL47_MODE_MACHINE (0x3u << 22)
#define CLIC_INT_CTRL47_TRIG_POS 17   // bit 17: edge (1) or level (0); bit 18: falling (1) or rising (0) edge
#define CLIC_INT_CTRL47_TRIG_MASK 0x60000ul
#define CLIC_INT_CTRL47_TRIG(value) ((((unsigned long)(value)) << 17) & CLIC_INT_CTRL47_TRIG_MASK)
#define CLIC_INT_CTRL47_TRIG_LEVEL (0x0u << 17)
#define CLIC_INT_CTRL47_TRIG_RISING (0x1u << 17)
#define CLIC_INT_CTRL47_TRIG_FALLING (0x3u << 17)
#define CLIC_INT_CTRL47_SHV_POS 16   // vectored: through mtvt's table, not the trap entry
#define CLIC_INT_CTRL47_SHV_MASK 0x10000ul
#define CLIC_INT_CTRL47_IE_POS 8   // enabled
#define CLIC_INT_CTRL47_IE_MASK 0x100u
#define CLIC_INT_CTRL47_IP_POS 0   // pending (an edge-triggered one is cleared by writing 0)
#define CLIC_INT_CTRL47_IP_MASK 0x1u

// ---- Constants

#define LP_WDT_WKEY_VALUE 0x50d83aa1ul   // LP_WDT_WPROTECT's key
#define LP_WDT_SWD_WKEY_VALUE 0x50d83aa1ul   // LP_WDT_SWD_WPROTECT's key
#define TIMG_WDT_WKEY_VALUE 0x50d83aa1ul   // a timer group's WDTWPROTECT key
#define CLIC_INTERRUPTS 0x30u   // the CLIC's interrupt ids
#define CLIC_EXT_INTR_NUM_OFFSET 0x10u   // the CLIC id of the CPU interrupt line 0
#define INTERRUPT_SOURCES 0x54u   // the interrupt matrix's sources (ETS_MAX_INTR_SOURCE)
#define ROM_RESERVED_START 0x4085c5a0ul   // the ROM's stack, .bss and .data while it boots, to SRAM's end
#define BOOTLOADER_FLASH_OFFSET 0x2000u   // where the ROM reads the image in flash
#define IMAGE_CHIP_ID 0x17u   // the image header's chip id (esptool)

#endif // ESP32C5_REGISTERS_H
